insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('guatemala-city-guatemala', '10S', 'Guatemala City', 'Guatemala', '*If it''s the first breath of Guatemala', 'live', 'verified', 'kyoto', 'Guatemala', '{"culture"}', '{}', '{"essential","comfort","premier","ultra"}', null, null, '{"key_facts":["La Aurora (GUA/MGGT) is Guatemala''s primary international gateway, 4th-busiest in Central America, 4,919,850 pax in 2024, direct US links via AA/UA/DL + Avianca hub.","City runs a numbered-zone system; traveler-relevant zones are Zone 1 (historic core), Zone 10 ''Zona Viva'' (hotels/dining/museums), Zone 13 (airport + museum row).","Antigua Guatemala is ~45–60 min (~40–45 km) by road; GC functions primarily as a transfer point to Antigua/Atitlán/Tikal.","Museum cluster is first-rate: Museo Popol Vuh (best pre-Hispanic/colonial art) + Museo Ixchel (~8,000 textiles, 180+ communities), both on the UFM campus in Zone 10.","Safety is zone-specific: US Level 3; Zone 18 + Villa Nueva are Level 4 ''Do Not Travel''; Zones 10/14, Zone 1 core, and Cayalá (Zone 16, safest) are where visitors stay."],"safety":{"emergency":"Police 110 · Fire/Ambulance 122 (also 123) · Red Cross 125 · PROATUR tourist assistance 1500 (from abroad +502 2290 2810)","hospital":"Hospital Herrera Llerandi (6a. Avenida 8-71, Zona 10; +502 2384-5959) — Forbes-recognized best hospital in Guatemala, CAP-accredited; Centro Médico + Hospital Universitario tier; GC is the national medical + medevac hub","book_enabled":true,"book_enabled_note":"BOOK WITH WARNING (Four-Bin v3) — founder-blessed as bookable-with-warning; booking enabled with mandatory full-advisory disclosure","consent_flow":{"bin":"BOOK WITH WARNING","disclosure_required":true,"renders":"full verbatim live US State Dept advisory for the country (level + reason + named-danger areas + complete ''If you decide to travel'' guidance), pulled live, plus traveler acknowledgment","wording_status":"hook set only — final consent language PENDING compliance-attorney sign-off"},"l3_disclosure":true,"in_city_nogo":"Zone 18 + Villa Nueva","state_dept_carveout":"airport Zone 13 + Zona Viva Zones 10/14 + Zone 1 historic safe; NEVER route to Zone 18 or Villa Nueva","stay_in_zone":true,"air_access_verified":"La Aurora International Airport (GUA / MGGT)","urban_crime":"vetted taxi/Uber only, no street-hailing; no night walking in unfamiliar zones","health":"dengue precautions; bottled water only","water":"bottled only"},"timing":{"demand_type":"derivative","curve_driver":"onward anchors (Antigua/Atitlán/Tikal) + country dry season Nov–Mar","inflection":"early-to-mid October","peak":"November–March + Semana Santa (late Mar / Apr)","shoulder_green":"May–October (rainy season)","booking_lead":"2–4 months dry season; 5–6+ months Semana Santa","events":["Semana Santa / Holy Week (movable, late Mar / Apr)"],"fire_date":"2026-09-20","fire_date_note":"gateway-booking window = curve-start (~mid-Oct) minus 1–2 weeks; lock GC beds + vetted transfers ahead of anchor demand. Semana Santa sub-fire Oct–Nov. Sharpen on live gateway tracking.","confidence":"medium-derived"},"jewels":[{"name":"Museo Popol Vuh","si_tag":"culture","zone":"10 (UFM)","tier":"comfort","commission_path":"admission non-commissionable → bundle into commissioned DMC city tour","source":"https://en.wikipedia.org/wiki/Universidad_Francisco_Marroqu%C3%ADn (Accessed 2026-07-06)","timing":"November–March + Semana Santa","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"\"one of the best collections of pre-Hispanic and colonial art in the country.\"","si":"culture","blurb":"\"one of the best collections of pre-Hispanic and colonial art in the country.\"","when":"November–March + Semana Santa","commission":"admission non-commissionable → bundle into commissioned DMC city tour","accessed":"2026-07-06"},{"name":"Museo Ixchel del Traje Indígena","si_tag":"culture","zone":"10 (UFM)","tier":"comfort","commission_path":"admission non-commissionable → guided textile tour + Antigua/Atitlán artisan retail linkage","source":"https://museoixchel.org/en/museo-ixchel-english/ (Accessed 2026-07-06)","timing":"November–March + Semana Santa","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"~8,000 textile pieces from 180+ Indigenous communities; huipiles, cortes, ceremonial garments; open Mon–Fri 9–5, Sat 9–1","si":"culture","blurb":"~8,000 textile pieces from 180+ Indigenous communities; huipiles, cortes, ceremonial garments; open Mon–Fri 9–5, Sat 9–1","when":"November–March + Semana Santa","commission":"admission non-commissionable → guided textile tour + Antigua/Atitlán artisan retail linkage","accessed":"2026-07-06"},{"name":"Museo Nacional de Arqueología y Etnología","si_tag":"culture","zone":"13","tier":"essential","commission_path":"bundle into DMC city tour","source":"https://en.wikipedia.org/wiki/Guatemala_City (Accessed 2026-07-06)","timing":"November–March + Semana Santa","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"November–March + Semana Santa","commission":"bundle into DMC city tour","accessed":"2026-07-06"},{"name":"Zone 1 Historic Center (Palacio Nacional, Cathedral, Mercado Central)","si_tag":"culture","zone":"1","tier":"essential","commission_path":"commissioned daytime historic-center walking tour via DMC","source":"https://en.wikipedia.org/wiki/Guatemala_City (Accessed 2026-07-06)","timing":"year-round","timing_type":"ALWAYS-ON","hook":"the founding civic core: National Palace, Cathedral, and the underground artisan market","si":"culture","blurb":"the founding civic core: National Palace, Cathedral, and the underground artisan market","when":"year-round","commission":"commissioned daytime historic-center walking tour via DMC","accessed":"2026-07-06"},{"name":"Paseo Cayalá / Ciudad Cayalá","si_tag":"Lifestyle/Dining","zone":"16","tier":"comfort","commission_path":"non-bookable district → hotel night + DMC evening transfer","source":"https://livinginguatemala.com/neighborhoods/zona-16-cayala/ (Accessed 2026-07-06)","timing":"November–March + Semana Santa","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Lifestyle/Dining","when":"November–March + Semana Santa","commission":"non-bookable district → hotel night + DMC evening transfer","accessed":"2026-07-06"},{"name":"Zona Viva dining","si_tag":"Lifestyle/Dining","zone":"10","tier":"comfort","commission_path":"hotel-package upsell","source":"https://en.wikipedia.org/wiki/Guatemala_City (Accessed 2026-07-06)","timing":"November–March + Semana Santa","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Lifestyle/Dining","when":"November–March + Semana Santa","commission":"hotel-package upsell","accessed":"2026-07-06"},{"name":"Antigua Guatemala transfer/day-trip","si_tag":"Culture & Heritage / Adventure","zone":"onward (~45 min)","tier":"comfort","commission_path":"commissioned DMC transfer + Antigua land package (primary revenue move)","source":"https://www.lonelyplanet.com/articles/best-time-to-visit-guatemala (Accessed 2026-07-06)","timing":"November–March + Semana Santa","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"colonial UNESCO city; the real reason GC exists as a gateway","si":"Culture & Heritage / Adventure","blurb":"colonial UNESCO city; the real reason GC exists as a gateway","when":"November–March + Semana Santa","commission":"commissioned DMC transfer + Antigua land package (primary revenue move)","accessed":"2026-07-06"},{"name":"Pacaya Volcano day-trip","si_tag":"adventure","zone":"onward (~1.5–2 hr)","tier":"essential","commission_path":"commissioned DMC guided excursion","source":"https://www.martsam.com/ (Accessed 2026-07-06)","timing":"November–March + Semana Santa","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"adventure","when":"November–March + Semana Santa","commission":"commissioned DMC guided excursion","accessed":"2026-07-06"},{"name":"La Aurora Zoo","si_tag":"Family/Layover","zone":"13","tier":"essential","commission_path":"non-commissionable admission; long-layover add-on","source":"https://en.wikipedia.org/wiki/Guatemala_City (Accessed 2026-07-06)","si":"Family/Layover","commission":"non-commissionable admission; long-layover add-on","accessed":"2026-07-06"}],"faq":[{"q":"Should I stay in Guatemala City or head straight to Antigua?","a":"Treat Guatemala City as a 1–2-night stopover, not a leisure anchor. It''s the international gateway — La Aurora (Central America''s 4th-busiest, 4,919,850 pax in 2024) sits in Zone 13, ~45–60 minutes (~40–45 km) from Antigua — so most travelers rest a night, then road out to the country''s true anchors.","source":"en.wikipedia.org, Accessed 2026-07-06","si_tag":null},{"q":"Is Guatemala City worth a stop for museums?","a":"Yes, for a half-day. The museum cluster is genuinely first-rate: Museo Popol Vuh holds one of the country''s best pre-Hispanic and colonial-art collections, and Museo Ixchel holds ~8,000 textile pieces from 180+ Indigenous communities, both on the UFM campus in the safe Zone 10.","source":"museoixchel.org, Accessed 2026-07-06","si_tag":"culture"},{"q":"Is Guatemala City safe right now?","a":"Safety is zone-specific, not city-wide. Guatemala is US Level 3, and within the metro Zone 18 and Villa Nueva are Level 4 \"Do Not Travel\" (gang violence, robbery, carjacking, extortion) — TWW never routes there. Visitors stay in Zones 10/14, the Zone 1 core, or Cayalá (Zone 16, rated safest).","source":"travel.state.gov, Accessed 2026-07-06","si_tag":"safety"},{"q":"How do I get from the airport safely?","a":"Use arranged or vetted transport, or Uber — never a street-hailed taxi. Move from La Aurora (Zone 13) to Zone 10/14 lodging on pre-arranged transport, avoid walking at night in unfamiliar zones, and ride the onward Antigua/Atitlán/Tikal handoff on a vetted shuttle or the DMC''s own transport.","source":"travel.state.gov, Accessed 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Guatemala City Travel Guide — La Aurora Gateway, Zona Viva & Safe-Zone Stopover | TravelWell.World","meta_description":"Accurate guide to Guatemala City as the international gateway (GUA) to Antigua, Atitlán & Tikal — Zona Viva stays, museum cluster, safety zones, Level 3 route-around.","search_language":["en","es-GT"],"local_keywords":["qué hacer en Ciudad de Guatemala","Zona Viva hoteles","escala Guatemala City","Museo Ixchel Zona 10","traslado aeropuerto La Aurora a Antigua","zonas seguras Ciudad de Guatemala"],"long_tail_en":["Guatemala City stopover before Antigua","is Guatemala City safe Zona Viva Zone 10","La Aurora airport to Antigua transfer","best hotels Zona Viva Guatemala City","Guatemala travel advisory Zone 18 Villa Nueva"],"hreflang":["en","es-GT"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-06"},"booking":null,"si_checklist_25":null,"sis_present":["Culture & Heritage (future)"],"ultra":[{"property":"Westin Camino Real (Zone 10)","play":"premier gateway night","channel":"Fora/Virtuoso consortia; else GDS commissioned","mor":"Fora advisor","tier":"premier"},{"property":"InterContinental Guatemala (Zone 10)","play":"business-luxury gateway","channel":"IHG consortia / Fora","mor":"Fora/consortia","tier":"premier"},{"property":"Barceló Guatemala City (Zone 10)","play":"upper premier gateway","channel":"consortia / GDS","mor":"consortia","tier":"premier"},{"property":"Hyatt Centric (Zone 10)","play":"lifestyle premier gateway","channel":"Hyatt Privé / Fora","mor":"Fora/Privé","tier":"premier"},{"property":"Antigua boutique-colonial base (REDIRECT)","play":"the true ultra stay — GC is transit","channel":"Fora/Virtuoso Antigua portfolio","mor":"Fora advisor","tier":"ultra"}],"source_verified":"2026-07-06","hero":{"query":"Guatemala City, Guatemala"},"geo":{"lat":14.6349,"lng":-90.5069}}'::jsonb, 45),
  ('holbox-mexico', '10S', 'Holbox', 'Mexico', 'Holbox whale sharks', 'live', 'verified', 'tropicalBeach', 'Quintana Roo (Cancún & Riviera Maya)', '{"expedition","romance","ocean","wildlife"}', '{}', '{"essential","comfort"}', null, null, '{"key_facts":["Whale-shark season mid-May to mid-Sep (official May 15-Sep 17), gov-enforced","Snorkel-only, no-touch; two swimmers + guide per turn; CONANP-certified operators only","Car-free island reached by ferry from Chiquila; golf carts/mopeds only","Bioluminescence at Punta Cocos on dark nights (western tip)","Inside Yum Balam Flora & Fauna Protection Area (~90% of Yucatan endemic birds)"],"safety":{"emergency":"911","hospital":"small local health center on-island; serious cases evac by ferry+road to Cancun private hospitals or air-evac","advisory_level":"L2","malaria":"effectively none in tourist zone","dengue":"active - Quintana Roo among highest-activity states 2026; chikungunya/Zika circulate; mangrove mosquitoes","water":"bottled/purified only","hurricane":"Jun-Nov - overlaps whale-shark peak","whale_shark":"SNORKEL ONLY, no-touch; life jackets typically mandatory; seasickness common (open water); biodegradable reef-safe sunscreen mandatory; CONANP-licensed operator required"},"timing":{"peak":"Dec-Apr (dry high season, northern-winter escape); event peak mid-May-mid-Sep whale sharks (peak Jul-Aug)","shoulder":"May, Jun, Sep (whale sharks present, rainy-season variability, softer rates)","green":"Oct (rainiest, many closures) + late Sep-Nov; November is the underrated value window","booking_window_lead_time":"3-6 months for Dec-Apr peak; tiny boutique inventory; book whale-shark tours ahead in event peak","out_of_season_fill_the_beds":"bioluminescence (new-moon year-round), Cabo Catoche/Isla Pasion boat tours, Yum Balam birding, kite season from Nov, boutique value rates","holiday_event_peaks":"Christmas-New Year, Semana Santa (Easter ~2x February rate), whale-shark peak Jul-Aug","campaign_start_trigger":"whale-shark campaigns Feb-Mar; dry-season/honeymoon campaigns Aug-Oct prior year; Nov green-window value late summer","flag":"whale-shark event peak OVERLAPS hurricane season (Jun-Nov, peak Aug-Oct) - sell with trip insurance + weather caveat","sources":["https://girlonazebra.com/best-time-to-visit-isla-holbox/","https://www.casasandra.com/blog/best-time-to-visit-holbox","https://puntacaliza.com/whale-sharks-in-holbox-best-season-and-tips-for-sightings/","https://www.islaholbox-info.com/en/holbox-island/travel-time-and-climate/"]},"jewels":[{"name":"Whale-shark snorkel aggregation","si_tag":"Global Expedition Adventures","status":"live","tier":"comfort","bookable":"CONANP-licensed full-day snorkel tour","commission_path":"local operator + Olympus/Amstar DMC + Viator affiliate","source":"https://travelyucatan.com/whale-sharks-holbox/","hook":"swim beside the world''s largest fish in a controlled, no-touch encounter","si":"expedition","blurb":"swim beside the world''s largest fish in a controlled, no-touch encounter","commission":"local operator + Olympus/Amstar DMC + Viator affiliate"},{"name":"Punta Cocos bioluminescence night","si_tag":"Romance & Honeymoons","status":"live","tier":"essential","bookable":"guided bioluminescence tour","commission_path":"local operator + Viator affiliate","source":"https://sceneloc8.com/isla-holbox-a-car-free-paradise-of-beaches-and-bioluminescence/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"plankton glow on the western tip on dark, moonless nights","si":"romance","blurb":"plankton glow on the western tip on dark, moonless nights","when":"Dec-Apr","commission":"local operator + Viator affiliate"},{"name":"Cabo Catoche / Isla Pasion three-islands boat tour","si_tag":"Ocean Adventures","status":"future","tier":"comfort","bookable":"boat/snorkel tour","commission_path":"local operator + GYG affiliate","source":"https://www.islaholbox-info.com/en/activities/tours-on-holbox/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","when":"Dec-Apr","commission":"local operator + GYG affiliate"},{"name":"Yum Balam reserve birding + flamingos","si_tag":"Wildlife & Nature","status":"future","tier":"essential","bookable":"eco/kayak tour","commission_path":"local operator + DMC","source":"https://en.wikipedia.org/wiki/Isla_Holbox","hook":"~90% of Yucatán endemic birds; flamingos, crocodiles, in a protected mangrove reserve","si":"wildlife","blurb":"~90% of Yucatán endemic birds; flamingos, crocodiles, in a protected mangrove reserve","commission":"local operator + DMC"}],"faq":[{"q":"Is Holbox safe to visit right now?","a":"Yes — freely bookable, no hold. Holbox is a low-crime, car-free island in Quintana Roo, which carries a standard US State Dept Level 2 \"Exercise Increased Caution\" (maintained 2026-05-29). The main caveat is medical: the island has only a small health center, so serious cases evacuate by ferry and road to Cancún — carry travel medical/evac insurance.","source":"travel.state.gov / mexicotravelandleisure.com, 2026-07-04","si_tag":"safety"},{"q":"What''s the real risk to plan for in Holbox?","a":"Open-water seasickness, mosquitoes and hurricane timing — not crime. Whale-shark boats run into open ocean where swells cause common seasickness (take motion meds 30–60 min before departure); this is a mangrove island so dengue is active (use repellent); and the whale-shark peak (Jul–Aug) overlaps hurricane season (Jun–Nov, peak Aug–Oct), so insure the trip.","source":"mexicowhaleshark.com / travel.state.gov, 2026-07-04","si_tag":"safety"},{"q":"Is swimming with whale sharks in Holbox safe?","a":"Yes — it is tightly regulated for both you and the animal. Only CONANP-certified operators may run tours; it is snorkel-only with no touching, only two swimmers plus a guide enter per turn, and life jackets are typically mandatory on board and in the water. Wear reef-safe biodegradable sunscreen only, applied 30+ minutes before entering.","source":"ovago.com / charlieontravel.com, 2026-07-04","si_tag":"safety"},{"q":"When and how can I swim with whale sharks in Holbox?","a":"Between May 15 and Sep 17, peaking July–August, on a full-day morning boat departure with a CONANP-licensed operator. The encounter is snorkel-only beside the world''s largest fish, with just two swimmers and a guide in the water at a time — book ahead during the event peak, as demand is high and operators are capped.","source":"travelyucatan.com, 2026-07-04","si_tag":"expedition"},{"q":"What is Holbox like as a car-free island?","a":"It is a barefoot sandbar with sand streets and no cars — you arrive by ferry from Chiquilá and move around by golf cart or moped. That car-free rhythm is the point: it is the slow, bohemian antidote to Cancún, built for beach days, bikes and sunsets rather than nightlife strips.","source":"en.wikipedia.org, 2026-07-04","si_tag":"tropical"},{"q":"Is Holbox good for a honeymoon?","a":"Yes, for couples who want quiet design over resort scale. There are no mass all-inclusives — just artist-owned boutiques like Ser Casasandra (17 rooms + 1 villa) and Punta Caliza (12 rooms) — plus bioluminescent night swims at Punta Cocos. Because inventory is tiny, book 3–6 months ahead for the Dec–Apr peak.","source":"casasandra.com / puntacaliza.com, 2026-07-04","si_tag":"romance"},{"q":"What else is there to do in Holbox beyond whale sharks?","a":"Plenty year-round. Walk the bioluminescent shore at Punta Cocos on new-moon nights, take the Cabo Catoche / Isla Pasión \"three islands\" boat-and-snorkel tour, kayak the mangroves, or ride the kite-surf season that starts in November — the reasons to come when the whale sharks are gone.","source":"islaholbox-info.com / sceneloc8.com, 2026-07-04","si_tag":"ocean"},{"q":"What wildlife can I see in the Yum Balam reserve?","a":"A lot — Holbox sits inside the Yum Balam Flora & Fauna Protection Area, home to roughly 90% of the Yucatán''s endemic bird species, plus flamingos, crocodiles and turtles. Guided eco or kayak tours through the protected mangroves are the way to see them; birdlife is seasonal, so ask what''s present at your dates.","source":"en.wikipedia.org, 2026-07-04","si_tag":"wildlife"},{"q":"When is the best time to visit Holbox?","a":"December–April is the dry high season (blue skies, busiest); the whale-shark window is mid-May to mid-September. November is the underrated value pick — dry-season comfort, clean beaches and the start of kite season at low-season prices — while October is rainiest and many venues close. Easter rates run about double February.","source":"girlonazebra.com / islaholbox-info.com, 2026-07-04","si_tag":"planning"}],"seo":{"meta_title":"Holbox Whale Sharks: Car-Free Island Guide","meta_description":"Snorkel with whale sharks off car-free Isla Holbox (mid-May–mid-Sep, no-touch, licensed operators) then walk a bioluminescent shore at Punta Cocos. When and how.","slug":"holbox-mexico","primary_keyword":"Holbox whale sharks","long_tail":["Holbox whale shark season 2026","Holbox bioluminescence Punta Cocos","car-free island Yucatan","Yum Balam biosphere Holbox","Holbox whale shark snorkel rules"],"search_language":["en","es-MX"],"local_keywords":["tiburón ballena Holbox","nadar con tiburón ballena Holbox temporada","isla sin autos Holbox","bioluminiscencia Punta Cocos","reserva Yum Balam Holbox","tours Holbox Cabo Catoche Isla Pasión","hoteles boutique Holbox"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-04"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"live"},{"si":"romance","status":"live"},{"si":"ocean","status":"future"},{"si":"wildlife","status":"future"}],"ultra":[{"name":"Ser Casasandra","posture":"boutique-luxe (not branded ultra)","price_tier":"luxury","earning":"on application / host-Virtuoso or host-DMC block","direct_only":true,"mor":"commissionable only where offered; no net-rate resale","source":"https://www.casasandra.com/"},{"name":"Punta Caliza","posture":"boutique-luxe (12-room design boutique, not a chain)","price_tier":"luxury","earning":"on application / host-Virtuoso","direct_only":true,"mor":"no net-rate resale","source":"https://puntacaliza.com/whale-sharks-in-holbox-best-season-and-tips-for-sightings/"},{"name":"Villas HM Palapas del Mar","posture":"boutique-luxe (HM Hotels group, resort-shaped)","price_tier":"premier","earning":"on application; some bedbank/TAAP possible - verify terms","direct_only":false,"mor":"no net-rate resale","source":""},{"name":"Ser Casasandra luxury villa","posture":"closest to ultra buy-out on-island","price_tier":"ultra","earning":"on application / host-Virtuoso","direct_only":true,"mor":"no net-rate resale","source":"https://www.casasandra.com/"}],"source_verified":"2026-07-04","hero":{"query":"Holbox, Mexico"},"geo":{"lat":21.522,"lng":-87.379}}'::jsonb, 46),
  ('hopkins-belize', '10S', 'Hopkins', 'Belize', 'Garifuna drums and the southern reef', 'live', 'verified', 'tropicalBeach', 'Belize', '{"tropical","expedition","culture"}', '{"tropical"}', '{"essential","comfort","premier","ultra"}', null, null, '{"key_facts":["The Garifuna cultural heart of Belize — living drumming tradition (Lebeha Drumming Center, est. 2002) and cuisine that is UNESCO-recognized intangible heritage (proclaimed 2001).","Gateway to Cockscomb Basin Wildlife Sanctuary — 128,000 acres, established 1986 as the world''s first jaguar preserve; ~200 jaguars and ~290 bird species.","One of the only places in Belize where the barrier reef and the rainforest are reachable from the same beach; South Water Caye is among the least-dived, healthiest reef systems in the country.","Mayflower Bocawina National Park (12 mi inland) has Belize''s longest zipline (2.5 mi) and its only guided waterfall rappel (Antelope Falls, 250 ft).","Garifuna Settlement Day (Nov 19) — Hopkins is one of three national epicenters, with a dawn Yurumein landing re-enactment and all-night drumming."],"safety":{"emergency":"911 (police & ambulance); maritime VHF Ch 16 or 966 — verify locally","hospital":"Dangriga (Southern Regional Hospital) for town care; serious trauma routes to Belize City; international medical evacuation the realistic path for major injury","recompression_chamber":"Ambergris Caye / San Pedro (24/7, tel 226-2660; DAN +1-919-648-9111) — FAR from Hopkins; dive conservatively","advisory_date":"2026-06-18","advisory_codes":"C (Crime) only","book_enabled":true,"consent_flow":{"bin":"BOOK WITH WARNING","disclosure_required":true,"renders":"full verbatim live US State Dept advisory for the country (level + reason + named-danger areas + complete ''If you decide to travel'' guidance), pulled live, plus traveler acknowledgment","wording_status":"hook set only — final consent language PENDING compliance-attorney sign-off"},"l3_disclosure":true,"state_dept_carveout":"only Southside Belize City restricted; Hopkins open","founder_policy_note":"book_enabled rides on TWW''s BOOK WITH WARNING (Four-Bin v3) posture — full-advisory disclosure + traveler acknowledgment at booking; only Southside Belize City is named, away from Hopkins","stay_in_zone":true,"air_access_verified":"BZE (Philip Goldson Intl) -> Dangriga/Hopkins DGA via Tropic Air/Maya Island Air (~25 min flight) + ~40 min drive; or ~2.5 hr direct drive from BZE","malaria":"WHO-certified malaria-free 2023; low localized inland risk only; dengue is an active 2026 risk (2,794 cases in 2025); jungle excursions raise mosquito exposure","water":"treat/bottled outside resorts"},"timing":{"peak_dry":"late-December to April","green_value_season":"June to November (30-40% savings)","event_peak":"Garifuna Settlement Day, November 19","secondary_events":["Hopkins Day (July)","Independence Day (September)"],"curve_start_dry":"mid-October","curve_start_event":"early-October","fire_date":"late-September to early-October","confidence":"seasonal-pattern-derived; sharpen on live booking pace"},"jewels":[{"name":"Lebeha Drumming Center","si_tag":"culture","tier":"essential","commission_path":"cultural experience add-on / direct-book","source":"https://en.wikipedia.org/wiki/Lebeha_Drumming_Center","si":"culture","commission":"cultural experience add-on / direct-book"},{"name":"Warasa Garifuna Drum School (Punta Gorda)","si_tag":"culture","tier":"essential","commission_path":"cultural add-on","source":"https://www.warasadrumschool.com/","si":"culture","commission":"cultural add-on"},{"name":"Garifuna cuisine (hudut/sere/ereba) cooking class","si_tag":"culture","tier":"essential","commission_path":"culinary experience / homestay bundle","source":"https://belizenewspost.com/garifuna-food/","si":"culture","commission":"culinary experience / homestay bundle"},{"name":"Garifuna Settlement Day (Nov 19)","si_tag":"culture","tier":"comfort","commission_path":"event-anchored stay+culture package","source":"https://caribbeanlifestyle.com/garifuna-settlement-day-belize/","hook":"November 19 The single sharpest cultural spike of the year: dawn Yurumein re-enactment, all-night drumming, parades. Hopkins is one of three epicenters","si":"culture","blurb":"November 19 The single sharpest cultural spike of the year: dawn Yurumein re-enactment, all-night drumming, parades. Hopkins is one of three epicenters","commission":"event-anchored stay+culture package"},{"name":"Cockscomb Basin Wildlife Sanctuary (world''s first jaguar preserve)","si_tag":"expedition","tier":"comfort","commission_path":"guided day-tour (gate non-commissionable)","source":"https://en.wikipedia.org/wiki/Cockscomb_Basin_Wildlife_Sanctuary","hook":"Established 1986, it holds ~200 jaguars plus puma, ocelot and ~290 bird species, reachable as a day trip rather than an expedition","si":"expedition","blurb":"Established 1986, it holds ~200 jaguars plus puma, ocelot and ~290 bird species, reachable as a day trip rather than an expedition","commission":"guided day-tour (gate non-commissionable)"},{"name":"Mayflower Bocawina National Park (waterfalls/zipline/rappel)","si_tag":"expedition","tier":"comfort","commission_path":"full-day adventure operator","source":"https://www.islandexpeditions.com/belize-vacations-blog/5-ways-explore-mayflower-bocawina-national-park","si":"expedition","commission":"full-day adventure operator"},{"name":"Sittee River manatee & birding","si_tag":"expedition","tier":"essential","commission_path":"half-day adventure operator","source":"https://www.magnumbelize.com/tours-2/sittee-river-kayaking/","hook":"Guided motorboat/kayak; crocodiles present — stay in the vessel, follow guide, no swimming in river sections. Manatees are protected — no-touch, no-chase","si":"expedition","blurb":"Guided motorboat/kayak; crocodiles present — stay in the vessel, follow guide, no swimming in river sections. Manatees are protected — no-touch, no-chase","commission":"half-day adventure operator"},{"name":"South Water Caye Marine Reserve + Glover''s Reef","si_tag":"tropical","tier":"comfort","commission_path":"dive own CLIA lane; snorkel day-trip operators","source":"https://www.zubludiving.com/destination/belize/stan-creek-district/hopkins-placencia-glovers-reef","si":"tropical","commission":"dive own CLIA lane; snorkel day-trip operators"}],"faq":[{"q":"What makes Hopkins different from Belize''s other beach spots?","a":"It is a rare double-header: one of the very few points on the Caribbean where the barrier reef and the rainforest are visible from the same beach chair, on a 12-mile beach. Because the southern barrier reef here fronts a low-population mainland, South Water Caye Marine Reserve is one of the least-dived, healthiest reef systems in the country.","source":"hamanasi.com, 2026-07-06","si_tag":"tropical"},{"q":"Can you visit the jaguar preserve from Hopkins?","a":"Yes — Cockscomb Basin, the world''s first jaguar preserve (128,000 acres, est. 1986), is about 30–40 minutes inland and works as a day trip, from an hour-long river stroll to a four-day Victoria Peak trek. The BZ$10 non-national entry fee is government pass-through; you book the guided day-tour for the value.","source":"hamanasi.com, 2026-07-06","si_tag":"expedition"},{"q":"Is Hopkins a good honeymoon destination?","a":"Yes, for jungle-and-reef romance rather than resort glitz. Hamanasi — a Tripadvisor Top-25-in-world honoree with 30 treehouse/beachfront rooms, a PADI facility and Green Globe certification — plus Belizean Dreams and Jaguar Reef Lodge are built around couples with private-guide adventures and infinity pools.","source":"tripadvisor.com, 2026-07-06","si_tag":"romance"},{"q":"Why is Hopkins the Garifuna cultural heart of Belize?","a":"Daily drum schools, homestays and food workshops make Hopkins the single most accessible stop to experience living Garifuna heritage — itself UNESCO-recognized intangible heritage (proclaimed 2001). Garifuna Settlement Day on November 19 brings a dawn Yurumein re-enactment and all-night drumming, and rooms in the village sell out.","source":"belizenewspost.com, 2026-07-06","si_tag":"culture"},{"q":"Is Hopkins safe right now?","a":"Yes, with the standard disclosure. Belize is at US State Dept Level 3 (reissued June 18, 2026, code C/Crime only), but the only named-by-boundary restriction is Southside Belize City — a residential district of the old port, nowhere near Hopkins. Stay in the coastal zone and the named restriction does not touch you.","source":"travel.state.gov, 2026-06-18","si_tag":"safety"},{"q":"What''s the real risk to plan for in Hopkins?","a":"Medical remoteness and mosquitoes, not crime. The State Dept warns emergency medical services are \"usually unavailable or significantly delayed\" and serious cases \"normally require medical evacuation to another country,\" so evacuation-grade insurance is non-negotiable; the nearest hospital is Dangriga, with trauma routing to Belize City. Dengue is an active 2026 risk (2,794 cases in 2025), and jungle excursions raise exposure.","source":"travel.state.gov, 2026-07-06","si_tag":"safety"},{"q":"Is the Mayflower Bocawina waterfall rappel or the jungle hiking dangerous?","a":"Mayflower Bocawina holds Belize''s longest zipline (2.5 mi) and its only guided waterfall rappel (Antelope Falls, 250 ft) — certified guides and provided harness/helmet only, never solo. In Cockscomb, the Tiger Fern Trail now requires a guide (mandated after a hiker fatality) and Victoria Peak (3,675 ft) is dry-season-only and guide-mandatory.","source":"mayflowerbocawina.org, 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Hopkins, Belize: Garifuna Culture, Jaguar Preserve & Reef Travel Guide (2026)","meta_description":"Hopkins is Belize''s Garifuna cultural heart — drumming, uncrowded beach, gateway to Cockscomb Basin jaguar preserve, Mayflower Bocawina waterfalls, and the southern barrier reef.","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-06","search_language":"en","local_keywords":["Hopkins Belize Garifuna drumming","Cockscomb Basin jaguar preserve tour from Hopkins","Hopkins Belize diving South Water Caye","Mayflower Bocawina waterfall rappel zipline","Sittee River manatee tour Belize","Garifuna Settlement Day Hopkins November 19","best time to visit Hopkins Belize","Hamanasi vs Belizean Dreams Hopkins","Hopkins Belize beach villa rental","is Hopkins Belize safe 2026","hudut Garifuna food Hopkins"],"hreflang":["en"]},"booking":null,"si_checklist_25":null,"sis_present":["tropical","expedition","culture"],"ultra":[{"name":"Hamanasi Adventure & Dive Resort","location":"Hopkins","tier":"$$$$ premier","lane":"Fora/AOR · MoR","note":"Tripadvisor Top-25-in-world honoree; treehouses; Green Globe"},{"name":"Itz''ana Resort & Residences","location":"Placencia (~45-60 min south)","tier":"$$$$ ultra","lane":"Fora/AOR · MoR","note":"nearest true ultra; SLH / MICHELIN Guide; villas + marina"},{"name":"Naïa Resort & Spa","location":"Placencia","tier":"$$$$ ultra","lane":"Fora/AOR","note":"ultra beachfront spa/villa"}],"source_verified":"2026-07-06","hero":{"query":"Hopkins, Belize"},"geo":{"lat":16.105,"lng":-88.2867}}'::jsonb, 47),
  ('huatulco-mexico', '10S', 'Huatulco', 'Mexico', 'Oaxaca''s calm nine-bay coast', 'live', 'verified', 'mountainValley', 'Oaxaca (Oaxaca City & Coast)', '{"expedition","diveglobal","ocean","culture","wildlife","wellness"}', '{}', '{"essential","comfort"}', null, null, '{"key_facts":["Nine bays across 36 beaches; horseshoe coves stay calm for swimming/snorkeling — greener and calmer than surf-driven Puerto Escondido.","Huatulco National Park protects ~11,890 ha of coast, reef and forest; dolphins, turtles and seasonal whales.","Playa La Entrega is the best land-accessible snorkel cove — reef starts feet from shore.","Pluma Hidalgo (~1,350 m, 45 min inland) produces some of the Americas'' top high-altitude Arabica coffee.","Copalita is one of only two seaside archaeological sites in Mexico (with Tulum) — Zapotec/Mixtec city settled by ~500 BC.","Humpback whale season Dec 15-Mar 21 (97% sighting success at peak); olive-ridley/green turtle nesting Jul-Jan."],"safety":{"emergency":"911","hospital":"Local Huatulco/La Crucecita clinics stabilize routine cases; serious trauma routes to Oaxaca City or Mexico City for definitive/ICU care","advisory_level":"L2","advisory_note":"L2 (Oaxaca) — Exercise Increased Caution (Huatulco explicitly unrestricted); updated May 29, 2026","book_enabled":true,"bin":"freely bookable (L2)","consent_flow":false,"air_access_verified":true,"malaria":"low/negligible in Huatulco tourist coast","dengue":"endemic seasonal risk, higher May-Nov; use repellent","water":"bottled/purified only; resort water filtered","swimming":"calmer/safer bays than Puerto Escondido, but open beaches carry riptides — swim sheltered coves","hurricane_season":"Pacific storm season ~Jun-Oct; insure/refundable"},"timing":{"peak":"Nov-Apr (dry season; sunny, no rain, highs 29-34C; whale window Dec-Mar)","inflection":"late Nov & April (shoulder value, still dry/sunny)","green":"May-Oct (rainy/low; hotter, lush, cheapest; overlaps turtle nesting)","whale_season":"humpbacks Dec 15-Mar 21, 97% sighting success at peak","turtle_season":"olive-ridley/green nesting Jul-Jan; hatchling-release draw","fire_date":"early-to-mid November — 1-2 weeks ahead of the Dec 15 humpback curve-start / dry-season flip","holiday_event_peaks":["Christmas/New Year","Semana Santa","whale-watch Dec-Mar"],"fill_the_beds":"green months lead with Pluma Hidalgo coffee day, Copalita eco-archaeology + river rafting, turtle-release evenings, calm-bay snorkel, green-season all-inclusive value","campaign_start_trigger":"open peak/whale campaigns early-mid Nov; shoulder (late Nov, Apr) ~3-4 months out; turtle-nesting green-season value push Jul-Oct"},"jewels":[{"name":"Nine-Bays boat tour","si_tag":"Ocean Adventures","status":"live","tier":"essential","hook":"Full-day boat expedition across the nine bays with beach + snorkel stops.","bookable_category":"guided boat tour","commission_path":"Amstar DMC ~12% / affiliate 4-8%; park bracelet pass-through","source":"https://www.amstardmc.com/en/excursions/sea-and-sun-bays/","si":"ocean","blurb":"Full-day boat expedition across the nine bays with beach + snorkel stops.","commission":"Amstar DMC ~12% / affiliate 4-8%; park bracelet pass-through"},{"name":"Bahia Maguey & Bahia Organo snorkel","si_tag":"Ocean Adventures","status":"future","tier":"essential","hook":"Calm-cove snorkel over close reef with beachfront seafood palapas at Maguey.","bookable_category":"boat snorkel stop","commission_path":"affiliate / DMC ~12%; food pass-through","source":"https://www.viator.com/tours/Huatulco/Huatulco-National-Park-Sightseeing-Cruise-with-Snorkeling-in-Maguey-Bay/d4334-5885HUXSUN","si":"ocean","blurb":"Calm-cove snorkel over close reef with beachfront seafood palapas at Maguey.","commission":"affiliate / DMC ~12%; food pass-through"},{"name":"Playa La Entrega reef","si_tag":"Ocean Adventures","status":"future","tier":"essential","hook":"Land-accessible horseshoe cove — reef starts feet from shore, calm and current-sheltered.","bookable_category":"shore snorkel / rental","commission_path":"affiliate 4-8% on packaged tours; DIY non-commissionable","source":"https://mrplayas.com/blog/huatulco-oaxaca-guide","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"Land-accessible horseshoe cove — reef starts feet from shore, calm and current-sheltered.","when":"Nov-Apr","commission":"affiliate 4-8% on packaged tours; DIY non-commissionable"},{"name":"Whale & dolphin watch","si_tag":"Wildlife & Nature","status":"future","tier":"comfort","hook":"Humpbacks Dec 15-Mar 21 (97% success at peak); year-round dolphins/turtles.","bookable_category":"wildlife boat safari","commission_path":"operator affiliate / DMC ~12%","source":"https://seasafarihuatulco.com/whale-watching-tours/","si":"wildlife","blurb":"Humpbacks Dec 15-Mar 21 (97% success at peak); year-round dolphins/turtles.","commission":"operator affiliate / DMC ~12%"},{"name":"Cacaluta & San Agustin remote bays","si_tag":"Ocean Adventures","status":"future","tier":"comfort","hook":"Wild, undeveloped bays — heart-shaped Cacaluta and gin-clear San Agustin (18 m viz).","bookable_category":"private boat / dedicated tour","commission_path":"DMC / operator affiliate; park bracelet pass-through","source":"https://www.tripadvisor.com/Attraction_Review-g150789-d524145-Reviews-Bahia_de_Cacaluta-Huatulco_Southern_Mexico.html","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"Wild, undeveloped bays — heart-shaped Cacaluta and gin-clear San Agustin (18 m viz).","when":"Nov-Apr","commission":"DMC / operator affiliate; park bracelet pass-through"},{"name":"La Entrega / San Agustin reef dive","si_tag":"Dive Globally","status":"future","tier":"comfort","hook":"Beginner-to-intermediate protected-reef dives; San Agustin ~30 m sunken ship.","bookable_category":"reef dive (PADI operator)","commission_path":"dive-operator affiliate / DMC ~12%","source":"https://www.explorehuatulco.com/Huatulco-Scuba-Diving-Guide","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","blurb":"Beginner-to-intermediate protected-reef dives; San Agustin ~30 m sunken ship.","when":"Nov-Apr","commission":"dive-operator affiliate / DMC ~12%"},{"name":"Pluma Hidalgo coffee-finca day","si_tag":"Wellness","status":"future","tier":"comfort","hook":"45-min drive to ~1,350 m coffee country — finca tour, roasting, tasting, mirador views.","bookable_category":"guided coffee tour","commission_path":"affiliate 4-8% / DMC ~12%","source":"https://www.getyourguide.com/huatulco-l781/huatulco-santa-maria-and-pluma-hidalgo-coffee-tour-t631983/","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"wellness","blurb":"45-min drive to ~1,350 m coffee country — finca tour, roasting, tasting, mirador views.","when":"Nov-Apr","commission":"affiliate 4-8% / DMC ~12%"},{"name":"Copalita eco-archaeological park","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"One of only two seaside archaeological sites in Mexico — Zapotec/Mixtec city in rainforest above the river mouth.","bookable_category":"guided park visit / combo","commission_path":"affiliate 4-8% / DMC ~12%; park entry pass-through","source":"https://lugares.inah.gob.mx/en/node/4487","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"One of only two seaside archaeological sites in Mexico — Zapotec/Mixtec city in rainforest above the river mouth.","when":"year-round","commission":"affiliate 4-8% / DMC ~12%; park entry pass-through"},{"name":"La Crucecita zocalo + Church of Guadalupe","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"Real Oaxacan town with a zocalo, market, and one of Mexico''s largest Guadalupe ceiling murals.","bookable_category":"walking tour / DIY","commission_path":"affiliate on guided walks; DIY non-commissionable","source":"https://www.explorehuatulco.com/la-crucecita-region-huatulco-mexico","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"Real Oaxacan town with a zocalo, market, and one of Mexico''s largest Guadalupe ceiling murals.","when":"year-round","commission":"affiliate on guided walks; DIY non-commissionable"},{"name":"Copalita River rafting","si_tag":"Global Expedition Adventures","status":"live","tier":"comfort","hook":"Guided whitewater at La Bocana beside the archaeological site; fuller in green months.","bookable_category":"guided rafting","commission_path":"operator affiliate / DMC ~12%","source":"https://www.huatulcowatersports.com/tours/copalita-archaological-site-143783","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"Guided whitewater at La Bocana beside the archaeological site; fuller in green months.","when":"Nov-Apr","commission":"operator affiliate / DMC ~12%"}],"faq":[{"q":"Is Huatulco safe to visit right now?","a":"Yes — freely bookable. Oaxaca carries a US State Dept **Level 2 \"Exercise Increased Caution\"** (updated May 29, 2026), and Huatulco is **explicitly named among the unrestricted areas** — a FONATUR-planned resort coast. The separate Isthmus region (Juchitán/Salina Cruz) is restricted for US-gov employees and is not a TWW destination.","source":"travel.state.gov, 2026-07-07","si_tag":"safety"},{"q":"What''s the real risk to plan for in the water?","a":"Riptides on the open beaches, not the sheltered bays. The horseshoe coves (La Entrega, Maguey, San Agustín) are genuinely calm and swimmable, but open stretches of Tangolunda and Chahué carry rip currents — swim only the flagged, sheltered coves, and heed the flags.","source":"mrplayas.com, 2026-07-07","si_tag":"safety"},{"q":"Which bays are calm enough for swimming and families?","a":"The horseshoe coves. La Entrega is the best land-accessible snorkel cove — the reef starts feet from shore — and Maguey, Órgano and San Agustín stay calm inside their coves; that''s the difference from surf-driven Puerto Escondido up the coast.","source":"mrplayas.com / secretflying.com, 2026-07-07","si_tag":"tropical"},{"q":"What''s the one must-do day here?","a":"The nine-bays boat tour — a full-day (~7 h) expedition across the nine bays with beach and snorkel stops, bookable through Amstar''s \"Sea and Sun\"/\"Seven Bays\" excursions or affiliate marketplaces (the National Park conservation bracelet is a cash pass-through).","source":"amstardmc.com, 2026-07-07","si_tag":"expedition"},{"q":"When can I see whales?","a":"Humpbacks run **Dec 15–Mar 21**, with sightings on **over 97% of tours** at the peak, on boat safaris out of Santa Cruz; dolphins and turtles are year-round, and turtle nesting (olive-ridley/green) runs Jul–Jan.","source":"oceanico.org, 2026-07-07","si_tag":"wildlife"},{"q":"Can beginners dive the reef here?","a":"Yes — the protected Pacific reef is beginner-friendly. La Entrega runs 10–12 m and San Agustín adds a ~30 m sunken ship for advanced divers, with up to ~18 m visibility in the dry season; book only PADI-certified operators (Huatulco Dive Center, Anfibios, Hurricane Divers).","source":"explorehuatulco.com, 2026-07-07","si_tag":"diveglobal"},{"q":"Is there culture beyond the beach?","a":"Yes — Copalita is one of only two seaside archaeological sites in Mexico (with Tulum), a Zapotec/Mixtec city settled by ~500 BC in rainforest above the river mouth, and La Crucecita''s zócalo holds one of Mexico''s largest Guadalupe ceiling murals.","source":"lugares.inah.gob.mx, 2026-07-07","si_tag":"culture"},{"q":"Is Huatulco good for a honeymoon?","a":"Yes, for calm-bay romance rather than branded-ultra. Secrets Huatulco is the adults-only, all-oceanfront-suite anchor of the Tangolunda strip; the coast tops out at premier all-inclusive plus a top oceanfront villa in Conejos — there is no Aman/Rosewood-tier hotel here.","source":"hyattinclusivecollection.com, 2026-07-07","si_tag":"romance"}],"seo":{"meta_title":"Huatulco Travel Guide 2026 — Nine Bays, Snorkel & Coffee Country | TravelWell.World","meta_description":"Plan Huatulco, Oaxaca''s calm eco-resort coast: the nine-bays boat tour, Maguey/Organo snorkel, La Crucecita, Pluma Hidalgo coffee, Copalita eco-archaeology, whale season, Level 2 safety (Huatulco unrestricted).","slug":"huatulco-mexico","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-07","search_language":"es-MX","local_keywords":["qué hacer en Huatulco","Bahías de Huatulco","La Crucecita","tour de las nueve bahías Huatulco","snorkel en Bahía Maguey","café Pluma Hidalgo tour","Parque Eco-Arqueológico Copalita","avistamiento de ballenas Huatulco","mejor época para visitar Huatulco","buceo en Huatulco","villas frente al mar Conejos Huatulco"],"hreflang":["en","es-MX"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"live"},{"si":"diveglobal","status":"future"},{"si":"ocean","status":"future"},{"si":"culture","status":"future"},{"si":"wildlife","status":"future"},{"si":"wellness","status":"future"}],"ultra":[{"name":"Secrets Huatulco Resort & Spa","price_tier":"premier","virtuoso":false,"earning":"all-incl -> OA host AOR + Hyatt Inclusive TA ~12%","mor_posture":true,"note":"adults-only all-oceanfront-suite; the branded ceiling for the coast","source":"https://www.hyattinclusivecollection.com/en/resorts-hotels/secrets/mexico/huatulco-resort-spa/"},{"name":"Dreams Huatulco Resort & Spa","price_tier":"comfort-premier","virtuoso":false,"earning":"OA host AOR + Hyatt Inclusive TA ~12%","mor_posture":true,"note":"family sister with shared Secrets access","source":"https://www.tripadvisor.com/Hotel_Review-g150789-d2089597-Reviews-Secrets_Huatulco_Resort_Spa-Huatulco_Southern_Mexico.html"},{"name":"Las Palmas Resort","price_tier":"comfort","virtuoso":false,"earning":"OA host AOR","mor_posture":true,"source":"https://www.tripadvisor.com/ShowTopic-g150789-i740-k14655958-Secrets_vs_Dreams_vs_Barcelo-Huatulco_Southern_Mexico.html"},{"name":"Boutique bay villas — Residencial Conejos (oceanfront)","price_tier":"ultra","virtuoso":false,"earning":"on application / via host or DMC villa AOR","mor_posture":true,"note":"villa ceiling; no branded true-ultra hotel on this eco-resort coast; net-rate resale red","source":"https://www.airbnb.com/santa-maria-huatulco-mexico/stays/villas"}],"source_verified":"2026-07-07","hero":{"query":"Huatulco, Mexico"},"geo":{"lat":15.76,"lng":-96.13}}'::jsonb, 48),
  ('iguazu-falls-argentina', '10S', 'Iguazú Falls (Argentine Side)', 'Argentina', 'Iguazú Falls (Argentine Side)', 'live', 'verified', 'mountainValley', 'Northwest, Mendoza Wine & Iguazú', '{"expedition","culture"}', '{}', '{"essential","comfort","luxury","ultra"}', null, null, '{"key_facts":null,"safety":{"emergency":"911","emergency_secondary":["101 police","107 ambulance (SAME)","100 fire","0800 999 5000 tourist line"],"advisory_level":"L1","book_enabled":true,"bin":"freely bookable (L1)","consent_flow":false,"air_access_verified":true,"air_access_note":"Puerto Iguazu / Cataratas del Iguazu Intl (IGR) via Buenos Aires AEP (domestic) / EZE (international); daily nonstops on Aerolineas Argentinas / Flybondi / JetSmart; IGR<->AEP among busiest domestic routes","trauma_note":"Puerto Iguazu hospital stabilises; serious trauma evac to Buenos Aires by air (IGR->AEP/EZE)","falls_footing":"catwalks + circuit boardwalks/stairs permanently misted & slippery; Lower Circuit most stair-heavy; Throat catwalk can close on river surge","gran_aventura_boat":"mandatory life jacket + briefing + dry-bags; jacket-quality reviews mixed; total soaking; river-level-dependent","triple_frontier_note":"Argentina-Brazil-Paraguay convergence is a transnational-crime region; avoid the Paraguay/Ciudad del Este side casually; park + Puerto Iguazu core safe with standard precautions; cross to Brazil before nightfall","health":"Misiones = CDC yellow-fever recommended + dengue risk; DEET, dawn/dusk cover, pre-travel vaccination consult","wildlife":"coatis bold near viewpoints — do NOT feed (bite/scratch)","mandatory_insurance":"Non-resident travel medical insurance required since 2025-07-01 (hospitalisation, repatriation, evacuation)"},"timing":{"peak_experience":"Mar-Apr & Aug-Sep (best flow-weather-crowd balance)","peak_flow_and_crowds":"Dec-Feb (max water flow, heat >35C, peak crowds); Easter week (Apr) crowd spike","shoulder_sleeper":"May (autumn flow, 30-40% lower rates)","quietest_days":"Tue-Thu","full_moon_walk":"5 nights/month only — plan around lunar calendar; 3 nightly departures, ~2.5 hr","fire_date":"curve-start minus 1-2 weeks; ~2 weeks before visible curve for a standard trip, but 6-12 months ahead for Awasi Iguazu or an in-park Gran Melia falls-view room"},"jewels":[{"name":"Garganta del Diablo catwalk (Devil''s Throat)","si_tag":"expedition","tier":"essential","commission_path":"park-fee entry (non-commissionable) + DMC land package / activity affiliate framing","source":"https://iguazufalls-tickets.org/what-to-see/devils-throat-iguazu-falls/","hook":"the marquee: 1.1 km of steel walkway out over the U-shaped canyon where 14 falls drop 82 m into permanent mist","si":"expedition","blurb":"the marquee: 1.1 km of steel walkway out over the U-shaped canyon where 14 falls drop 82 m into permanent mist","commission":"park-fee entry (non-commissionable) + DMC land package / activity affiliate framing"},{"name":"Upper Circuit","si_tag":"expedition","tier":"essential","commission_path":"park-fee + DMC/affiliate","source":"https://iguazufalls.com/travel-guide/the-circuits-in-iguazu-falls/","hook":"~1.75 km, mostly flat, top-down panoramas across the cataract chain; the accessible headline alongside the Throat catwalk","si":"expedition","blurb":"~1.75 km, mostly flat, top-down panoramas across the cataract chain; the accessible headline alongside the Throat catwalk","commission":"park-fee + DMC/affiliate"},{"name":"Lower Circuit + Isla San Martín boat","si_tag":"expedition","tier":"essential","commission_path":"park-fee + DMC/affiliate","source":"https://iguazutickets.com/guides/what-to-see-at-iguazu-falls/","hook":"~1.7 km, stairs down to the base, closest in-your-face angle, plus the passenger boat to the rocky Isla San Martín and its beach","si":"expedition","blurb":"~1.7 km, stairs down to the base, closest in-your-face angle, plus the passenger boat to the rocky Isla San Martín and its beach","commission":"park-fee + DMC/affiliate"},{"name":"Gran Aventura — under-the-falls boat + 4x4","si_tag":"expedition","tier":"comfort","commission_path":"in-park concession (largely non-commissionable) — package via DMC / frame via activity affiliate","source":"https://iguazufalls.com/tours-and-activities/gran-aventura-activity/","hook":"the adrenaline jewel: 4×4 jungle trail to Puerto Macuco, then a 6 km semi-rigid run into the San Martín falls \"baptism of the mists.\"","si":"expedition","blurb":"the adrenaline jewel: 4×4 jungle trail to Puerto Macuco, then a 6 km semi-rigid run into the San Martín falls \"baptism of the mists.\"","commission":"in-park concession (largely non-commissionable) — package via DMC / frame via activity affiliate"},{"name":"Full-Moon Walk (Paseos de Luna Llena)","si_tag":"expedition","tier":"comfort","commission_path":"guided-only ticket via activity affiliate + DMC","source":"https://iguazufalls.com/tours-and-activities/full-moon-walk-tour/","hook":"5 nights a month only, timed to the full moon: welcome drink + Guaraní music, Eco-Train through the night jungle to the Throat catwalk","si":"expedition","blurb":"5 nights a month only, timed to the full moon: welcome drink + Guaraní music, Eco-Train through the night jungle to the Throat catwalk","commission":"guided-only ticket via activity affiliate + DMC"},{"name":"Sunrise with in-park hotel (Gran Meliá privilege)","si_tag":"GEA/RHN","tier":"ultra","commission_path":"in-park hotel booking (ultra lane)","source":"https://www.jacadatravel.com/latin-america/argentina/iguazu-falls/accommodation/melia-iguazu/","si":"GEA/RHN","commission":"in-park hotel booking (ultra lane)"},{"name":"Macuco jungle trail","si_tag":"expedition","tier":"essential","commission_path":"self-guided or guided via in-park operator + DMC","source":"http://www.iguazujungle.com/eng/web2/","hook":"the park''s longer forest walk to a hidden waterfall; coatis, toucans, capuchins, butterflies","si":"expedition","blurb":"the park''s longer forest walk to a hidden waterfall; coatis, toucans, capuchins, butterflies","commission":"self-guided or guided via in-park operator + DMC"},{"name":"Güirá Oga wildlife refuge","si_tag":"expedition","tier":"essential","commission_path":"activity affiliate + DMC add-on","source":"https://www.welcomeargentina.com/puertoiguazu/lodge-awasi-iguazu_i.html","hook":"\"bird house\" in Guaraní; a rescue-and-rehab centre for trafficked/injured native fauna just outside Puerto Iguazú","si":"expedition","blurb":"\"bird house\" in Guaraní; a rescue-and-rehab centre for trafficked/injured native fauna just outside Puerto Iguazú","commission":"activity affiliate + DMC add-on"},{"name":"Brazilian-side panorama day-trip","si_tag":"culture","tier":"comfort","commission_path":"DMC/guided transfer + activity affiliate (cross-ref Brazil-side dossier)","source":"https://sayhueque.com/our-trips/iguazu-falls/","hook":"cross to Parque Nacional do Iguaçu for the whole-system framed view Argentina can''t give you; passport-required border crossing, ~3–4 hr","si":"culture","blurb":"cross to Parque Nacional do Iguaçu for the whole-system framed view Argentina can''t give you; passport-required border crossing, ~3–4 hr","commission":"DMC/guided transfer + activity affiliate (cross-ref Brazil-side dossier)"},{"name":"San Ignacio Miní (UNESCO Jesuit-Guaraní mission)","si_tag":"culture","tier":"essential","commission_path":"DMC / guided excursion + activity affiliate","source":"https://whc.unesco.org/en/list/275/","hook":"the roofless red-sandstone cathedral of a 1610 Jesuit reduction, UNESCO-listed 1984, ~300 km south toward Posadas","si":"culture","blurb":"the roofless red-sandstone cathedral of a 1610 Jesuit reduction, UNESCO-listed 1984, ~300 km south toward Posadas","commission":"DMC / guided excursion + activity affiliate"}],"faq":[{"q":"What''s the best plan for a day at Iguazú Falls?","a":"Run the Devil''s Throat first at the 08:00 park opening, then work back through the Upper and Lower Circuits. The park opens 08:00 and closes 18:00 with last falls access around 16:30, and starting at the Garganta station gives the best rainbow light and thinnest crowds; budget 5–6 hours minimum for all three circuits plus the Eco-Train.","source":"iguazufalls-tickets.org, Accessed 2026-07-07","si_tag":"expedition"},{"q":"When is the best time to visit Iguazú Falls?","a":"March–April and August–September are the sweet spot, because they balance strong water flow with comfortable 20–30 °C temperatures and manageable crowds. December–February brings maximum flow but heat above 35 °C and peak crowds, while May is a quiet sleeper month with autumn flow and room rates 30–40% below the Dec–Feb peak.","source":"iguazutickets.com, Accessed 2026-07-07","si_tag":"expedition"},{"q":"Where should honeymooners stay at Iguazú?","a":"The two scarce in-jewel beds are the play: Awasi Iguazú (Relais & Châteaux, 14 stilted villas with a private guide and 4×4 each) and the Gran Meliá Iguazú, the only hotel inside the Argentine park. Both are near-zero on bedbanks and contract direct or via DMC, so book Awasi or an in-park falls-view room 6–12 months ahead.","source":"relaischateaux.com, Accessed 2026-07-07","si_tag":"romance"},{"q":"Should I visit the Brazilian side too — and what else is nearby?","a":"Yes if time allows: Argentina holds ~80% of the falls and the immersion, while Brazil''s single panoramic boardwalk delivers the whole-system view as a passport-required border day-trip. South toward Posadas, the roofless red-sandstone cathedral of San Ignacio Miní (UNESCO-listed 1984) rounds out a cultural-heritage circuit.","source":"sayhueque.com, Accessed 2026-07-07","si_tag":"culture"},{"q":"Is Iguazú Falls safe right now?","a":"Yes. Argentina is at U.S. State Department Level 1 \"Exercise Normal Precautions,\" the safest tier, alongside Japan and Germany and reissued 2026-05-20, and the national parks are well-organised with crime against visitors inside the park rare. The elevated nodes — Rosario city (L2) and the Triple Frontier — are geographically separable from Puerto Iguazú''s tourist core.","source":"travel.state.gov, Accessed 2026-07-07","si_tag":"safety"},{"q":"What''s the real risk to plan for at Iguazú?","a":"Health and weather, not crime. Misiones province carries a CDC yellow-fever vaccination recommendation and a real dengue risk, so pack DEET and get a pre-travel vaccination consult; the catwalks are permanently misted and slippery, and extreme rainfall can close the Devil''s Throat catwalk on river surge.","source":"wwwnc.cdc.gov, Accessed 2026-07-07","si_tag":"safety"},{"q":"Is the Gran Aventura speedboat dangerous?","a":"It is operator-run and low-risk with the rules followed, but not trivial. A life jacket is mandatory and a safety briefing is given before the 6 km run into the San Martín falls; jacket-quality reviews are mixed, so non-swimmers should weigh the run, everyone gets thoroughly soaked, and the trip is river-level-dependent and cancels in high water.","source":"iguazufalls.com, Accessed 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Iguazú Falls, Argentine Side: Devil''s Throat, the Circuits & Gran Aventura Boat | TravelWell.World","meta_description":"Stand over the Devil''s Throat, walk the Upper and Lower Circuits, run the Gran Aventura boat under the falls, and stay inside the national park — the complete guide to the Argentine side of Iguazú.","long_tail_en":["iguazu falls argentine side guide","garganta del diablo devil''s throat iguazu","iguazu upper and lower circuits","gran aventura boat ride iguazu","iguazu falls full moon walk","best time to visit iguazu falls","gran melia iguazu in-park hotel","awasi iguazu relais chateaux","iguazu argentina vs brazil side","san ignacio mini jesuit ruins"],"search_language":"es-AR","local_keywords":["Cataratas del Iguazú","Garganta del Diablo","Gran Aventura Iguazú","circuito superior e inferior Iguazú","Tren Ecológico de la Selva","paseo de luna llena Cataratas","San Ignacio Miní ruinas","qué hacer en Puerto Iguazú"],"hreflang":["en","es-AR"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","freshness":"2026-07-07","primary_keyword":"Iguazú Falls (Argentine Side)"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"live"},{"si":"culture","status":"live"}],"ultra":[{"name":"Awasi Iguazu","type":"Relais & Chateaux all-inclusive villa lodge","location":"Misiones jungle, ~20 min from falls","earning":"Virtuoso/Fora advisor commission + amenities","mor":"AOR/advisor","tier":"ultra"},{"name":"Gran Melia Iguazu","type":"in-park hotel (only one, Argentine side)","location":"inside Iguazu National Park","earning":"advisor/DMC commission + RedLevel upsell","mor":"AOR/advisor/DMC","tier":"ultra"},{"name":"Loi Suites Iguazu","type":"upscale jungle-river resort","location":"Iryapu reserve, ~10 min from Puerto Iguazu","earning":"advisor/DMC commission","mor":"AOR/DMC","tier":"luxury"}],"source_verified":null,"hero":{"query":"Iguazú Falls (Argentine Side), Argentina"},"geo":{"lat":-25.6953,"lng":-54.4367}}'::jsonb, 49),
  ('isla-contoy-mexico', '10S', 'Isla Contoy', 'Mexico', '*If it''s 200 people a day on an island', 'live', 'verified', 'oceanAerial', 'Quintana Roo (Cancún & Riviera Maya)', '{"expedition","ocean","wildlife"}', '{}', '{"comfort"}', 'comfort', null, '{"key_facts":["Uninhabited national park capped at 200 visitors/day, authorized tours only","UNESCO-recognized reserve, habitat for 173+ bird species (frigatebirds, pelicans)","Ixlaché reef marks the northern start of the world''s 2nd-largest barrier reef","Sea-turtle nesting May-October; ~30 km north of Isla Mujeres","Day-trip only (no lodging); ~7-8 hr tours from Cancún/Isla Mujeres marinas"],"safety":{"emergency":"911","hospital":"uninhabited - no on-island care; evac via Isla Mujeres to Cancún (Galenia/Hospiten - verify)","advisory_level":"L2","malaria":"none in QR tourist zones (verify); dengue precautions","yellow_fever":"none required"},"timing":{"peak":"Dec-Apr (dry, calm seas, best Ixlaché clarity) + Jun-Sep whale-shark corridor (sold as whale-shark + Contoy combos = true event peak)","shoulder":"May-Jun & Nov (easier permit-day availability; May-Jun straddles whale-shark open + turtle-nesting start)","green":"Jun-mid-Oct (hurricane season; exposed ~30 km open-water crossing - trips cancel in rough seas; disclose cancellation policy)","booking_lead":"200/day cap + authorized-only = book 3-6+ wks in peak (combos sell out with summer 30-39-day window), 1-3 wks shoulder; popular operators + calm-sea Sundays fill first","off_season_specials":"no beds - ''fill-the-permit-days'': green/shoulder = calm-day nature escape (birds + Ixlaché) bundled with off-island Isla Mujeres/Cancún stay","event_peaks":"Christmas-NY + spring break (Dec-Apr); sea-turtle nesting (May-Oct) + whale-shark run (Jun-Sep) are the island''s wildlife event peaks","campaign_start":"whale-shark + Contoy combo Mar-Apr (6-8 wks pre-open); dry-season Ixlaché day-trip Aug-Sep; always pair with off-island stay CTA"},"jewels":[{"name":"Contoy authorized eco-expedition (200/day cap)","si_tag":"Global Expedition Adventures","status":"live","tier":"comfort","hook":"permitted boat + guided trail through frigatebird/pelican colonies","bookable_category":"authorized eco day tour","commission_path":"authorized operator → DMC/curated (park fee pass-through)","source":"https://contoyadventures.com/isla-contoy/","timing":"Dec-Apr  + Jun-Sep whale-shark corridor","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"permitted boat + guided trail through frigatebird/pelican colonies","when":"Dec-Apr  + Jun-Sep whale-shark corridor","commission":"authorized operator → DMC/curated (park fee pass-through)"},{"name":"Ixlaché reef snorkel","si_tag":"Ocean Adventures","status":"future","tier":"comfort","hook":"northern start of world''s 2nd-largest barrier reef, 17 hard + 14 soft corals","bookable_category":"snorkel stop within Contoy tour","commission_path":"authorized operator → curated (bundled)","source":"https://contoyadventures.com/isla-contoy/","timing":"Dec-Apr  + Jun-Sep whale-shark corridor","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"northern start of world''s 2nd-largest barrier reef, 17 hard + 14 soft corals","when":"Dec-Apr  + Jun-Sep whale-shark corridor","commission":"authorized operator → curated (bundled)"},{"name":"173+ bird species + sea-turtle nesting","si_tag":"Wildlife & Nature","status":"future","tier":"comfort","hook":"frigatebirds, pelicans, green/loggerhead nesting beaches (May-Oct)","bookable_category":"guided nature walk (within tour)","commission_path":"authorized operator → curated (conservation fee non-commissionable)","source":"https://nationalparksassociation.org/mexico-national-parks/isla-contoy-national-park/","si":"wildlife","blurb":"frigatebirds, pelicans, green/loggerhead nesting beaches (May-Oct)","commission":"authorized operator → curated (conservation fee non-commissionable)"}],"faq":[{"q":"Is Isla Contoy safe to visit right now?","a":"Yes — freely bookable, no hold. Contoy sits in Quintana Roo, which carries a standard US State Dept Level 2 \"Exercise Increased Caution\" (dated 2026-05-29). The key caveat is that the island is uninhabited with no medical facility, so your safety net is the operator''s radio and boat; serious cases route by boat to Isla Mujeres, then Cancún.","source":"travel.state.gov / nationalparksassociation.org, 2026-07-04","si_tag":"safety"},{"q":"What''s the real risk to plan for on an Isla Contoy trip?","a":"The open-water crossing and weather — not crime. Contoy sits ~30 km out at the seam where the Caribbean meets the Gulf, an exposed run where sea state can build and operators cancel trips in rough weather (especially hurricane season, Jun–Nov). Pick a calm-sea day, confirm the cancellation/reschedule policy, and keep life jackets on during transit.","source":"airial.travel, 2026-07-04","si_tag":"safety"},{"q":"Is the reef snorkel and boat crossing dangerous?","a":"Both are low-risk with a guide, but respect the water. Snorkeling is snorkel-only with no decompression restriction — the real hazards are the open-water current at the reef seam, boat traffic and sun, so wear the vest, avoid all coral/wildlife contact and stay with the guide. On the ~30 km crossing, follow crew instructions and keep life jackets on.","source":"nationalparksassociation.org, 2026-07-04","si_tag":"safety"},{"q":"How do you actually visit Isla Contoy?","a":"Only through a handful of authorized operators — there is no independent access. The daily cap of 200 visitors makes it scarcity-priced, so book 3–6+ weeks ahead in peak season (1–3 weeks in shoulder); popular operators and calm-sea days fill first. Every trip bundles the park fee, lunch and snorkel gear.","source":"contoyadventures.com / airial.travel, 2026-07-04","si_tag":"expedition"},{"q":"What is the Ixlaché reef snorkel like?","a":"It is the headline in-water stop — the northern start of the world''s second-largest barrier reef. Ixlaché holds 17 hard and 14 soft coral species just south of the island; visibility is clearest in the dry season (Dec–Apr), and the snorkel is included in the guided tour on calm-sea days.","source":"contoyadventures.com, 2026-07-04","si_tag":"ocean"},{"q":"What wildlife will I see on Isla Contoy?","a":"Birds above all — the island is critical habitat for 173+ species, with frigatebird and pelican colonies you pass on the marked trails. Green and loggerhead sea turtles nest on the beaches May–October, adding a seasonal wildlife hook; the whole reserve is car-free and strictly protected.","source":"nationalparksassociation.org, 2026-07-04","si_tag":"wildlife"},{"q":"When is the best time to visit Isla Contoy, and where do trips leave from?","a":"December–April brings the calmest seas and clearest Ixlaché water; the summer whale-shark run (roughly Jun–Sep) is the true event peak, since Contoy is often sold as a whale-shark + Contoy combo. Trips depart Cancún and Isla Mujeres marinas on ~7–8 hour days — there is no lodging, so base off-island.","source":"isla-seatours.com / machupicchu.org, 2026-07-04","si_tag":"planning"}],"seo":{"meta_title":"Isla Contoy, Mexico: 200-a-Day National Park Island","meta_description":"Uninhabited and capped at 200 visitors a day — Isla Contoy''s bird sanctuary and Ixlaché reef are authorized-tour-only. How to book the trip and what to expect.","slug":"isla-contoy-mexico","primary_keyword":"Isla Contoy national park tour","long_tail":["Isla Contoy 200 visitors per day","Ixlaché reef snorkeling","Isla Contoy bird sanctuary","Isla Contoy day trip from Cancún","Isla Contoy authorized operators"],"search_language":"es-MX (restated, not machine-translated)","local_keywords":["tour a Isla Contoy","Parque Nacional Isla Contoy","snorkel arrecife Ixlaché","santuario de aves Isla Contoy","excursión Isla Contoy desde Cancún","operadores autorizados Isla Contoy","combo tiburón ballena e Isla Contoy"],"hreflang":["en","es-MX"],"jsonld_type":"TouristAttraction","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-04"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"live"},{"si":"ocean","status":"future"},{"si":"wildlife","status":"future"}],"ultra":[{"name":"NONE - uninhabited national park, no lodging","why_ultra":"Isla Contoy is an uninhabited national park: no hotels/villas/lodging, no overnight permitted - day-trip add-on, not a stay. Ultra play lives off-island (Isla Mujeres Impression / Cancún Nizuc / Mayakoba corridor - verify municipality)","earning":"n/a on-island; on application via associated Isla Mujeres/Puerto Morelos dossiers","virtuoso_value_add":"n/a on-island - see associated dossiers","mor":"no on-island revenue; commission captured on associated stay + day-tour","source":"https://nationalparksassociation.org/mexico-national-parks/isla-contoy-national-park/"}],"source_verified":"2026-07-04","hero":{"query":"Isla Contoy, Mexico"},"geo":{"lat":21.4833,"lng":-86.7917}}'::jsonb, 50),
  ('isla-mujeres-mexico', '10S', 'Isla Mujeres', 'Mexico', '*If it''s a golf-cart island with the world''s calmest', 'live', 'verified', 'tropicalBeach', 'Quintana Roo (Cancún & Riviera Maya)', '{"tropical","ocean","diveglobal","adventure"}', '{"tropical"}', '{"comfort","premier"}', null, 'anchor', '{"key_facts":["Whale-shark snorkel capital, roughly June-September (snorkel-only, no scuba)","MUSA statues 3.5-8 m deep - divable by Open Water divers and snorkelers","Punta Sur summer loggerhead-turtle mating aggregation in strong currents","Playa Norte among the region''s most sargassum-protected beaches","Short ferry from Cancún; gateway for Isla Contoy day trips"],"safety":{"emergency":"911","hospital":"local clinic; major trauma in Cancún (Galenia/Hospiten - verify); hyperbaric via SSS Cancún / Cozumel","advisory_level":"L2","malaria":"none in QR tourist zones (verify); dengue precautions","yellow_fever":"none required"},"timing":{"peak":"Dec-Apr (region dry/high season) + Jun-Sep whale-shark event peak (snorkel-only)","shoulder":"May-Jun & Nov (~30-40% off winter rates)","green":"Jun-mid-Oct (hurricane season, ~40-60% off; whale-shark peak sits inside it)","booking_lead":"whale-shark tours ~30-39 days (book 3-6 wks ahead, sells out summer); shoulder beds 2-4 wks; ultra/boutique suites Dec-Apr + holidays 3-6+ months","off_season_specials":"green-season play = discounted island bed + premium whale-shark excursion (''cheap bed, peak wildlife''); disclose hurricane/sargassum","event_peaks":"Christmas-New Year, US spring break (Mar); whale-shark open (early Jun) + Jul-Aug midsummer height","campaign_start":"whale-shark Mar-Apr (6-8 wks pre-open); winter/honeymoon-suite Aug-Sep; green-season value Apr-May"},"jewels":[{"name":"Whale-shark snorkel departures","si_tag":"ocean","status":"future","tier":"comfort","hook":"island boats to the aggregation, Jun-Sept, snorkel-only","bookable_category":"boat snorkel excursion","commission_path":"DMC/local operator → OTA affiliate","source":"https://mexicodivers.com/","si":"ocean","blurb":"island boats to the aggregation, Jun-Sept, snorkel-only","commission":"DMC/local operator → OTA affiliate"},{"name":"MUSA south wing","si_tag":"diveglobal","status":"future","tier":"comfort","hook":"shallow sculpture reef divable by beginners and snorkelers","bookable_category":"dive/snorkel tour","commission_path":"local dive-op → OTA affiliate","source":"https://www.bluewaterdivetravel.com/scuba-musa-isla-mujeres-cancun","timing":"Dec-Apr  + Jun-Sep whale-shark event peak","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","blurb":"shallow sculpture reef divable by beginners and snorkelers","when":"Dec-Apr  + Jun-Sep whale-shark event peak","commission":"local dive-op → OTA affiliate"},{"name":"Punta Sur loggerhead-turtle dive","si_tag":"diveglobal","status":"future","tier":"premier","hook":"summer mating aggregation in south-point current","bookable_category":"guided drift dive","commission_path":"local dive-op (advanced) → curated-recommend","source":"https://www.pocnadivecenter.com/post/scuba-diving-with-loggerheads-in-isla-mujeres","si":"diveglobal","blurb":"summer mating aggregation in south-point current","commission":"local dive-op (advanced) → curated-recommend"},{"name":"Playa Norte at dawn","si_tag":"tropical","status":"live","tier":"comfort","hook":"waist-deep glass-calm turquoise, sargassum-protected","bookable_category":"hotel + ferry","commission_path":"bed-bank/boutique portal → OTA; ferry pass-through","source":"https://www.howisthesargassum.com/blog/cancun-hurricane-season-2026","timing":"Dec-Apr  + Jun-Sep whale-shark event peak","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"tropical","blurb":"waist-deep glass-calm turquoise, sargassum-protected","when":"Dec-Apr  + Jun-Sep whale-shark event peak","commission":"bed-bank/boutique portal → OTA; ferry pass-through"},{"name":"Isla Contoy day trip","si_tag":"globaladv","status":"future","tier":"comfort","hook":"200/day capped bird-sanctuary reserve + Ixlaché reef","bookable_category":"authorized eco day tour","commission_path":"authorized Contoy operator/DMC → curated (fee pass-through)","source":"https://contoyadventures.com/isla-contoy/","timing":"Dec-Apr  + Jun-Sep whale-shark event peak","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"adventure","blurb":"200/day capped bird-sanctuary reserve + Ixlaché reef","when":"Dec-Apr  + Jun-Sep whale-shark event peak","commission":"authorized Contoy operator/DMC → curated (fee pass-through)"}],"faq":[{"q":"Is Isla Mujeres safe to visit right now?","a":"Yes — freely bookable, no hold. Isla Mujeres sits in Quintana Roo, which carries a standard US State Dept Level 2 \"Exercise Increased Caution\" (dated 2026-05-29). It is a small, calm golf-cart island; it has a local clinic, with major trauma care a short ferry and drive away in Cancún (Galenia, Hospiten).","source":"travel.state.gov","si_tag":"safety"},{"q":"What''s the real risk to plan for on Isla Mujeres?","a":"Water, weather and currents — not crime. Drink bottled water, use repellent for dengue (no malaria in the tourist zone), and note hurricane season runs June–November with September riskiest. Playa Norte is comparatively sargassum-protected, but 2026 is heavy region-wide; the Punta Sur loggerhead dives sit in strong currents, so they are for advanced divers only.","source":"howisthesargassum.com","si_tag":"safety"},{"q":"Is swimming with whale sharks or diving Punta Sur dangerous?","a":"The whale-shark encounter is snorkel-only with no decompression restriction — wear the vest, no touching, stay with the guide against boat traffic and open-water current. Punta Sur''s summer loggerhead dive is a strong-current drift for advanced divers with a local guide; observe no-fly of 18–24 hours after any scuba.","source":"pocnadivecenter.com","si_tag":"safety"},{"q":"When and how can I swim with whale sharks from Isla Mujeres?","a":"Roughly June to September, on a snorkel-only boat excursion to the aggregation — the island is the whale-shark snorkel capital of the region. Tours book about 30–39 days out on average and sell out fast in peak summer, so reserve at least 3–6 weeks ahead; it is snorkel-only, with no scuba allowed.","source":"mexicodivers.com","si_tag":"ocean"},{"q":"Can beginners dive MUSA from Isla Mujeres?","a":"Yes — MUSA is one of the most accessible dives anywhere. Its 470+ statues sit just 3.5–8 m down, shallow enough for Open Water divers and snorkelers, and at ≤9 m these are easy day dives. Advanced divers can add the Punta Sur loggerhead drift in summer, which sits in strong current and is guided-only.","source":"bluewaterdivetravel.com","si_tag":"diveglobal"},{"q":"Is Playa Norte good, and will sargassum ruin it?","a":"It is the island''s signature beach — waist-deep, glass-calm turquoise you can wade out a hundred meters into — and one of the most sargassum-protected stretches in the region. In a heavy year like 2026 that protection is a genuine edge, but still disclose: no beach is fully immune, and mornings are cleanest.","source":"howisthesargassum.com","si_tag":"tropical"}],"seo":{"meta_title":"Isla Mujeres, Mexico: Whale Sharks, MUSA & Playa Norte","meta_description":"A golf-cart island off Cancún — snorkel the whale-shark run, dive MUSA and Punta Sur loggerheads, and wade Playa Norte''s calm turquoise. Season, safety, booking.","slug":"isla-mujeres-mexico","primary_keyword":"Isla Mujeres whale shark snorkeling","long_tail":["Isla Mujeres MUSA diving","Playa Norte Isla Mujeres","Punta Sur loggerhead turtles","Isla Mujeres whale shark season","Isla Contoy tour from Isla Mujeres"],"search_language":"es-MX (restated, not machine-translated)","local_keywords":["nadar con tiburón ballena Isla Mujeres","buceo MUSA Cancún","Playa Norte Isla Mujeres","temporada de tiburón ballena","tortugas caguama Punta Sur","qué hacer en Isla Mujeres","villas de lujo Isla Mujeres"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-04"},"booking":{"bin":"freely_bookable","level":"L2","codes":[],"consent_flow":false,"note":"Quintana Roo/Mexico US L2 (Exercise Increased Caution) - freely bookable; MXN currency, USD widely accepted"},"si_checklist_25":{"run_date":"2026-07-31","hits":7,"misses":15,"disregarded":3,"note":"Canonical 25-SI list; sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"tropical","name":"tropical","status":"live"},{"si":"ocean","name":"ocean","status":"future"},{"si":"diveglobal","name":"diveglobal","status":"future"},{"si":"globaladv","name":"adventure","status":"future"}],"ultra":[{"name":"Impression Isla Mujeres by Secrets","why_ultra":"125 all-suite adults-only, butler + Endless Privileges, 8 restaurants, private catamaran transfer; ''Most Instagrammable Hotel in the World'' 2 yrs running — island''s true ultra flagship","earning":"on application / via host-Virtuoso (Hyatt Inclusive Collection); verify %","virtuoso_value_add":"verify Virtuoso/Hyatt Prive amenities - not documented","mor":"commission-on-net; no net-rate resale markup","source":"https://www.hyattinclusivecollection.com/en/resorts-hotels/impression-by-secrets/mexico/isla-mujeres/"},{"name":"Mia Reef Isla Mujeres (All-Inclusive)","why_ultra":"private-island feel at Playa Norte tip, dock-connected, 93 rooms + 63 suites, King''s Pool snorkel lagoon — upper-luxe marquee, not five-diamond (reviews flag dated facilities)","earning":"on application via host/OTA; verify","virtuoso_value_add":"verify - not documented","mor":"commission-on-net; no resale markup","source":"https://www.tripadvisor.com/Hotel_Review-g150810-d259074-Reviews-Mia_Reef_Isla_Mujeres-Isla_Mujeres_Yucatan_Peninsula.html"},{"name":"Nearest true ultra: Cancún Nizuc / Playa Mujeres / Mayakoba corridor (mainland)","why_ultra":"AAA Five-Diamond / Virtuoso-preferred ultra is mainland (Nizuc, Mayakoba Rosewood/Banyan Tree/Fairmont/Andaz); Isla Mujeres = day-trip / honeymoon-island add-on","earning":"on application - see Puerto Morelos/Mayakoba dossier","virtuoso_value_add":"see corridor dossier","mor":"commission-on-net","source":"https://www.jetsetchristina.com/where-to-stay-in-mayakoba-mexico-rosewood-vs-fairmont-vs-andaz-vs-banyan-tree/"}],"source_verified":"2026-07-04","hero":{"query":"Isla Mujeres, Mexico"},"geo":{"lat":21.2311,"lng":-86.7311}}'::jsonb, 51),
  ('izamal-mexico', '10S', 'Izamal', 'Mexico', '*If it''s a whole city painted the color of', 'live', 'verified', 'kyoto', 'Yucatán (Mérida & Chichén Itzá)', '{"culture","romance","culinary"}', '{}', '{"comfort","premier","ultra"}', null, null, '{"key_facts":["Mexico''s FIRST Pueblo Mágico, designated 2002-02-16 — launched the entire Magical Towns program","Convento de San Antonio de Padua founded 1549 / completed 1561 atop a Maya temple; 75-arch atrium among the largest monastery atriums in the world","Kinich Kakmó pyramid ~200m x ~180m, c. 400-600 AD, dedicated to the Maya sun god, climbable to the summit","Pope John Paul II visited August 1993; standardized ochre-yellow color tradition dates to that visit (''the Yellow City'')","~70 km / ~1h10 from Mérida — an easy day-trip, roughly midway toward Chichén Itzá"],"safety":{"emergency_number":"911","nearest_trauma":"Mérida (~1h10 west; regional hospital hub)","advisory_level":"L1","book_enabled":true,"air_access_verified":true,"air_access_note":"MID Mérida ~1h10 drive; US nonstops incl. Houston, Miami, Dallas, Atlanta","primary_hazards":["heat/sun exposure (shadeless plazas + exposed pyramid climb)","Kinich Kakmó footing (steep, handrail-free Maya steps)","calesa/town traffic (low)","dengue (rainy season)","non-potable tap water"],"climbing_note":"Kinich Kakmó IS climbable to summit — genuine draw; steep uneven risers, no handrails"},"timing":{"inflection_curve_start":"2026-11-01","peak":"2026-12 to 2027-04","shoulder":"2026-05 to 2026-10 (hot/humid; hurricane exposure Aug-Oct; year-round photo baseline)","fire_date":"2026-10-20","trigger_rule":"curve-start minus 1-2 weeks; front-runs both dry-season inflection and Hanal Pixán; attaches to Mérida-base / in-town boutique lead time","booking_lead_days":{"day_tour":"2-7","in_town_boutique":"7-28","merida_base_high_season":"28-84"},"event_peaks":["Hanal Pixán / Día de Muertos 2026-10-31 to 2026-11-02 (headline)","year-round artisan & photo-travel demand","calesa demand steady all year"],"note":"sharpen on live tracking — Mérida occupancy + Izamal Pueblo-Mágico visitor counts + Hanal Pixán calendar"},"jewels":[{"name":"Convento de San Antonio de Padua (golden convent, sunset)","si_tag":"culture_heritage","commission_path":"non-commissionable entry; anchors tour + sunset-stay night","source":"https://www.atlasobscura.com/places/yellow-city-of-izamal | Accessed 2026-07-06","si":"culture","commission":"non-commissionable entry; anchors tour + sunset-stay night","accessed":"2026-07-06"},{"name":"Kinich Kakmó pyramid (climbable)","si_tag":"culture_heritage","tier":"comfort","commission_path":"day-tour inclusion (guiding); entry non-commissionable","source":"https://tourtochichenitza.com/destinations/izamal | Accessed 2026-07-06","hook":"Unlike El Castillo at Chichén, Izamal''s Kinich Kakmó is climbable to the summit for rooftop views over the yellow city.]","si":"culture","blurb":"Unlike El Castillo at Chichén, Izamal''s Kinich Kakmó is climbable to the summit for rooftop views over the yellow city.]","commission":"day-tour inclusion (guiding); entry non-commissionable","accessed":"2026-07-06"},{"name":"Pope John Paul II heritage (1993 visit, JP-II statue)","si_tag":"culture_heritage","tier":"comfort","commission_path":"guided-tour narrative anchor; faith-travel draw","source":"https://en.wikipedia.org/wiki/Izamal | Accessed 2026-07-06","si":"culture","commission":"guided-tour narrative anchor; faith-travel draw","accessed":"2026-07-06"},{"name":"Centro Cultural y Artesanal (folk-art museum + workshops)","si_tag":"culture_heritage","tier":"comfort","commission_path":"experience add-on (affiliate/Viator); workshop packages","source":"https://themexicoreport.com/entrepreneurs-preserve-mayan-culture-and-traditions-at-centro-cultural-y-artesanal-in-izamal-yucatan/ | Accessed 2026-07-06","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","when":"year-round","commission":"experience add-on (affiliate/Viator); workshop packages","accessed":"2026-07-06"},{"name":"Sunset calesa (horse-carriage) ride","si_tag":"romance","tier":"comfort","commission_path":"bookable experience add-on (Viator/GetYourGuide; Host for private)","source":"https://tourtochichenitza.com/destinations/izamal | Accessed 2026-07-06","hook":"low-speed, low-risk, but shared with light town traffic; standard care boarding/alighting. Guided calesa tours are the norm and low-hazard","si":"romance","blurb":"low-speed, low-risk, but shared with light town traffic; standard care boarding/alighting. Guided calesa tours are the norm and low-hazard","commission":"bookable experience add-on (Viator/GetYourGuide; Host for private)","accessed":"2026-07-06"},{"name":"Golden-hour photo circuit (yellow arcades + convent)","si_tag":"romance","tier":"premier","commission_path":"private photo-tour upsell; drives one-night boutique room-night","source":"https://www.bontraveler.com/izamal-yucatan-mexico-yellow-city/ | Accessed 2026-07-06","si":"romance","commission":"private photo-tour upsell; drives one-night boutique room-night","accessed":"2026-07-06"},{"name":"Hammock & artisan workshops (huipil, alebrijes)","si_tag":"culinary","tier":"comfort","commission_path":"artisan-experience + retail add-on; Centro Cultural packages","source":"https://yucatantoday.com/en/blog/yucatans-most-iconic-handcrafts-artisan-towns | Accessed 2026-07-06","si":"culinary","commission":"artisan-experience + retail add-on; Centro Cultural packages","accessed":"2026-07-06"},{"name":"Santa Bárbara cenotes (nearby, ~49 km)","si_tag":"romance","tier":"comfort","commission_path":"adventure add-on (operator/Viator)","source":"https://tourtochichenitza.com/destinations/izamal | Accessed 2026-07-06","si":"romance","commission":"adventure add-on (operator/Viator)","accessed":"2026-07-06"}],"faq":[{"q":"Why is Izamal called the Yellow City, and what makes it special?","a":"It is Mexico''s first Pueblo Mágico (designated 2002), and the entire historic center is painted one standardized ochre-gold — a color tradition set for Pope John Paul II''s August 1993 visit and maintained ever since. The city is built in layers: the Spanish set the great Franciscan convent atop a Maya temple, and the Kinich Kakmó sun-god pyramid still rises above the rooftops.","source":"en.wikipedia.org / casaloltun.com, 2026-07-06","si_tag":"culture"},{"q":"Can you climb the pyramid in Izamal?","a":"Yes — Kinich Kakmó is climbable to the summit, which sets it apart from Chichén Itzá, where El Castillo has been closed to climbers since 2008. The ~200 × 180 m pyramid dates to c. 400–600 AD; the steps are steep, uneven Maya risers with no handrails, so wear sturdy shoes and mind your footing on the descent.","source":"tourtochichenitza.com, 2026-07-06","si_tag":"culture"},{"q":"Is Izamal good for a romantic day or honeymoon?","a":"Yes — it is a golden-hour romance magnet. The convent glows like a lantern above the plaza at sunset, a 45–60 min horse-drawn calesa ride winds through the yellow arcades, and the light seems to come from the buildings themselves. Most couples day-trip it from Mérida (70 km / ~1h10) or book one night in an in-town boutique to shoot the convent at golden hour.","source":"bontraveler.com, 2026-07-06","si_tag":"romance"},{"q":"What is there to do beyond the convent?","a":"Hands-on Maya craft: the Centro Cultural y Artesanal runs artisan workshops and tours to hammock weavers, huipil embroiderers and alebrije painters who often work in-shop while you eat. Yucatecan cuisine and Hanal Pixán (the Maya Day of the Dead food tradition) give a soft culinary layer for later.","source":"yucatantoday.com, 2026-07-06","si_tag":"culinary"},{"q":"Is Izamal safe right now?","a":"Yes — freely bookable. Izamal is a small, calm Pueblo Mágico in Yucatán, one of only two Mexican states rated US State Dept Level 1 \"Exercise Normal Precautions.\" Normal precautions suffice; the town is comfortably self-guided on foot.","source":"travel.state.gov, 2026-07-06","si_tag":"safety"},{"q":"What''s the real risk to plan for in Izamal?","a":"Heat and footing, not crime. The shadeless plazas and the exposed, handrail-free Kinich Kakmó climb get hot at midday, so carry water, a hat and sunscreen and shoot golden hour rather than noon. Izamal has local clinics only — the nearest full trauma care is Mérida, ~1h10 west.","source":"travel.state.gov, 2026-07-06","si_tag":"safety"}],"seo":{"jsonld_type":"TouristAttraction","meta_title":"Izamal, the Yellow City: Pueblo Mágico Guide (2026) | TravelWell.World","search_language":"en","local_keywords":["Izamal ciudad amarilla","Convento Izamal","Convento de San Antonio de Padua","pirámide Kinich Kakmó","calesa Izamal","Pueblo Mágico Izamal","artesanías Izamal"],"long_tail_en":["Izamal yellow city guide 2026","Izamal from Mérida day trip","Convento San Antonio de Padua Izamal","Kinich Kakmó pyramid climb","Izamal calesa horse carriage ride","Izamal sunset photography"],"hreflang":["en","es-MX"],"author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-06"},"booking":null,"si_checklist_25":null,"sis_present":["culture_heritage","romance","culinary"],"ultra":[{"name":"Hotel San Miguel Arcángel (in-town)","tier":"premier_boutique","earning_path":"Host FIT / MoR","note":"ceiling in-town; no true ultra hotel in Izamal itself","source":"https://yucatantoday.com/en/izamal/ | Accessed 2026-07-06"},{"name":"Chablé Yucatán","tier":"ultra","earning_path":"Virtuoso / Fora","note":"nearest ultra; ~30 min Mérida; #13 World''s Best Hotels 2023","source":"https://www.virtuoso.com/travel/luxury-hotels/15452675/chable-yucatan | Accessed 2026-07-06"},{"name":"Hacienda Temozón (Luxury Collection)","tier":"ultra","earning_path":"Virtuoso / Marriott STARS / Fora / MoR","note":"28-room grand hacienda","source":"https://www.travelweekly.com/Hotels/Abala-Mexico/Hacienda-Temozon-Luxury-Collection-p51093491 | Accessed 2026-07-06"},{"name":"Hacienda Santa Rosa (Luxury Collection)","tier":"ultra","earning_path":"Virtuoso / Marriott STARS / MoR","note":"intimate 11 rooms","source":"https://www.letstraveltomexico.com/yucatan-haciendas/ | Accessed 2026-07-06"}],"source_verified":"2026-07-06","hero":{"query":"Izamal, Mexico"},"geo":{"lat":20.9308,"lng":-89.0175}}'::jsonb, 52)
