  ('jericoacoara-brazil', '10S', 'Jericoacoara & the Ceará Coast, Brazil', 'Brazil', 'Jericoacoara & the Ceará Coast', 'live', 'verified', 'tropicalBeach', 'Northeast Beaches & Bahia', '{"tropical","romance"}', '{"tropical"}', '{"essential","comfort","premier"}', null, null, '{"key_facts":null,"safety":{"emergency":"190","advisory_level":"L2","advisory_source":"US State Dept, issued 2025-05-29","book_enabled":true,"bin":"freely bookable (L2)","consent_flow":false,"air_access_verified":true,"air_access":["JJD (Jericoacoara Airport, ~35 min transfer)","FOR (Fortaleza/Pinto Martins) + 4-5 hr authorized 4x4 dune transfer (~300 km)"],"remote_flag":true,"trauma_note":"Remote, road-less; definitive care/evac via Fortaleza then US air evac; factor 4x4-only ground leg; med-evac insurance advised","water_hazards":["riptides/strong currents","shorebreak","strong-wind open-water kite hazard"],"environmental":["high UV / sun exposure","dune heat","minimal shade"]},"timing":{"peak":"Jul-Dec (kite season; dry; wind nearly daily, 20-25kt building to 30-35kt Sep-Nov, strongest Nov)","spike":"Reveillon ~Dec26-Jan3 (20,000+ visitors, >98% occupancy, AYA + LABRYINTO festivals)","inflection":"late Jun / early Jul (wind curve starts)","green_rainy":"Feb-May (lighter wind ~55-65% good days, fuller lagoons, quiet, value)","fire_date":"mid-to-late June (kite-curve start minus 1-2 weeks)","off_season_fill":"Feb-May romance + lagoon-hammock + value tiers"},"jewels":[{"name":"Sunset Dune (Duna do Pôr do Sol) + capoeira","si_tag":"Tropical/Beaches","tier":"essential","commission_path":"free ritual → anchor pousada stay + F&B add-on","source":"https://www.nextstopbrazil.com/destinations/jericoacoara","timing":"Jul-Dec","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the nightly pilgrimage; sun into the sea, drums on the sand below","si":"Tropical/Beaches","blurb":"the nightly pilgrimage; sun into the sea, drums on the sand below","when":"Jul-Dec","commission":"free ritual → anchor pousada stay + F&B add-on"},{"name":"Lagoa do Paraíso hammocks-in-water","si_tag":"Tropical/Beaches","tier":"essential","commission_path":"buggy day-tour + lagoon-bar F&B","source":"https://beachtraveldestinations.com/jericoacoara/","timing":"Jul-Dec","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"wooden hammocks set in a crystal freshwater lagoon; the signature Jeri postcard","si":"Tropical/Beaches","blurb":"wooden hammocks set in a crystal freshwater lagoon; the signature Jeri postcard","when":"Jul-Dec","commission":"buggy day-tour + lagoon-bar F&B"},{"name":"Pedra Furada arch","si_tag":"Tropical/Beaches","tier":"essential","commission_path":"guided coastal walk / photo tour add-on","source":"https://www.nextstopbrazil.com/destinations/jericoacoara","timing":"Jul-Dec","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Pedra Furada, a wind-and-sea-carved stone arch, is a ~45-minute coastal walk from the village","si":"Tropical/Beaches","blurb":"Pedra Furada, a wind-and-sea-carved stone arch, is a ~45-minute coastal walk from the village","when":"Jul-Dec","commission":"guided coastal walk / photo tour add-on"},{"name":"Kite at Preá / Guriú","si_tag":"expedition","tier":"essential","commission_path":"IKO school package + kite-hotel stay","source":"https://landedtravel.com/rancho-do-peixe/","timing":"Jul-Dec","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Preá''s flat, steady wind is the training and cruising ground just outside the park; Guriú''s river-and-mangrove approach","si":"expedition","blurb":"Preá''s flat, steady wind is the training and cruising ground just outside the park; Guriú''s river-and-mangrove approach","when":"Jul-Dec","commission":"IKO school package + kite-hotel stay"},{"name":"Tatajuba dunes + freshwater lagoon","si_tag":"expedition","tier":"essential","commission_path":"full-day private buggy (~R$300-500/4pax)","source":"https://www.getyourguide.com/jericoacoara-l105737/jericoacoara-tatajuba-beach-and-buggy-ride-t229207/","timing":"Jul-Dec","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"village half-swallowed by dunes, a magical freshwater lagoon with rafts, waterslide, SUP, and submerged hammocks, ~25 km by buggy via a ferry-crossing at Guriú","si":"expedition","blurb":"village half-swallowed by dunes, a magical freshwater lagoon with rafts, waterslide, SUP, and submerged hammocks, ~25 km by buggy via a ferry-crossing at Guriú","when":"Jul-Dec","commission":"full-day private buggy (~R$300-500/4pax)"},{"name":"Buggy the Rota das Emoções","si_tag":"expedition","tier":"comfort","commission_path":"multi-day DMC land package (AOR)","source":"https://planetaexo.com/trips/pt/a/rota-das-emocoes-6-dias-lencois-jericoacoara","timing":"Jul-Dec","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the epic dune-buggy/4x4 arc Jeri → Delta do Parnaíba → Lençóis Maranhenses","si":"expedition","blurb":"the epic dune-buggy/4x4 arc Jeri → Delta do Parnaíba → Lençóis Maranhenses","when":"Jul-Dec","commission":"multi-day DMC land package (AOR)"},{"name":"Lençóis Maranhenses extension (via Barreirinhas/Atins)","si_tag":"romance","tier":"comfort","commission_path":"multi-day romance package via Rota das Emoções DMC (AOR)","source":"https://ambiental.tur.br/destinos/jericoacoara-delta-e-lencois-maranhenses-com-atins/","timing":"Jul-Dec","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the surreal blue-lagoon-in-white-dunes national park ~500 km west via the Rota das Emoções, staged from Barreirinhas or the barefoot village of Atins","si":"romance","blurb":"the surreal blue-lagoon-in-white-dunes national park ~500 km west via the Rota das Emoções, staged from Barreirinhas or the barefoot village of Atins","when":"Jul-Dec","commission":"multi-day romance package via Rota das Emoções DMC (AOR)"},{"name":"Candlelit fresh-fish + terrace-pool sunset","si_tag":"romance","tier":"premier","commission_path":"luxe pousada F&B + honeymoon package","source":"https://www.humboldttravel.co.uk/hotel/pousada-vila-kalango/","timing":"Jul-Dec","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Vila Kalango''s open-air candlelit fish dinner and sunset-magnet terrace pool","si":"romance","blurb":"Vila Kalango''s open-air candlelit fish dinner and sunset-magnet terrace pool","when":"Jul-Dec","commission":"luxe pousada F&B + honeymoon package"}],"faq":[{"q":"When is the best time to kitesurf in Jericoacoara?","a":"July–December is kite season because the dry-season trade wind blows nearly every day, running ~20–25 kt and building to 30–35 kt on September–November afternoons (strongest in November). This wind is the demand engine, so book schools and pousadas early — the curve switches on around late June / early July.","source":"wakeupstoked.com, Accessed 2026-07-07","si_tag":"expedition"},{"q":"What is there to do in Jericoacoara besides the beach?","a":"The signature rituals are free and natural: climb the Sunset Dune (Duna do Pôr do Sol) at dusk to watch the sun drop straight into the Atlantic — one of the few places in Brazil where it does — walk ~45 minutes to the Pedra Furada arch, and float in the wooden hammocks set in the shallows of crystal-clear Lagoa do Paraíso.","source":"nextstopbrazil.com, Accessed 2026-07-07","si_tag":"tropical"},{"q":"Is Jericoacoara good for a honeymoon?","a":"Yes, but set expectations at barefoot-luxe, not palace-luxury — exquisite bungalows, sand floors and candlelight. Vila Kalango (24 beachfront bungalows, MICHELIN Guide) anchors the lane, and the green Feb–May shoulder sells the quiet, glassy-lagoon honeymoon version when the pousadas discount.","source":"guide.michelin.com, Accessed 2026-07-07","si_tag":"romance"},{"q":"Is Jericoacoara safe right now?","a":"Yes — it is freely bookable at Level 2, with `book_enabled = true` and no consent flow. Brazil''s national L2 (issued 2025-05-29) is driven by crime and kidnapping risk, but its high-risk carve-outs — favelas, land-border zones, Brasília satellite cities at night — do not apply to this small protected village on the Ceará coast.","source":"travel.state.gov, Accessed 2026-07-07","si_tag":"safety"},{"q":"What''s the real risk to plan for?","a":"Remoteness. Jeri is road-less, so definitive trauma care and complex medical evacuation route through Fortaleza — a 4x4-only, ~4–5 hr ground leg (or JJD air) — then international air evac as needed. Factor that into any emergency-response estimate; travel insurance with medical-evacuation cover is strongly advised.","source":"portaljericoacoara.com.br, Accessed 2026-07-07","si_tag":"safety"},{"q":"Is kitesurfing in Jericoacoara dangerous?","a":"Manageable with the right school: use IKO-certified schools (Rancho do Peixe/Ticowind, Preá Kite Club, North Kite Center, BLU). Central-Jeri offshore wind is not for beginners — they route to Preá''s flat water — and deep-water sessions warrant a life jacket, with a local briefing mandatory because of open-water current.","source":"ikointl.com, Accessed 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Jericoacoara & the Ceará Coast, Brazil — Kitesurf Capital, Sunset Dune & Barefoot-Luxe Pousadas | TravelWell.World","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","freshness":"2026-07-07","search_language":"pt-BR","local_keywords":["Jericoacoara o que fazer","kitesurf Jeri","Lagoa do Paraíso","Duna do Pôr do Sol Jeri","Pedra Furada Jericoacoara","transfer Fortaleza Jericoacoara 4x4","Réveillon Jericoacoara","Rota das Emoções roteiro","pousada Jericoacoara frente mar"],"hreflang":["en","pt-BR"],"primary_keyword":"Jericoacoara & the Ceará Coast"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"tropical","status":"live"},{"si":"romance","status":"live"}],"ultra":[{"name":"Vila Kalango","positioning":"24 beachfront bungalows, MICHELIN Guide, watersports center, candlelit fish","earning":"luxe-pousada commission + package cross-sell","mor":"package via DMC","tier":"premier"},{"name":"Essenza Hotel","positioning":"30-room 5-star, infinity pool, direct beach, sunset-dune views","earning":"affiliate + direct commission","mor":"room affiliate → package","tier":"premier","flag":"Relais & Chateaux affiliation NOT verified — do not claim"},{"name":"My Blue Hotel","positioning":"beachfront, spa, swim-up bar — premium boutique","earning":"affiliate + direct","mor":"room affiliate","tier":"$$"},{"name":"Casa Nomade","positioning":"boutique per prompt — UNVERIFIED this pass","earning":"hold until confirmed","mor":"-","tier":"flag"}],"source_verified":null,"hero":{"query":"Jericoacoara & the Ceará Coast, Brazil, Brazil"},"geo":{"lat":-2.7936,"lng":-40.514}}'::jsonb, 53),
  ('la-fortuna-arenal-costa-rica', '10S', 'La Fortuna / Arenal', 'Costa Rica', 'La Fortuna Costa Rica', 'live', 'verified', 'mountainValley', 'Costa Rica', '{"expedition","romance","wellness"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, null, '{"key_facts":["La Fortuna Waterfall drops ~246 ft into a swimmable jade pool below the Arenal cone","Arenal is an active volcano — no summit hikes; hike the 1968 Trail / National Park loops only","Hot springs run ~90-104F, heated by the volcano; resorts range essential to ultra","Whitewater: Rio Balsa (Class II-III family) and Rio Sarapiqui (Class III-IV)","~3-3.5 hr private transfer from San Jose (SJO); local La Fortuna airstrip for small aircraft"],"safety":{"emergency":"911","hospital":"Fortuna Medical Center (La Fortuna, 24hr, +506 6065-9911); Hospital San Carlos Ciudad Quesada (~1hr); major trauma/evac -> CIMA (+506 2208-1000) or Clinica Biblica (+506 2522-1000) San Jose (~3hr)","advisory_level":"L2","book_enabled":true,"air_access_verified":true,"volcano":"Active but monitored; viewing safe; NO active-cone summit hikes (1968 Trail / Cerro Chato-area / park loops only)","water":"Generally potable tap water; sensitive travelers may prefer bottled","malaria":"Not a significant malaria zone; dengue present year-round (worse May-Nov) — use DEET repellent"},"timing":{"inflection_curve_start":"~Dec 15 (dry season opens)","peak":"mid-Dec to Apr (25-40% premium); Xmas/NY + Easter super-peak","fire_date":"Dec 1 (general dry-season, curve-start minus 1-2 wks); Oct 1 for 12-mo holiday/ultra inventory","shoulder":"May & November","green":"May-Nov (20-40% lower rates, lush, fullest waterfalls)","booking_lead":"~3 months general; ~12 months Xmas/NY/Easter + ultra thermal resorts","off_season_specials":"green-season resort rate drops 20-40%; May post-Easter + Nov pre-Thanksgiving sweet spots","event_peaks":["US winter holidays Dec 20-Jan 5","US Spring Break/Presidents'' weekend","Easter/Semana Santa"]},"jewels":[{"name":"La Fortuna Waterfall","si_tag":"GEA","status":"live","hook":"246-ft waterfall, swimmable jade pool below the cone","bookable_category":"guided tour/combo","tier":"comfort","commission_path":"Viator/GYG affiliate + DMC bundle (OutsideAgents)","source":"https://www.adventuretourscostarica.com/blog/2026-ultimate-guide-hiking-and-swimming-at-la-fortuna-waterfall","timing":"year-round","timing_type":"ALWAYS-ON","si":"GEA","blurb":"246-ft waterfall, swimmable jade pool below the cone","when":"year-round","commission":"Viator/GYG affiliate + DMC bundle (OutsideAgents)"},{"name":"Rio Celeste (Tenorio NP)","si_tag":"GEA","status":"live","hook":"surreal turquoise river & waterfall day-trip","bookable_category":"guided day tour","tier":"premier","commission_path":"DMC/operator (OutsideAgents)","source":"https://www.adventuretourscostarica.com/tours/rio-celeste-waterfall-hike","timing":"mid-Dec to Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"GEA","blurb":"surreal turquoise river & waterfall day-trip","when":"mid-Dec to Apr","commission":"DMC/operator (OutsideAgents)"},{"name":"Arenal Hanging Bridges","si_tag":"GEA","status":"live","hook":"600-acre reserve, canopy suspension walk","bookable_category":"tour ticket","tier":"comfort","commission_path":"operator/affiliate (OutsideAgents)","source":"https://www.adventuretourscostarica.com/tours/la-fortuna-arenal-volcano-hanging-bridges-waterfall-tour","timing":"year-round","timing_type":"ALWAYS-ON","si":"GEA","blurb":"600-acre reserve, canopy suspension walk","when":"year-round","commission":"operator/affiliate (OutsideAgents)"},{"name":"Whitewater rafting (Balsa II-III / Sarapiqui III-IV)","si_tag":"GEA","status":"live","hook":"family-easy to serious guided rafting","bookable_category":"guided raft","tier":"essential","commission_path":"operator resell / Viator (OutsideAgents)","source":"https://arenalrafting.com/","timing":"mid-Dec to Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"GEA","blurb":"family-easy to serious guided rafting","when":"mid-Dec to Apr","commission":"operator resell / Viator (OutsideAgents)"},{"name":"Venado Caves","si_tag":"GEA","status":"live","hook":"limestone caverns + subterranean river","bookable_category":"guided caving tour","tier":"comfort","commission_path":"operator (OutsideAgents)","source":"https://www.adventuretourscostarica.com/destinations/la-fortuna-arenal","timing":"mid-Dec to Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"GEA","blurb":"limestone caverns + subterranean river","when":"mid-Dec to Apr","commission":"operator (OutsideAgents)"},{"name":"Arenal 1968 Trail / Cerro Chato area","si_tag":"GEA","status":"live","hook":"lava-flow hiking, cone & lake views (no summit)","bookable_category":"guided hike / park entry","tier":"essential","commission_path":"guide fee (OutsideAgents); park entry non-comm","source":"https://www.adventuretourscostarica.com/destinations/la-fortuna-arenal","timing":"mid-Dec to Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"GEA","blurb":"lava-flow hiking, cone & lake views (no summit)","when":"mid-Dec to Apr","commission":"guide fee (OutsideAgents); park entry non-comm"},{"name":"Ecotermales Fortuna","si_tag":"RHM","status":"live","hook":"intimate capacity-capped romantic hot springs","bookable_category":"timed pass / package","tier":"premier","commission_path":"bundle via DMC/resort (OutsideAgents); gate non-comm","source":"https://www.machupicchu.org/arenal-hot-springs-guide-2026-tabacon-baldi-free-options.htm","timing":"year-round","timing_type":"ALWAYS-ON","si":"romance","blurb":"intimate capacity-capped romantic hot springs","when":"year-round","commission":"bundle via DMC/resort (OutsideAgents); gate non-comm"},{"name":"Sloth / nocturnal wildlife night walk","si_tag":"RHM","status":"live","hook":"guided rainforest night hike (sloths, frogs, birds)","bookable_category":"guided walk","tier":"comfort","commission_path":"operator (OutsideAgents)","source":"https://www.adventuretourscostarica.com/destinations/la-fortuna-arenal","timing":"mid-Dec to Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","blurb":"guided rainforest night hike (sloths, frogs, birds)","when":"mid-Dec to Apr","commission":"operator (OutsideAgents)"},{"name":"Coffee & chocolate (cacao) tour","si_tag":"WELLNESS_THERMAL/CULTURE","status":"future","hook":"farm-to-cup + bean-to-bar half-day","bookable_category":"guided tour","tier":"comfort","commission_path":"operator/affiliate (OutsideAgents)","source":"https://www.adventuretourscostarica.com/destinations/la-fortuna-arenal","timing":"mid-Dec to Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"WELLNESS_THERMAL/CULTURE","blurb":"farm-to-cup + bean-to-bar half-day","when":"mid-Dec to Apr","commission":"operator/affiliate (OutsideAgents)"},{"name":"Lake Arenal SUP / windsurf","si_tag":"GEA","status":"live","hook":"Costa Rica''s largest lake + wind corridor","bookable_category":"rental / lesson","tier":"comfort","commission_path":"operator (OutsideAgents)","source":"https://www.adventuretourscostarica.com/destinations/la-fortuna-arenal","si":"GEA","blurb":"Costa Rica''s largest lake + wind corridor","commission":"operator (OutsideAgents)"}],"faq":[{"q":"Can you climb Arenal Volcano?","a":"No — you cannot summit Arenal, because it is an active volcano. The hikeable product is the Arenal 1968 Trail and the National Park loops, walking hardened lava flows with lake-and-cone views; the active cone itself is closed to hikers.","source":"adventuretourscostarica.com, 2026-07-06","si_tag":"expedition"},{"q":"Which Arenal hot springs are best for couples?","a":"Ecotermales Fortuna is the romantic pick. It is intimate and capacity-capped — romantic, not a waterpark — at a $59 timed pass, a better couples fit than the larger complexes like Baldi ($85), The Springs ($75) or Tabacón (~$99–110).","source":"machupicchu.org, 2026-07-06","si_tag":"romance"},{"q":"How hot are the Arenal hot springs?","a":"They run roughly 90–104°F. The mineral water is heated by the volcano itself, and the region''s best springs have been built around by high-end resorts, rustic lodges and luxury hotels — hydrate, limit soak time and go easy on alcohol in the heat.","source":"adventuretourscostarica.com, 2026-07-06","si_tag":"wellness"},{"q":"Is La Fortuna safe to visit right now?","a":"Yes, with standard caution. Costa Rica is U.S. Level 2 — Exercise Increased Caution (reissued April 2, 2026, crime), the same tier as France, Italy and the UK; watch belongings, don''t leave valuables in cars, avoid poorly-lit streets after dark and don''t resist a robbery.","source":"travel.state.gov, 2026-07-06","si_tag":"safety"},{"q":"Is the Arenal volcano dangerous to visit?","a":"No — Arenal is an active but monitored volcano, and guided viewing is the whole point. The one hard rule is no summit hikes on the active cone; only the 1968 Trail, Cerro Chato-area and National Park loops are open to hikers.","source":"adventuretourscostarica.com, 2026-07-06","si_tag":"safety"},{"q":"Is whitewater rafting near La Fortuna safe?","a":"Yes, with a licensed guided operator. The rivers run both easy and serious — Class II–III family rafting on the Río Balsa and Class III–IV on the Río Sarapiquí — always guided, with PFDs and helmets standard; book class-appropriate to the group.","source":"arenalrafting.com, 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"La Fortuna & Arenal Volcano, Costa Rica — Hot Springs, Waterfalls & Adventure | TravelWell.World","meta_description":"Plan La Fortuna / Arenal: active-volcano hikes, the 246-ft La Fortuna Waterfall, whitewater rafting, hanging bridges, and world-class hot springs — from Nayara to Tabacon. Expert, sourced, bookable.","slug":"la-fortuna-arenal-costa-rica","primary_keyword":"La Fortuna Costa Rica","long_tail":["Arenal Volcano hot springs","things to do in La Fortuna","La Fortuna Waterfall hike","Nayara Tented Camp Arenal","La Fortuna vs Monteverde"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-06","search_language":"es-CR","local_keywords":["qué hacer en La Fortuna","aguas termales Arenal","volcán Arenal tour","catarata La Fortuna","rafting río Balsa","puentes colgantes Arenal"],"hreflang":["en","es-CR"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"live"},{"si":"romance","status":"live"},{"si":"wellness","status":"future"}],"ultra":[{"name":"Nayara Tented Camp","why_ultra":"LHW/Virtuoso stilted luxury tents, best cone views, plunge pools","earning":"consortia rate + commission ~10%+","virtuoso_value_add":"arrival upgrade + resort/spa credit + daily breakfast (verify block)","mor":false,"tier":"ultra"},{"name":"Nayara Springs","why_ultra":"adults-only plunge-pool casitas; honeymoon apex","earning":"consortia + commission","virtuoso_value_add":"upgrade + credit (verify)","mor":false,"tier":"ultra"},{"name":"Nayara Gardens","why_ultra":"couples/families gateway into Nayara ultra cluster","earning":"consortia + commission","virtuoso_value_add":"upgrade + credit (verify)","mor":false,"tier":"luxury/ultra"},{"name":"The Springs Resort & Spa","why_ultra":"multi-level hot-spring resort, big-view suites, spa + wildlife park","earning":"consortia where eligible / DMC net","virtuoso_value_add":"where consortia-eligible","mor":true,"tier":"premier/luxury"},{"name":"Tabacon Thermal Resort & Spa","why_ultra":"benchmark natural thermal-river resort + Grand Spa","earning":"DMC net / agent","virtuoso_value_add":"suite consortia where available","mor":true,"tier":"premier/luxury"}],"source_verified":"2026-07-06","hero":{"query":"La Fortuna / Arenal, Costa Rica"},"geo":{"lat":10.4678,"lng":-84.6427}}'::jsonb, 54),
  ('la-paz-mexico', '10S', 'La Paz', 'Mexico', 'La Paz whale sharks', 'live', 'verified', 'oceanAerial', 'Baja California Sur (Los Cabos & La Paz)', '{"expedition","tropical","diveglobal"}', '{"tropical"}', '{"essential","comfort","premier"}', null, null, '{"key_facts":["Whale-shark season Oct 1-Apr 30 in bay refuge zone; juveniles 4-8m; snorkel-only, 5 pax + guide per shark, 30-min limit, licensed operators","Los Islotes: 600+ California sea lions, ~1hr by boat; snorkel-only; colony closed Jun 1-Aug 31 (pupping)","Espiritu Santo: UNESCO World Heritage (2005) + Archipielago Espiritu Santo National Park (2007); CONANP paper-bracelet permit required","La Paz is the DMC/lodging hub and launch port for Espiritu Santo and the whale-shark bay","Hyperbaric chamber present in La Paz; Salvatierra ferry wreck dive at 18-20m"],"safety":{"emergency":"911","hospital":"Hospital General Juan Maria Salvatierra (public, 2nd-level) + ISSSTE Hospital General La Paz; private clinics + air-evac for major trauma; carry medical/evac insurance","advisory_level":"L2","malaria":"effectively none in Baja California Sur","dengue":"circulates in Mexico - use repellent","water":"bottled/purified only","hurricane":"Jun-Nov - carry trip insurance for summer/fall","whale_shark":"SNORKEL ONLY, no-touch, no scuba; licensed operator, 5 pax + guide per shark, 30-min limit; Oct 1-Apr 30 only","sea_lion":"SNORKEL ONLY, no-touch; Los Islotes closed Jun 1-Aug 31; keep guide distance from territorial bulls","dive":"nearest hyperbaric chamber in La Paz (verify status/location); DAN +1-919-684-9111; no-fly 18-24h; dive-within-cert; current on open-water sites"},"timing":{"peak":"Nov-Apr (dry desert winter); whale-shark event peak Oct 1-Apr 30 (core Nov-Mar)","shoulder":"May & Sep-early Oct (sea lions open, whale sharks bookending, warm water, softer rates)","green":"Jun-Aug (summer heat, hurricane window, whale sharks gone, sea-lion colony closed Jun 1-Aug 31)","booking_window_lead_time":"3-6 months for Nov-Apr peak; small boutique inventory (Baja Club 32 rooms, Camp Cecil 8 tents Nov-Apr); book whale-shark/Espiritu Santo tours ahead in Oct-Apr","out_of_season_fill_the_beds":"Balandra/Tecolote beaches, San Rafaelito reef (sea-lion substitute during closure), Malecon dining + sunset sails, Salvatierra wreck diving, boutique summer value rates","holiday_event_peaks":"Christmas-New Year, Semana Santa (Easter), whale-shark core Nov-Mar; domestic spikes Easter + mid-summer","campaign_start_trigger":"whale-shark/Espiritu Santo campaigns May-Jul (4-6 months ahead of Oct opening); Nov-Apr honeymoon/beach campaigns late summer; summer green-window value in spring","flag":"whale shark dead May-Sep; sea lions closed Jun 1-Aug 31; summer overlaps hurricane season Jun-Nov","sources":["https://www.thoroughlytravel.com/swim-with-whale-sharks-la-paz/","https://www.goworldtravel.com/snorkeling-sea-lions-sea-of-cortez/","https://scubaboard.com/community/threads/la-paz-sea-lion-colony-closed-for-snorkel-scuba-june-1-aug-31.621077/","https://www.islands.com/story/resorts/the-glamping-experience-of-isla-espiritu-santo-camp-cecil/"]},"jewels":[{"name":"Whale-shark snorkel, Bay of La Paz","si_tag":"Global Expedition Adventures","status":"live","tier":"comfort","bookable":"licensed operator half-day snorkel (Oct 1-Apr 30)","commission_path":"local operator + Journey Mexico/Amstar DMC + Viator affiliate","source":"https://www.thoroughlytravel.com/swim-with-whale-sharks-la-paz/","hook":"eye-to-eye with juvenile whale sharks in a controlled, no-touch refuge encounter","si":"expedition","blurb":"eye-to-eye with juvenile whale sharks in a controlled, no-touch refuge encounter","commission":"local operator + Journey Mexico/Amstar DMC + Viator affiliate"},{"name":"Los Islotes sea-lion snorkel","si_tag":"Global Expedition Adventures","status":"live","tier":"comfort","bookable":"Espiritu Santo day tour (Sep-May)","commission_path":"local operator + DMC + Viator affiliate","source":"https://www.goworldtravel.com/snorkeling-sea-lions-sea-of-cortez/","hook":"play with 600+ California sea lions at one of Mexico''s healthiest colonies","si":"expedition","blurb":"play with 600+ California sea lions at one of Mexico''s healthiest colonies","commission":"local operator + DMC + Viator affiliate"},{"name":"Espiritu Santo full-day island + snorkel","si_tag":"Global Expedition Adventures","status":"live","tier":"premier","bookable":"permitted day tour incl. CONANP bracelet","commission_path":"local operator + DMC","source":"https://www.thoroughlytravel.com/isla-espiritu-santo/","hook":"uninhabited UNESCO desert island — beaches, sea lions, snorkel","si":"expedition","blurb":"uninhabited UNESCO desert island — beaches, sea lions, snorkel","commission":"local operator + DMC"},{"name":"Playa Balandra day trip (El Hongo)","si_tag":"Tropical Islands","status":"live","tier":"essential","bookable":"transfer/tour or self-drive + CONANP bracelet","commission_path":"DMC transfer + GYG affiliate","source":"https://en.wikipedia.org/wiki/Puerto_Balandra,_Baja_California_Sur","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Mexico''s most photographed beach, shallow turquoise flats, protected","si":"tropical","blurb":"Mexico''s most photographed beach, shallow turquoise flats, protected","when":"Nov-Apr","commission":"DMC transfer + GYG affiliate"},{"name":"Malecon + sunset sail","si_tag":"Tropical Islands","status":"live","tier":"premier","bookable":"catamaran/sail charter","commission_path":"charter operator + Viator affiliate","source":"https://www.thoroughlytravel.com/swim-with-whale-sharks-la-paz/","hook":"La Paz''s waterfront promenade and calm-bay sunset cruises","si":"tropical","blurb":"La Paz''s waterfront promenade and calm-bay sunset cruises","commission":"charter operator + Viator affiliate"},{"name":"Salvatierra wreck dive","si_tag":"Dive Globally / Ocean Adventures","status":"future","tier":"comfort","bookable":"dive-within-cert charter","commission_path":"dive operator + affiliate","source":"https://lapazdivers.com/la-paz-dive-sites/","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"1976 ferry wreck at 18–20 m, thriving artificial reef, diveable near year-round","si":"Dive Globally / Ocean Adventures","blurb":"1976 ferry wreck at 18–20 m, thriving artificial reef, diveable near year-round","when":"Nov-Apr","commission":"dive operator + affiliate"}],"faq":[{"q":"When and how can I swim with whale sharks in La Paz?","a":"October 1 to April 30, on a licensed half-day snorkel in the bay''s protected refuge zone — never scuba. Encounters are capped at 5 swimmers plus a certified guide per shark for 30 minutes, with no touching, to protect the juveniles that feed there.","source":"thoroughlytravel.com / bucketlistbri.com, 2026-07-04","si_tag":"expedition"},{"q":"Is La Paz a good island and beach base?","a":"Yes — it is the launch port for the whole Sea-of-Cortez set: protected Balandra, Tecolote, the Malecón waterfront and boat trips to UNESCO-listed Espíritu Santo. It''s the quiet, low-key alternative to the Los Cabos corridor two hours south.","source":"en.wikipedia.org, 2026-07-04","si_tag":"tropical"},{"q":"What is there to dive around La Paz?","a":"The signature dive is the Salvatierra, a 1976 ferry wreck at 18–20 m that''s now a thriving artificial reef, diveable near year-round, plus the El Bajo seamount. La Paz has its own recompression chamber (confirm status at booking) and DAN emergency is +1-919-684-9111.","source":"lapazdivers.com, 2026-07-04","si_tag":"diveglobal"},{"q":"Is La Paz safe right now?","a":"Yes — freely bookable. Baja California Sur is US State Dept Level 2 \"Exercise Increased Caution\" (May 29, 2026), and La Paz is a low-key capital far calmer than the mainland cartel-flagged states.","source":"travel.state.gov, 2026-05-29","si_tag":"safety"},{"q":"What''s the real risk to plan for?","a":"Missing the season, not crime. Whale sharks are gone May–Sep, sea lions close Jun 1–Aug 31, both are snorkel-only (no touch, no scuba), and hurricane season runs Jun–Nov. Book the Oct–Apr window ahead and carry trip insurance for summer/fall.","source":"scubaboard.com / dossier Safety Card, 2026-07-04","si_tag":"safety"}],"seo":{"meta_title":"La Paz Whale Sharks & Sea Lions: Sea of Cortez Guide","meta_description":"Snorkel with whale sharks (Oct–Apr) and sea lions at Los Islotes, then sail to UNESCO-listed Espíritu Santo — the quiet Baja capital on the Sea of Cortez. When and how to book.","slug":"la-paz-mexico","primary_keyword":"La Paz whale sharks","long_tail":["La Paz whale shark season 2026","swim with sea lions Los Islotes","Espiritu Santo tour from La Paz","Balandra beach La Paz guide","La Paz Sea of Cortez snorkel"],"search_language":["en","es-MX"],"local_keywords":["tiburón ballena La Paz temporada","nadar con lobos marinos Los Islotes","tour Isla Espíritu Santo desde La Paz","Playa Balandra La Paz","snorkel Mar de Cortés La Paz","hoteles boutique La Paz Baja","buceo naufragio Salvatierra"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-04"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"live"},{"si":"tropical","status":"live"},{"si":"Dive Globally / Ocean Adventures","status":"future"}],"ultra":[{"name":"Baja Club","posture":"boutique-luxe, Design Hotels/Marriott (not full branded ultra)","price_tier":"luxury","earning":"on application / host-Virtuoso or Marriott STARS/Design Hotels program","virtuoso_value_add":"amenity block (breakfast/credit/upgrade) where rate qualifies","mor":"commissionable only where offered; no net-rate resale","source":"https://www.designhotels.com/hotels/mexico/baja-california-sur/la-paz/baja-club/"},{"name":"CostaBaja Resort & Spa (Puerta Cortes)","posture":"five-star resort (La Paz first five-star)","price_tier":"luxury","earning":"on application / host bedbank or preferred program","virtuoso_value_add":"amenity block where rate qualifies","mor":"no net-rate resale","source":"https://www.costabajaresortspa.com/"},{"name":"Camp Cecil de la Isla (Espiritu Santo)","posture":"eco-luxe private-island glamping (8 tents, TOSEA)","price_tier":"ultra","earning":"on application / host-Virtuoso or TOSEA operator terms","virtuoso_value_add":"private buy-out / naturalist upgrade on application","mor":"no net-rate resale","source":"https://www.islands.com/story/resorts/the-glamping-experience-of-isla-espiritu-santo-camp-cecil/"},{"name":"Puerta Cortes private beachfront villa (private pool/jacuzzi)","posture":"top private villa in gated marina-golf community","price_tier":"luxury","earning":"on application / villa-manager commission where offered; often OTA/Airbnb (affiliate)","virtuoso_value_add":"concierge + beach-club access","mor":"no net-rate resale","source":"https://www.booking.com/hotel/mx/beachfront-villa-private-pool-at-puerta-cortes.html"}],"source_verified":"2026-07-04","hero":{"query":"La Paz, Mexico"},"geo":{"lat":24.1425,"lng":-110.3108}}'::jsonb, 55),
  ('lake-atitlan-guatemala', '10S', 'Lake Atitlán', 'Guatemala', '*If it''s the first pale light on three volcanoes', 'live', 'verified', 'desertDunes', 'Guatemala', '{"adventure","romance","culture","wellness"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, null, '{"key_facts":["Volcanic caldera lake at 1,562 m (5,125 ft), up to 340 m deep, ~130 km², ringed by three volcanoes — San Pedro, Tolimán, Atitlán (Source: en.wikipedia.org/wiki/Lake_Atitlán, Accessed 2026-07-06)","Villages divide by role: Panajachel gateway hub, San Pedro backpacker/Spanish-school, San Marcos yoga/wellness, Santiago Atitlán largest/traditional, San Juan weaving + coffee (Source: adventurouskate.com, Accessed 2026-07-06)","Indian Nose sunrise hike (~30 min pre-dawn) is the signature caldera overlook; San Marcos offers yoga retreats + Cerro Tzankujil cliff-jump (Source: adventurouskate.com, Accessed 2026-07-06)","Dry season Nov–Apr is most photogenic; Christmas + Semana Santa fill weeks ahead; Sept–Oct rates 40–50% below peak (Source: atitlan.com, Accessed 2026-07-06)","Air access via GUA (La Aurora Intl) + shuttle/private transfer ~3 hr to Panajachel; boat (lancha) is the only road between villages (Source: theabroadblog.com / adventurouskate.com, Accessed 2026-07-06)"],"safety":{"emergency":"110 police · 122/123 ambulance · 1500 ASISTUR/PROATUR (or +502-2290-2810) — verify locally","hospital":"Panajachel/Sololá clinics + regional hospital for stabilization; serious trauma/cardiac evac to Guatemala City (~3 hr road); highlands lack tertiary trauma capability","book_enabled":true,"state_dept_carveout":"US State Dept (reissued Jun 11 2026, codes C+T) explicitly names Lake Atitlán among destinations US-gov employees can visit; L4 zones = San Marcos Dept, Huehuetenango Dept, Zone 18 GC, Villa Nueva — none is Atitlán/Sololá","san_marcos_clarification":"L4 ''San Marcos Department'' (highland border dept) is a DIFFERENT place from ''San Marcos La Laguna,'' the safe yoga village on Lake Atitlán (Sololá)","l3_disclosure":true,"stay_in_zone":true,"founder_policy_note":"book_enabled rides on TWW''s BOOK WITH WARNING (Four-Bin v3) framing (same founder/attorney axis as the held Central-Mexico SR6)","consent_flow":{"bin":"BOOK WITH WARNING","disclosure_required":true,"renders":"full verbatim live US State Dept advisory for the country (level + reason + named-danger areas + complete ''If you decide to travel'' guidance), pulled live, plus traveler acknowledgment","wording_status":"hook set only — final consent language PENDING compliance-attorney sign-off"},"air_access_verified":"GUA (La Aurora Intl) + shuttle/private transfer ~3 hr to Panajachel","altitude":"~1,562 m (5,125 ft) lakeside — mild; volcano summits San Pedro ~3,020 m / Atitlán ~3,535 m reach real altitude","malaria":"none — CDC reports no malaria transmission at Lake Atitlán (highland); insect-bite precautions only; dengue/Zika possible in Guatemala generally","water":"bottled/purified only","lake_boat_safety":"Xocomil wind kicks up late morning/afternoon and can capsize boats — cross early, licensed lanchas with life vests","swim_advisory":"verify current cyanobacteria (Microcystis) advisory before selling lake-swim (blooms 2009, 2015)"},"timing":{"inflection_curve_start":"Dry-season demand builds from late Sept / early Oct for the Nov–Apr window; retreat + honeymoon bookings run longer lead","peak":"Dry season Nov–Apr; sharpest spikes Christmas–New Year and Semana Santa; weekly Chichi-market micro-peak Thu/Sun","fire_date":"Mid-September for the Christmas/New-Year + Jan–Mar dry-season peak; early-to-mid January for the Semana Santa spike — curve-start minus 1–2 weeks (directional, sharpen on live tracking)","shoulder":"May–June and September–October","green":"May–October wet season — afternoon storms, greenest landscape, Sept–Oct rates 40–50% below peak","booking_lead":"Peak boutiques/villas 2–4 mo (longer for Christmas + Semana Santa); yoga retreats 2–6 mo; day tours day-of to 1 wk","off_season_specials":"Rainy-season wellness-retreat + language-immersion + villa packages; midweek boutique value; Chichi day-trip add-ons year-round","event_peaks":"Semana Santa (Mar/Apr), Christmas–New Year, Santiago Atitlán Maximón/Holy-Week processions"},"jewels":[{"name":"Indian Nose (Nariz del Indio) sunrise hike","si_tag":"Global / Epic Adventures","status":"live","hook":"~30-min pre-dawn ridge trek to a panoramic caldera + three-volcano overlook ''in perfect silence''","bookable_category":"guided sunrise hike + transfer","tier":"comfort","commission_path":"activity affiliate / DMC","source":"https://www.adventurouskate.com/the-towns-of-lake-atitlan-guatemala/ (Accessed 2026-07-06)","si":"Global / Epic Adventures","blurb":"~30-min pre-dawn ridge trek to a panoramic caldera + three-volcano overlook ''in perfect silence''","commission":"activity affiliate / DMC","accessed":"2026-07-06"},{"name":"San Pedro / Atitlán volcano summit","si_tag":"Global / Epic Adventures","status":"live","hook":"Guided ascent of San Pedro (~3,020 m) or the harder Atitlán/Tolimán cones","bookable_category":"guided volcano trek","tier":"premier","commission_path":"DMC / activity affiliate","source":"https://en.wikipedia.org/wiki/Lake_Atitl%C3%A1n (Accessed 2026-07-06)","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Global / Epic Adventures","blurb":"Guided ascent of San Pedro (~3,020 m) or the harder Atitlán/Tolimán cones","when":"Dry season Nov–Apr","commission":"DMC / activity affiliate","accessed":"2026-07-06"},{"name":"Kayak / SUP the caldera","si_tag":"Global / Epic Adventures","status":"live","hook":"Morning paddle across glass-calm water beneath the volcanoes; cleanest near San Marcos","bookable_category":"rental + guided paddle","tier":"comfort","commission_path":"activity affiliate","source":"https://www.adventurouskate.com/the-towns-of-lake-atitlan-guatemala/ (Accessed 2026-07-06)","si":"Global / Epic Adventures","blurb":"Morning paddle across glass-calm water beneath the volcanoes; cleanest near San Marcos","commission":"activity affiliate","accessed":"2026-07-06"},{"name":"Village-hop by lancha","si_tag":"Global / Epic Adventures","status":"live","hook":"Full-day boat circuit of the lakeside villages — each a distinct world","bookable_category":"private/shared lancha day","tier":"comfort","commission_path":"DMC / boat operator","source":"https://www.adventurouskate.com/the-towns-of-lake-atitlan-guatemala/ (Accessed 2026-07-06)","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Global / Epic Adventures","blurb":"Full-day boat circuit of the lakeside villages — each a distinct world","when":"Dry season Nov–Apr","commission":"DMC / boat operator","accessed":"2026-07-06"},{"name":"Chichicastenango market (Thu & Sun)","si_tag":"Culture & Heritage","status":"future","hook":"Guatemala''s most famous Maya market — textiles, masks, Santo Tomás church, Pascual Abaj shrine","bookable_category":"guided day trip from Atitlán","tier":"comfort","commission_path":"DMC (Clark/Martsam) / activity affiliate (browsing = non-commissionable)","source":"https://dmcfinder.com/listing/clark-tours/ (Accessed 2026-07-06)","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Guatemala''s most famous Maya market — textiles, masks, Santo Tomás church, Pascual Abaj shrine","when":"Dry season Nov–Apr","commission":"DMC (Clark/Martsam) / activity affiliate (browsing = non-commissionable)","accessed":"2026-07-06"},{"name":"San Juan La Laguna textile + natural-dye co-ops","si_tag":"Culture & Heritage","status":"future","hook":"Women''s weaving cooperatives (e.g. Lema'') — backstrap looms + indigo/cochineal natural dyes","bookable_category":"co-op weaving demo + shop","tier":"comfort","commission_path":"activity affiliate / DMC","source":"https://www.adventurouskate.com/the-towns-of-lake-atitlan-guatemala/ (Accessed 2026-07-06)","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Women''s weaving cooperatives (e.g. Lema'') — backstrap looms + indigo/cochineal natural dyes","when":"Dry season Nov–Apr","commission":"activity affiliate / DMC","accessed":"2026-07-06"},{"name":"Santiago Atitlán + Maximón","si_tag":"Culture & Heritage","status":"future","hook":"The lake''s largest, most traditional Tz''utujil town + the Maximón folk-saint shrine (moved yearly among cofradías)","bookable_category":"guided cultural visit","tier":"comfort","commission_path":"DMC / guide (shrine tip = non-commissionable)","source":"https://www.adventurouskate.com/the-towns-of-lake-atitlan-guatemala/ (Accessed 2026-07-06)","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"The lake''s largest, most traditional Tz''utujil town + the Maximón folk-saint shrine (moved yearly among cofradías)","when":"Dry season Nov–Apr","commission":"DMC / guide (shrine tip = non-commissionable)","accessed":"2026-07-06"},{"name":"San Juan coffee cooperatives","si_tag":"Culture & Heritage","status":"future","hook":"Farm-to-cup tours at highland coffee co-ops; small-lot Guatemalan coffee story","bookable_category":"coffee-farm tour + tasting","tier":"comfort","commission_path":"activity affiliate / DMC","source":"https://www.adventurouskate.com/the-towns-of-lake-atitlan-guatemala/ (Accessed 2026-07-06)","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"Farm-to-cup tours at highland coffee co-ops; small-lot Guatemalan coffee story","when":"Dry season Nov–Apr","commission":"activity affiliate / DMC","accessed":"2026-07-06"},{"name":"San Marcos La Laguna yoga + retreats","si_tag":"Wellness","status":"future","hook":"Central America''s yoga village — Las Pirámides del Ká, Eagle''s Nest, retreat centers + vegetarian cafés","bookable_category":"retreat program + wellness stay","tier":"premier","commission_path":"retreat referral / hotel","source":"https://www.adventurouskate.com/the-towns-of-lake-atitlan-guatemala/ (Accessed 2026-07-06)","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"wellness","blurb":"Central America''s yoga village — Las Pirámides del Ká, Eagle''s Nest, retreat centers + vegetarian cafés","when":"Dry season Nov–Apr","commission":"retreat referral / hotel","accessed":"2026-07-06"},{"name":"Cerro Tzankujil cliff-jump reserve (San Marcos)","si_tag":"Wellness","status":"future","hook":"Natural reserve with trails + lakeside cliff-jump platform — the lake''s famous swim spot","bookable_category":"reserve entry + guided add-on","tier":"essential","commission_path":"activity add-on (entry = non-commissionable)","source":"https://www.adventurouskate.com/the-towns-of-lake-atitlan-guatemala/ (Accessed 2026-07-06)","timing":"Dry season Nov–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"wellness","blurb":"Natural reserve with trails + lakeside cliff-jump platform — the lake''s famous swim spot","when":"Dry season Nov–Apr","commission":"activity add-on (entry = non-commissionable)","accessed":"2026-07-06"},{"name":"Private-boat sunset + volcano golden hour","si_tag":"Romance & Honeymoons","status":"live","hook":"Chartered lancha sunset cruise or private-dock dinner beneath the three volcanoes","bookable_category":"private-boat charter + dining","tier":"luxury","commission_path":"DMC / hotel F&B + villa","source":"https://www.jacadatravel.com/latin-america/guatemala/lake-atitlan/ (Accessed 2026-07-06)","si":"romance","blurb":"Chartered lancha sunset cruise or private-dock dinner beneath the three volcanoes","commission":"DMC / hotel F&B + villa","accessed":"2026-07-06"}],"faq":[{"q":"What''s the Indian Nose sunrise hike, and can you climb the volcanoes?","a":"The Indian Nose (Nariz del Indio) is a ~30-minute pre-dawn ridge trek to a panoramic caldera-and-three-volcano overlook \"in perfect silence\" — Atitlán''s signature dawn. You can also summit the harder volcanoes (San Pedro ~3,020 m, Atitlán ~3,535 m), which reach real altitude, so go guided-only.","source":"adventurouskate.com, Accessed 2026-07-06","si_tag":"global"},{"q":"Where do you stay for a honeymoon at Lake Atitlán?","a":"At the lake''s one true-luxury anchor: Casa Palopó, Guatemala''s only Relais & Châteaux hotel — a ~15-room boutique above Santa Catarina Palopó with three-volcano views. Beneath it sit eco-luxury Laguna Lodge and full-staff cliffside private villas with private docks, ideal for honeymoons and small buyouts.","source":"jacadatravel.com, Accessed 2026-07-06","si_tag":"romance"},{"q":"When is the Chichicastenango market?","a":"Thursdays and Sundays only. It''s Guatemala''s most famous Maya market — textiles, masks, produce, the Santo Tomás church and the hillside Pascual Abaj shrine — booked as a guided day-trip from Atitlán, because those are the two K''iche'' Maya trading days that drive the weekly highland micro-peak.","source":"dmcfinder.com, Accessed 2026-07-06","si_tag":"culture"},{"q":"Is Lake Atitlán good for a yoga retreat?","a":"Yes — San Marcos La Laguna is Central America''s best-known yoga village, with retreat centers like Las Pirámides del Ká and Eagle''s Nest plus a cluster of vegetarian cafés and a genuine decades-old community. Retreats run set calendars, so wellness bookings often carry a 2–6-month lead.","source":"adventurouskate.com, Accessed 2026-07-06","si_tag":"wellness"},{"q":"Is Lake Atitlán safe right now?","a":"Yes, with disclosure. Guatemala is US Level 3, but the advisory explicitly names Lake Atitlán among destinations US-government employees can visit; the four Level 4 zones don''t include Atitlán/Sololá. Don''t confuse the L4 \"San Marcos Department\" (Mexican-border highland) with safe \"San Marcos La Laguna\" on the lake.","source":"travel.state.gov, Accessed 2026-07-06","si_tag":"safety"},{"q":"What''s the real risk to plan for on the lake?","a":"The wind, not the water quality. The Xocomil — a Pacific-vs-northern wind collision — kicks up late morning and afternoon and is \"capable of capsizing boats,\" so cross early on licensed lanchas with life vests. Separately, verify the current cyanobacteria (Microcystis) swim advisory before booking lake-swim.","source":"en.wikipedia.org, Accessed 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Lake Atitlán Travel Guide — Volcanoes, Maya Villages & Chichi Market | TravelWell.World","meta_description":"The most beautiful lake in the world: three volcanoes, a dozen Maya villages, San Marcos yoga, San Juan weavers, Santiago''s Maximón, the Chichicastenango market, and Casa Palopó (Relais & Châteaux). Bookable with mandatory L3 disclosure.","slug":"lake-atitlan-guatemala","primary_keyword":"Lake Atitlán travel guide","long_tail":["best time to visit Lake Atitlán 2026","is Lake Atitlán safe 2026","Lake Atitlán villages guide","San Marcos La Laguna yoga retreat","Indian Nose sunrise hike","Chichicastenango market days","Casa Palopó Relais & Châteaux","San Juan La Laguna weaving cooperative","how to get to Lake Atitlán from Guatemala City"],"search_language":"es-GT","local_keywords":["Lago de Atitlán qué hacer","¿es seguro viajar al Lago de Atitlán?","mejores hoteles Lago de Atitlán","Chichicastenango mercado","nariz del indio caminata amanecer","San Marcos La Laguna yoga","San Juan La Laguna tejidos","cómo llegar al Lago de Atitlán desde Guatemala"],"hreflang":["en","es-GT"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-06"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"adventure","status":"live"},{"si":"romance","status":"live"},{"si":"culture","status":"future"},{"si":"wellness","status":"future"}],"ultra":[{"name":"Casa Palopó (Relais & Châteaux)","why_ultra":"Guatemala''s only Relais & Châteaux hotel — ~15 individually designed suites above Santa Catarina Palopó with three-volcano views; the lake''s benchmark true-luxury property","earning":"on application / Relais & Châteaux via Virtuoso/Fora","mor":true,"tier":"ultra"},{"name":"Laguna Lodge Eco-Resort","why_ultra":"Premier eco-luxury boat-access boutique on a private lakeside reserve; sustainability-forward design + spa; the lake''s top eco-luxury play","earning":"on application / host program","mor":true,"tier":"luxury"},{"name":"Cliffside private villas (Santa Cruz / Tzununá / San Marcos)","why_ultra":"Full-staff private lake houses with private docks + caldera terraces — the ultra-villa alternative for honeymoons + small buyouts","earning":"via specialist villa desk + MoR","mor":true,"tier":"luxury-ultra"}],"source_verified":"2026-07-06","hero":{"query":"Lake Atitlán, Guatemala"},"geo":{"lat":14.6907,"lng":-91.2025}}'::jsonb, 56),
  ('lake-titicaca-puno-peru', '10S', 'Lake Titicaca (Puno), Peru', 'Peru', 'Lake Titicaca (Puno)', 'live', 'verified', 'mountainValley', 'Lima, South Coast & Amazon', '{"culture"}', '{}', '{"essential","comfort"}', null, null, '{"key_facts":null,"safety":{"emergency":"105","tourist_help":"iPerú (national tourist assistance line)","advisory_level":"L2","book_enabled":true,"bin":"freely bookable (L2)","consent_flow":false,"air_access_verified":true,"air_access":"Juliaca (JUL) via Lima (LIM); or rail/road from Cusco & Arequipa","altitude_m":{"lake_titicaca_puno":3810,"taquile":3800,"amantani_temple_hills":4100},"altitude_rule":"Highest stop on most Peru circuits (higher than Cusco); arrive already acclimatized (ideally Arequipa→Colca→Puno→Cusco); gradual island climbs; coca/soroche management; consider Diamox","cold_nights":"Bitterly cold altiplano nights; island homestays unheated — pack layers","water":"bottled/purified only","remoteness_note":"Islands have basic facilities only; serious emergencies require boat to Puno then evac to Arequipa/Lima"},"timing":{"peak":"May–September (dry-season altiplano)","event_peak":"Virgen de la Candelaria — ~Jan 16 – Feb 10 (main day Feb 2, dance apex Feb 8–10); secondary Inti Raymi-season (late June) overflow","inflection_curve_start":"early December (Candelaria) / early April (dry-season core)","fire_date":"mid–late November (Candelaria/Feb) & mid–late March (May–Sep core)","green_offseason":"November–March (minus the February Candelaria spike)","binding_constraint":"Candelaria lodging sellout + acclimatization sequencing; often booked as the Cusco↔Arequipa overland link"},"jewels":[{"name":"Uros floating reed islands","si_tag":"culture","tier":"essential","commission_path":"DMC/operator day tour + Uros community landing fee (non-comm) + reed-craft retail","source":"https://www.theonlyperuguide.com/peru-guide/puno/uros-floating-islands/","timing":"May–September","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"hand-built totora-reed islands ~30 min by boat from Puno, springy underfoot, where the Uros people still live and build. Real communities","si":"culture","blurb":"hand-built totora-reed islands ~30 min by boat from Puno, springy underfoot, where the Uros people still live and build. Real communities","when":"May–September","commission":"DMC/operator day tour + Uros community landing fee (non-comm) + reed-craft retail"},{"name":"Taquile Island (UNESCO textile island)","si_tag":"culture","tier":"comfort","commission_path":"DMC/operator day or 2-day tour + community entry (non-comm) + textile-cooperative retail","source":"https://ich.unesco.org/en/RL/taquile-and-its-textile-art-00166","timing":"May–September","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"terraced island where knitting is done by men and weaving by women; the textile art is on UNESCO''s Intangible Cultural Heritage list","si":"culture","blurb":"terraced island where knitting is done by men and weaving by women; the textile art is on UNESCO''s Intangible Cultural Heritage list","when":"May–September","commission":"DMC/operator day or 2-day tour + community entry (non-comm) + textile-cooperative retail"},{"name":"Amantaní homestay + starry night","si_tag":"culture","tier":"essential","commission_path":"direct-to-community co-op (thin margin) + homestay/community fee (non-comm)","source":"https://www.peroudecouverte.com/peru-puno-amantani-island-homestay-pachamama-en.html","hook":"the deepest cultural time on the lake: overnight with a Quechua family, shared meals, dance in borrowed dress","si":"culture","blurb":"the deepest cultural time on the lake: overnight with a Quechua family, shared meals, dance in borrowed dress","commission":"direct-to-community co-op (thin margin) + homestay/community fee (non-comm)"},{"name":"Sillustani chullpa towers (sunset)","si_tag":"culture","tier":"comfort","commission_path":"DMC/operator afternoon excursion + site entry (non-comm)","source":"https://www.machutravelperu.com/blog/puno-sillustani","timing":"year-round","timing_type":"ALWAYS-ON","hook":"pre-Inca Colla funerary towers up to 12 m tall on a peninsula over Lake Umayo, ~35 km from Puno","si":"culture","blurb":"pre-Inca Colla funerary towers up to 12 m tall on a peninsula over Lake Umayo, ~35 km from Puno","when":"year-round","commission":"DMC/operator afternoon excursion + site entry (non-comm)"},{"name":"Virgen de la Candelaria festival (February)","si_tag":"culture","tier":"comfort","commission_path":"DMC festival package (hotel + guiding + stadium seating); book by mid–late Nov","source":"https://www.urosexpeditions.com/travel-news/candelaria-festival-2026-official-schedule-dance-order","timing":"May–September","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"one of the largest folk-festival gatherings in the Americas: thousands of dancers, \"traje de luces\" sequined costumes, brass bands","si":"culture","blurb":"one of the largest folk-festival gatherings in the Americas: thousands of dancers, \"traje de luces\" sequined costumes, brass bands","when":"May–September","commission":"DMC festival package (hotel + guiding + stadium seating); book by mid–late Nov"},{"name":"Llachón peninsula community tourism (Capachica)","si_tag":"culture","tier":"essential","commission_path":"direct-to-community co-op + DMC add-on","source":"https://titicacatravel-ip.com/en/tour/lake-titicaca/homestay-tour-llachon-amantani-taquile-islands","timing":"May–September","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the mainland community-tourism heartland on the Capachica peninsula: experiential homestays, weaving, cooking and sailing with families, quieter than the islands","si":"culture","blurb":"the mainland community-tourism heartland on the Capachica peninsula: experiential homestays, weaving, cooking and sailing with families, quieter than the islands","when":"May–September","commission":"direct-to-community co-op + DMC add-on"},{"name":"Aymara / Quechua living culture","si_tag":"culture","tier":"essential","commission_path":"DMC cultural interpretation woven through every tour","source":"https://en.wikipedia.org/wiki/Sillustani","timing":"May–September","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the altiplano is a living Aymara–Quechua cultural landscape; language, dress, agriculture and belief are the deep story that ties every island and shore together","si":"culture","blurb":"the altiplano is a living Aymara–Quechua cultural landscape; language, dress, agriculture and belief are the deep story that ties every island and shore together","when":"May–September","commission":"DMC cultural interpretation woven through every tour"},{"name":"Luxury catamaran day-sail (Peru-side)","si_tag":"GEA / RHN","tier":"comfort","commission_path":"lake-operator net/commissionable tour (Peru-side only); private charter highest margin","source":"https://titicaca.cruises/en/home/","timing":"May–September","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"a private or shared catamaran across the open lake. Outdoor decks, Cordillera views, and — on some operators","si":"GEA / RHN","blurb":"a private or shared catamaran across the open lake. Outdoor decks, Cordillera views, and — on some operators","when":"May–September","commission":"lake-operator net/commissionable tour (Peru-side only); private charter highest margin"}],"faq":[{"q":"Are the Uros, Taquile and Amantaní islands worth it — and does my money reach the families?","a":"Yes, and this is the reason to come. Booked through the community co-op, an Amantaní overnight homestay costs roughly $10–15 per person including meals and rotates through ten host communities, so the income reaches families directly rather than mainland middlemen — the deepest cultural experience on the lake.","source":"peroudecouverte.com, 2026-07-07","si_tag":"culture"},{"q":"How hard is the island walking, and what should I plan for?","a":"Plan for altitude, not difficulty. Island hikes run ~3,800–4,100 m — Taquile is a steady 30–60 minute uphill from the dock, and Amantaní''s twin temple hills top near 4,100 m — so the real risk is AMS. Arrive already acclimatized, pace the climb, and carry water.","source":"bushop.com, 2026-07-07","si_tag":"expedition"},{"q":"Is Lake Titicaca good for a honeymoon?","a":"Yes, as a quiet luxe add-on to a Cusco/Machu Picchu core. The standout is Titilaka, an 18-suite all-inclusive Relais & Châteaux lodge on a private peninsula with lake-view suites, a private jetty and oxygen-quiet calm — sunrise over the water and private catamaran sailing.","source":"relaischateaux.com, 2026-07-07","si_tag":"romance"},{"q":"Is Lake Titicaca safe right now?","a":"Yes — it is freely bookable. Peru sits at U.S. State Department Level 2 (Exercise Increased Caution), and State carries no Puno-specific carve-out; Puno sits inside the government-prioritized Southern Tourist Corridor. `book_enabled = true`, no consent flow required.","source":"travel.state.gov, 2026-07-07","si_tag":"safety"},{"q":"What''s the real risk to plan for?","a":"Altitude — full stop. At ~3,810 m the lake is the highest stop on most Peru circuits, higher than Cusco, so AMS (soroche) is the dominant safety fact and outranks crime by a wide margin. Best practice: reach the lake already acclimatized (Arequipa→Colca→Puno→Cusco).","source":"turismoliberty.pe, 2026-07-07","si_tag":"safety"},{"q":"Is the boat trip across the lake dangerous?","a":"Only if you cut corners on the operator. Titicaca is a huge, cold, high-altitude open lake where afternoon wind picks up fast; insist on a licensed lancha with life vests and prefer guided/operator boats over informal transport. Weather can turn quickly on the altiplano.","source":"titicaca.cruises, 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Lake Titicaca & Puno, Peru — Uros, Taquile & Amantaní Guide, Altitude Tips & Luxury Lodges | TravelWell.World","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","freshness":"2026-07-07","search_language":"es-PE","local_keywords":["Lago Titicaca Uros","islas flotantes Puno","Taquile Amantaní tour","homestay isla Amantaní","chullpas de Sillustani","Virgen de la Candelaria Puno 2026","mal de altura Puno soroche","cómo llegar a Puno desde Cusco","catamarán Lago Titicaca"],"hreflang":["en","es-PE"],"primary_keyword":"Lake Titicaca (Puno)"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"culture","status":"live"}],"ultra":[{"name":"Titilaka (Relais & Châteaux)","location":"Private peninsula near Puno","earning":"Relais & Châteaux / Virtuoso preferred; agency AoR + VIP amenities (upgrade, breakfast, early/late, 50-min massage for two)","mor":"agency/hotel","tier":"$$$$"},{"name":"GHL Hotel Lago Titicaca","location":"Esteves Island","earning":"agency + affiliate; agency AoR","mor":"agency/hotel","tier":"$$$"},{"name":"Casa Andina Premium Puno","location":"Puno lakeshore","earning":"agency + affiliate; agency AoR","mor":"agency/hotel","tier":"$$$"},{"name":"Private catamaran (Peru-side day charter)","location":"Open lake ex-Puno","earning":"lake-operator charter; agency-coordinated","mor":"operator","tier":"$$$"}],"source_verified":null,"hero":{"query":"Lake Titicaca (Puno), Peru, Peru"},"geo":{"lat":-15.8402,"lng":-70.0219}}'::jsonb, 57),
  ('lima-peru', '10S', 'Lima', 'Peru', 'The world''s table, on the Pacific', 'live', 'verified', 'kyoto', 'Lima, South Coast & Amazon', '{"romance","expedition","culinary","culture"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, null, '{"key_facts":["Home to the World''s #1 restaurant 2025 (Maido, Nikkei) plus Central (former #1, Best of the Best), Kjolle #9, Merito #26, Mayta #39 - a global top-tier food capital.","Pre-Inca adobe pyramids inside the modern city (Huaca Pucllana, ~200-700 AD, in Miraflores) alongside the UNESCO colonial Centro Historico and the Convento de San Francisco catacombs.","Jorge Chavez (LIM) is South America''s newest mega-hub: new $2.4B Fraport/LAP terminal opened June 1, 2025 (3x size, up to 40M pax/yr, 46 gates, 2nd runway); the gateway to Cusco/MP, the Amazon, Titicaca and the south coast.","Cool Pacific-desert climate: warm sunny summer Dec-Apr; grey misty ''garua'' winter May-Nov (dry but overcast) - the driest window for Machu Picchu, which drives Lima''s derivative winter spike.","Bohemian Barranco (Puente de los Suspiros) and clifftop Miraflores (Malecon, Costa Verde paragliding) anchor the boutique-romance line; genuine global-flag ultra (Belmond, Relais & Chateaux, LHW, JW Marriott)."],"safety":{"emergency":"105 National Police (PNP) / 106 SAMU medical-ambulance / 116 Bomberos (fire); iPeru tourist assistance (01-574-8000, desks at LIM/Miraflores/Larcomar)","hospital":"Lima has Peru''s best private hospitals/clinics (Clinica Anglo Americana, Ricardo Palma, Clinica Internacional) for stabilization; serious trauma routes to US medical evacuation - carry evac-capable insurance","advisory_level":"L2","bin":"freely bookable (L2)","book_enabled":true,"consent_flow":"none (L2 is standard-caution, below disclosure threshold)","l3_disclosure":false,"air_access_verified":true,"air_access_note":"Jorge Chavez Intl (LIM), Callao - new Fraport/LAP terminal opened 2025-06-01; SA hub; LIM->Miraflores ~45-60 min via hotel/DMC transfer (not street taxi)","urban_crime_discipline":"stay in Miraflores/Barranco/San Isidro; registered radio-taxi or ride-hail app or hotel transfer only (never unmarked street taxi - express-kidnapping setup); beware distraction theft; in-bank ATMs only; don''t display valuables","state_of_emergency_note":"Lima/Callao late-2025 state of emergency raised police/military presence amid rising urban crime - does not change L2 bin; verify current status live","altitude":"Lima at sea level (no altitude issue; useful soft-landing before Cusco 3,400 m / Titicaca 3,800 m)","dengue":"low on cool Lima coast; higher on Amazon/northern extensions","malaria":"no malaria risk in Lima (highland/coastal capital); Amazon extensions do carry risk - CDC consult for those legs","water":"bottled/purified only (also underpins reputable-cebicheria raw-fish hygiene rule)"},"timing":{"peak_coastal_summer":"Dec-Apr - Lima''s own warm/sunny curve (beaches, nightlife, paragliding, surfing); highest crowds/prices","inflection_gateway_winter":"Jun-Aug - derivative spike as travelers bookend the driest Machu Picchu window through Lima","garua":"May-Nov grey misty sea-fog winter (dry but overcast); sell as culinary/culture bookend, not beach","fire_date":"coastal-summer curve: fire ~mid-November (curve-start -1-2 wks); MP-derivative winter curve: fire ~mid-May; practically, attach Lima nights to whenever the parent Cusco/MP campaign fires","booking_lead":"top tasting menus (Central/Maido/Kjolle) weeks ahead - reservation-first; city hotels 2-3 months for summer; Cusco/Amazon-attached bookends 3-6 months","shoulder":"Apr-May & Sep-Nov (better deals, workable weather)","off_season_specials":"grey-winter ''gastronomy bookend'': tasting-menu circuit, cebicheria lunches, Larco/Pachacamac/San Francisco heritage, cooking classes, pisco-sour masterclasses","event_peaks":["Fiestas Patrias late July (Independence, domestic peak)","Mistura-successor gastronomy festival (name/dates UNVERIFIED - confirm live)","Christmas/New Year (summer)"]},"jewels":[{"name":"Central / Maido / Kjolle tasting menus","si_tag":"Culinary","status":"future","hook":"The world-ranked Lima fine-dining trinity - Maido (World''s #1 2025), Central (Best of the Best), Kjolle (#9); book weeks ahead, reservation-first.","bookable_category":"direct reservation or DMC culinary program","tier":"ultra","commission_path":"DMC culinary-program AOR 10-15%; raw restaurant deposit pass-through","source":"https://www.theworlds50best.com/stories/News/maido-lima-the-worlds-best-restaurant-2025.html","si":"culinary","blurb":"The world-ranked Lima fine-dining trinity - Maido (World''s #1 2025), Central (Best of the Best), Kjolle (#9); book weeks ahead, reservation-first.","commission":"DMC culinary-program AOR 10-15%; raw restaurant deposit pass-through"},{"name":"La Mar cebicheria (Gaston Acurio)","si_tag":"Culinary","status":"future","hook":"Acurio''s flagship Miraflores cebicheria (est. 2005), Latin America''s 50 Best - the definitive lunch-only ceviche experience.","bookable_category":"direct / DMC food tour (lunch only)","tier":"premier","commission_path":"DMC food-program AOR / Viator affiliate 4-8%; walk-in pass-through","source":"http://limacitykings.com/la-mar-cebicheria-peruana/","si":"culinary","blurb":"Acurio''s flagship Miraflores cebicheria (est. 2005), Latin America''s 50 Best - the definitive lunch-only ceviche experience.","commission":"DMC food-program AOR / Viator affiliate 4-8%; walk-in pass-through"},{"name":"Pisco Sour at the Country Club English Bar","si_tag":"Culinary","status":"future","hook":"SUMMUM-award-winning Pisco Sour (2012/2013/2022 best bar in Lima) in the 1927 hotel''s traditional English Bar.","bookable_category":"walk-in / hotel guest","tier":"premier","commission_path":"pairs with Country Club stay (hotel AOR); bar spend pass-through","source":"https://en.wikipedia.org/wiki/Country_Club_Lima_Hotel","si":"culinary","blurb":"SUMMUM-award-winning Pisco Sour (2012/2013/2022 best bar in Lima) in the 1927 hotel''s traditional English Bar.","commission":"pairs with Country Club stay (hotel AOR); bar spend pass-through"},{"name":"Huaca Pucllana","si_tag":"Culture & Heritage","status":"future","hook":"Pre-Inca (~200-700 AD) adobe pyramid in the heart of Miraflores, with an acclaimed on-site restaurant overlooking the floodlit ruin.","bookable_category":"site tour / restaurant","tier":"premier","commission_path":"DMC/affiliate on tour; site fee + restaurant pass-through","source":"https://www.tripadvisor.com/Attraction_Review-g294316-d311722-Reviews-Huaca_Pucllana-Lima_Lima_Region.html","si":"culture","blurb":"Pre-Inca (~200-700 AD) adobe pyramid in the heart of Miraflores, with an acclaimed on-site restaurant overlooking the floodlit ruin.","commission":"DMC/affiliate on tour; site fee + restaurant pass-through"},{"name":"Convento de San Francisco catacombs","si_tag":"Culture & Heritage","status":"future","hook":"1540 Franciscan monastery in the UNESCO Centro Historico with catacombs holding tens of thousands of bones.","bookable_category":"guided city tour","tier":"comfort","commission_path":"DMC/affiliate 4-10%; entry pass-through","source":"https://kaypiperutours.com/must-visit-attractions-in-lima/","si":"culture","blurb":"1540 Franciscan monastery in the UNESCO Centro Historico with catacombs holding tens of thousands of bones.","commission":"DMC/affiliate 4-10%; entry pass-through"},{"name":"Larco Museum (Museo Larco)","si_tag":"Culture & Heritage","status":"future","hook":"Pre-Columbian masterpiece collection in an 18th-c. mansion over a pyramid, with a famed garden restaurant; the ''Huacas & Larco by night'' tour is a classic.","bookable_category":"entry / night tour + dinner","tier":"premier","commission_path":"Viator night-tour affiliate 4-8%; entry pass-through","source":"https://www.viator.com/tours/Lima/Huacas-and-Larco-Museum-by-Night-with-Dinner/d928-7465P4","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"Pre-Columbian masterpiece collection in an 18th-c. mansion over a pyramid, with a famed garden restaurant; the ''Huacas & Larco by night'' tour is a classic.","when":"year-round","commission":"Viator night-tour affiliate 4-8%; entry pass-through"},{"name":"Pachacamac archaeological complex","si_tag":"Culture & Heritage","status":"future","hook":"Vast pre-Inca/Inca pilgrimage city (pyramids, temples, plazas) ~30 km south of Lima with an on-site museum; easy half-day.","bookable_category":"DMC/Viator day tour","tier":"comfort","commission_path":"DMC 10-12% / affiliate 4-8%; site entry pass-through","source":"https://kaypiperutours.com/must-visit-attractions-in-lima/","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"Vast pre-Inca/Inca pilgrimage city (pyramids, temples, plazas) ~30 km south of Lima with an on-site museum; easy half-day.","when":"year-round","commission":"DMC 10-12% / affiliate 4-8%; site entry pass-through"},{"name":"Callao Monumental street-art district","si_tag":"Culture & Heritage","status":"future","hook":"Regenerated Callao port-district arts quarter - murals, galleries and design studios in old republican buildings; go with a vetted tour.","bookable_category":"guided art tour (zone awareness)","tier":"comfort","commission_path":"DMC/affiliate 4-10%; confirm live tour product + safe corridor","source":"https://kaypiperutours.com/must-visit-attractions-in-lima/","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"Regenerated Callao port-district arts quarter - murals, galleries and design studios in old republican buildings; go with a vetted tour.","when":"year-round","commission":"DMC/affiliate 4-10%; confirm live tour product + safe corridor"},{"name":"Barranco + Puente de los Suspiros","si_tag":"Romance & Honeymoons","status":"live","hook":"Bohemian seafront district - murals, galleries, the romance-legend Bridge of Sighs and sunset bars; Lima''s honeymoon base.","bookable_category":"self-guided within corridor / guided art walk","tier":"luxury","commission_path":"pairs with Hotel B/Barranco boutique stay (hotel AOR); walk affiliate 4-8%","source":"https://kaypiperutours.com/must-visit-attractions-in-lima/","si":"romance","blurb":"Bohemian seafront district - murals, galleries, the romance-legend Bridge of Sighs and sunset bars; Lima''s honeymoon base.","commission":"pairs with Hotel B/Barranco boutique stay (hotel AOR); walk affiliate 4-8%"},{"name":"Miraflores Malecon + Parque del Amor at sunset","si_tag":"Romance & Honeymoons","status":"live","hook":"Clifftop coastal promenade above the Pacific with the mosaic ''Park of Love'' - the classic Lima romance postcard, free.","bookable_category":"free / paired with clifftop dinner","tier":"essential","commission_path":"bundled into commissionable romance program / dinner","source":"https://kaypiperutours.com/must-visit-attractions-in-lima/","si":"romance","blurb":"Clifftop coastal promenade above the Pacific with the mosaic ''Park of Love'' - the classic Lima romance postcard, free.","commission":"bundled into commissionable romance program / dinner"},{"name":"Tandem paragliding off the Miraflores cliffs","si_tag":"Global Expedition Adventures","status":"live","hook":"Guided tandem flight over the Costa Verde clifftops and Pacific from the ~80 m Miraflores launch - the signature Lima adventure.","bookable_category":"reputable tandem operator / Viator (guided-only)","tier":"premier","commission_path":"affiliate 4-8% / DMC 10-12%","source":"https://pariwana-hostel.com/en/blog/2025/10/07/paragliding-in-lima-a-complete-guide-to-flying-over-the-costa-verde/","si":"expedition","blurb":"Guided tandem flight over the Costa Verde clifftops and Pacific from the ~80 m Miraflores launch - the signature Lima adventure.","commission":"affiliate 4-8% / DMC 10-12%"},{"name":"Costa Verde surf lesson","si_tag":"Global Expedition Adventures","status":"live","hook":"Guided surf school on the Miraflores/Barranco beach breaks (Makaha/Waikiki); cold-water summer swell, certified instructor + wetsuit.","bookable_category":"surf school / Viator (guided-only)","tier":"comfort","commission_path":"affiliate 4-8%","source":"https://pariwana-hostel.com/en/blog/2025/10/07/paragliding-in-lima-a-complete-guide-to-flying-over-the-costa-verde/","si":"expedition","blurb":"Guided surf school on the Miraflores/Barranco beach breaks (Makaha/Waikiki); cold-water summer swell, certified instructor + wetsuit.","commission":"affiliate 4-8%"}],"faq":[{"q":"How do I actually get a table at Maido, Central or Kjolle?","a":"Book weeks ahead — the tables are the binding constraint, not the hotel. Central, Maido and Kjolle open reservations on a rolling monthly/multi-week basis and sell out, so the culinary itinerary must be built reservation-first; grey winter is fine because the dining is indoors.","source":"ohlalima.com, 2026-07-07","si_tag":"culinary"},{"q":"What can I see in Lima in a day or two?","a":"More than you''d expect for a gateway city. Walk to Huaca Pucllana (a ~200–700 AD adobe pyramid in Miraflores), the Convento de San Francisco (founded 1540) catacombs in the UNESCO Centro Histórico, and the Larco Museum''s 5,000-year pre-Columbian collection in an 18th-century mansion.","source":"kaypiperutours.com, 2026-07-07","si_tag":"culture"},{"q":"Is Lima good for a honeymoon?","a":"Yes — the base is bohemian Barranco, Lima''s most walkable, romantic district, home to the Puente de los Suspiros (\"Bridge of Sighs\") and to Hotel B, a restored 1914 Belle Époque arts-mansion that is the city''s only Relais & Châteaux.","source":"relaischateaux.com, 2026-07-07","si_tag":"romance"},{"q":"Can you paraglide over Lima, and is it safe?","a":"Yes, with a certified tandem operator only. Flights launch from the ~80 m Miraflores clifftop over the Costa Verde; responsible operators won''t launch in strong crosswind, low visibility or unstable air and will reschedule. Best window is Dec–Apr, midday to late afternoon, when summer thermals build and the garúa clears.","source":"pariwana-hostel.com, 2026-07-07","si_tag":"expedition"},{"q":"Is Lima safe right now?","a":"Yes — it''s freely bookable at Level 2. Peru''s advisory (reissued 2025-05-16; codes C+K+U) is standard caution, below TWW''s disclosure threshold; the Level 4 \"Do Not Travel\" zones (Colombia-border Loreto, the VRAEM) are far from Lima and off the tourist circuit. `book_enabled = true`, no consent flow.","source":"travel.state.gov, 2026-07-07","si_tag":"safety"},{"q":"What''s the real risk to plan for in Lima?","a":"Urban street crime, not any activity. Stay in Miraflores, Barranco and San Isidro; use only registered radio-taxis, ride-hail apps or hotel transfers — never an unmarked street taxi, the classic express-kidnapping setup (forced ATM withdrawals over 1–3 hours). Use in-bank ATMs and keep valuables out of sight.","source":"bushop.com, 2026-07-07","si_tag":"safety"},{"q":"Is the ceviche safe to eat?","a":"Yes — eat the great version, coach away from the risky one. Ceviche (raw fish \"cooked\" in citrus) is Lima''s signature dish; the safety line is to eat it at reputable, high-turnover cebicherías (La Mar and peers) at lunch when the fish is freshest, not at low-traffic street stalls, and stick to bottled/purified water.","source":"limacitykings.com, 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Lima Peru Travel Guide 2026 — World''s #1 Restaurant, Pre-Inca Ruins & Barranco | TravelWell.World","meta_description":"Plan Lima, Peru: the world''s #1 restaurant (Maido), Central, Kjolle and La Mar; pre-Inca Huaca Pucllana, Larco Museum and Pachacamac; bohemian Barranco; luxury Belmond & Relais & Chateaux stays; and clear L2 safety with zone/taxi coaching.","slug":"lima-peru","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-07","search_language":["en","es-PE"],"local_keywords":["qué hacer en Lima","mejores restaurantes Lima","Barranco Miraflores","Puente de los Suspiros","tour Huaca Pucllana","Museo Larco","Pachacámac desde Lima","parapente Costa Verde Lima","mejor época para viajar a Lima","cebicherías Lima","pisco sour Lima"],"hreflang":["en","es-PE"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"romance","status":"live"},{"si":"expedition","status":"live"},{"si":"culinary","status":"future"},{"si":"culture","status":"future"}],"ultra":[{"name":"Miraflores Park, A Belmond Hotel","why_ultra":"82-room clifftop Pacific-Riviera flagship in Miraflores; boutique service + full-luxury amenities; Lima''s iconic ultra address and a Belmond = Virtuoso-preferred flag (CLAUDE.md moat)","earning":"on application / host-Virtuoso or Fora (Amex FHR-listed)","virtuoso_value_add":"Virtuoso-preferred / consortia amenities where eligible (verify)","mor":true,"tier":"ultra"},{"name":"Hotel B","why_ultra":"Lima''s only Relais & Chateaux - restored 1914 Belle Epoque arts-mansion in Barranco, connected to the Lucia de la Puente gallery; the romance/honeymoon ultra pick","earning":"on application / Fora or Relais & Chateaux consortia where eligible","virtuoso_value_add":"consortia amenities where eligible (verify)","mor":true,"tier":"ultra"},{"name":"Country Club Lima Hotel","why_ultra":"five-star 1927 San Isidro landmark (California-colonial, national heritage), Leading Hotels of the World; award-winning Perroquet + SUMMUM-winning English Bar Pisco Sour; living-history grandeur","earning":"on application / host-Virtuoso or Fora / LHW Leaders Club where eligible","virtuoso_value_add":"LHW/consortia amenities where eligible (verify)","mor":true,"tier":"luxury"},{"name":"JW Marriott Hotel Lima","why_ultra":"oceanfront Miraflores tower on the Costa Verde clifftop, steps from Larcomar/Malecon; best-located branded-luxury oceanfront with Bonvoy + STARS/Luminous eligibility","earning":"on application / Marriott STARS/Luminous or Fora where eligible","virtuoso_value_add":"STARS/Luminous amenities where eligible (verify)","mor":true,"tier":"luxury"}],"source_verified":"2026-07-07","hero":{"query":"Lima, Peru"},"geo":{"lat":-12.0464,"lng":-77.0428}}'::jsonb, 58),
  ('loreto-mexico', '10S', 'Loreto', 'Mexico', 'Blue whales and five empty islands', 'live', 'verified', 'mountainValley', 'Baja California Sur (Los Cabos & La Paz)', '{"expedition","tropical","diveglobal","romance"}', '{"tropical"}', '{"essential","premier"}', null, null, '{"key_facts":["Loreto Bay sheltered by 5 uninhabited islands (Coronado, del Carmen, Danzante, Monserrat, Santa Catalina); marine park w/ 40+ dive/snorkel sites (Source: wildloreto.com, 2026-07-04)","Blue-whale season ~Jan-Mar, strongest early Feb to mid-Mar (Source: thoroughlytravel.com, 2026-07-04)","Humpback, fin, sei whales + dolphins, rays, sea lions, turtles also frequent the bay (Source: thoroughlytravel.com, 2026-07-04)","Whale tours depart Loreto Marina / Marina Puerto Escondido, 4-6 h (Source: sallysees.com, 2026-07-04)","LTO airport served by Alaska/American/Volaris/WestJet; no non-stop LTO-SJD (Source: flightsfrom.com, 2026-07-04)"],"safety":{"emergency":"911","nearest_trauma":"Loreto clinics for routine; serious trauma/recompression to La Paz (~350 km) or Los Cabos","advisory_level":"L2","advisory_note":"Baja California Sur US Level 2 (Exercise Increased Caution), May 29, 2026 — freely bookable, disclose L2, no hold","malaria":"none","dengue":"present in Baja California Sur (Loreto ~2 cases YTD 2026, low); use repellent","water":"bottled/purified","hurricane":"May 15-Nov 30, peak Aug-Oct"},"timing":{"peak":"Dec-Apr (whale season; blue whale Feb-Apr; dry mild high season)","shoulder":"May, Oct-Nov","green":"Jun-Sep (hot, hurricane-exposed, best rates)","booking_window_lead_time":"3-6 months for whale-season stays + panga slots; resort peak weeks further out","out_of_season_fill":"summer island-snorkel, kayak, TPC golf packages","holiday_event_peaks":["Blue Whale Festival (whale season)","US/Canada winter escape peak","Danzante Bay golf invitational (autumn)"],"campaign_start_trigger":"early fall (Sep-Oct) for Jan-Mar whale window; summer green-season golf/island campaigns"},"jewels":[{"si_tag":"expedition","status":"live","tier":"premier","commission":"operator agreement","name":"Blue-whale watching","si":"expedition"},{"si_tag":"expedition","status":"live","tier":"essential","commission":"operator","name":"Sierra de la Giganta / mission-canyon hike","si":"expedition"},{"si_tag":"tropical","status":"live","tier":"essential","commission":"operator","name":"Isla Coronado snorkel day","si":"tropical"},{"si_tag":"tropical","status":"live","tier":"essential","commission":"operator","name":"Isla del Carmen / Puerto Balandra snorkel","si":"tropical"},{"si_tag":"tropical","status":"live","tier":"premier","commission":"resort/operator","name":"Isla Danzante / Danzante Bay","si":"tropical"},{"si_tag":"diveglobal","status":"future","tier":"premier","commission":"operator agreement","name":"Loreto Bay Marine Park dives (40+ sites)","si":"diveglobal"},{"si_tag":"romance","status":"future","tier":"premier","commission":"resort contract","name":"Villa del Palmar spa + Danzante Bay golf escape","si":"romance"}],"faq":[{"q":"When is the best time to see blue whales in Loreto?","a":"Roughly January–March, strongest early February to about mid-March, because that''s when blue whales feed in the bay; gray and humpback come slightly earlier. Tours are 4–6-hour pangas from Loreto Marina or Puerto Escondido — book the short window 3–6 months ahead.","source":"thoroughlytravel.com / sallysees.com, 2026-07-04","si_tag":"expedition"},{"q":"What are Loreto''s islands like?","a":"Five uninhabited islands — Coronado, del Carmen, Danzante, Monserrat and Santa Catalina — shelter the bay with turquoise coves, white-sand beaches and a sea-lion colony, all inside a protected marine park with 40+ snorkel/dive sites. Isla Coronado is the classic day trip.","source":"wildloreto.com, 2026-07-04","si_tag":"tropical"},{"q":"Is Loreto good for a golf-and-spa couples escape?","a":"Yes, if you want premier rather than ultra. Villa del Palmar at Danzante Bay has Mexico''s only TPC course (Best Golf Course in Mexico 2020) and a 39,000-sq-ft spa on a secluded bay — position it as a premier golf-and-whale escape, not an Aman-tier ultra.","source":"villadelpalmarloreto.com, 2026-07-04","si_tag":"romance"},{"q":"Is Loreto safe to visit?","a":"Yes — freely bookable. Baja California Sur is US State Dept Level 2 (May 29, 2026) and one of Mexico''s safer states; dengue is low here (Loreto reported ~2 cases YTD 2026).","source":"travel.state.gov, 2026-05-29 / oem.com.mx, 2026-07-04","si_tag":"safety"},{"q":"What''s the real risk to plan for — is the diving remote?","a":"Yes — chamber distance is the gatekeeper. Loreto has local clinics for routine care, but a serious dive bend routes ~350 km south to the La Paz chamber (or Los Cabos), so dive conservatively, keep whale-panga trips to licensed no-chase operators, and observe 18–24 h no-fly before the LTO departure.","source":"scubaboard.com / dan.org, 2026-07-04","si_tag":"safety"}],"seo":{"meta_title":"Loreto Mexico — Blue Whales, Marine Park & Island Snorkel | TravelWell.World","meta_description":"Loreto, Baja California Sur: blue-whale season, five uninhabited islands, Loreto Bay Marine Park diving, TPC Danzante Bay golf. Pueblo Magico gateway, plan by season.","primary_keywords":["Loreto Mexico","blue whale watching Loreto","Loreto Bay National Park","Loreto islands"],"long_tail":["best time to see blue whales in Loreto","Loreto whale watching tours 2026","Isla Coronado snorkel","TPC Danzante Bay golf","Villa del Palmar Loreto"],"search_language":"es-MX","local_keywords":["avistamiento de ballena azul Loreto","Parque Nacional Bahia de Loreto","islas de Loreto","buceo Loreto","Pueblo Magico Loreto","tours de ballenas Loreto"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-04"},"booking":null,"si_checklist_25":null,"sis_present":["expedition","tropical","diveglobal","romance"],"ultra":[{"what":"Villa del Palmar at the Islands of Loreto by Danzante Bay (premier, not true ultra)","why_ultra":"Mexico''s only TPC course (Rees Jones; Best Golf Course in Mexico 2020), 39,000-sq-ft spa, secluded bay","earning":"on application / via host-Virtuoso if preferred program exists (verify — not confirmed Virtuoso)","virtuoso_value_add":"resort credit/upgrade where preferred program applies; else standard commission via bedbank/MoR","mor":"resale under resort contract; position as premier golf + whale escape, not Aman/FS-tier ultra; nearest true ultra = Los Cabos/East Cape"}],"source_verified":"2026-07-04","hero":{"query":"Loreto, Mexico"},"geo":{"lat":26.0115,"lng":-111.3486}}'::jsonb, 59),
  ('los-barriles-mexico', '10S', 'Los Barriles', 'Mexico', 'Los Barriles kiteboarding', 'live', 'verified', 'tropicalBeach', 'Baja California Sur (Los Cabos & La Paz)', '{"ocean","expedition","tropical"}', '{"tropical"}', '{"comfort","premier"}', null, null, '{"key_facts":["East Cape town on the Sea of Cortez, ~1 hr from Los Cabos Airport / ~40 min from La Paz","El Norte kite/wind season Nov 1 - end of March; N/NE crosswind 15-30 knots, afternoon peak","Offshore sportfishing peaks May-early November (marlin, sailfish, dorado, wahoo, tuna); glass-calm","Dorado Shoot Out (~mid-July, ~140 boats) is the largest dorado tournament in Baja; East Cape Offshore / Bisbee''s circuit opener nearby","Villas + fishing lodges are the lodging rung (Van Wormer Palmas de Cortez / Playa del Sol); northern gateway to Cabo Pulmo"],"safety":{"emergency":"911","hospital":"remote small town, no major trauma on-site; La Paz ~40 min (Hospital Salvatierra/private) or Los Cabos/San Jose del Cabo ~1 hr (private) - FLAG MEDEVAC DISTANCE; carry medical + evac insurance","advisory_level":"L2","malaria":"effectively none in Baja California Sur","dengue":"circulates in Mexico - use repellent","water":"drink bottled/purified water","hurricane":"Jun-Nov - trip insurance for summer/fall","wind_watersport":"El Norte 15-30 kt with offshore-drift risk - lessons with rescue-boat cover, correct kite size, helmet/impact vest for beginners","offshore_fishing":"open Sea of Cortez - licensed charter, VHF, life jackets, float plan, sun/heat protection; slow rescue on remote coast","dive":"diving south at Cabo Pulmo (separate dossier); nearest hyperbaric chamber Los Cabos or La Paz; no-fly 18-24h; DAN +1-919-684-9111; remote-distance flag"},"timing":{"peak":"Nov-Mar (El Norte kite/wind season) - highest occupancy, schools full, villas booked; whale + whale-shark window","shoulder":"Apr & Oct (wind tapering / fishing ramping; softer rates)","green":"May-early Nov (glass-calm offshore = billfish/dorado peak + summer tournaments; desert heat + hurricane window Jun-Nov)","booking_window_lead_time":"villas + fishing lodges for Nov-Mar wind season and summer tournament dates book 4-9 months ahead; tournament weeks (Dorado Shoot Out mid-July, East Cape Offshore) tightest; shoulder short-lead; verify current tournament dates","out_of_season_fill_the_beds":"Apr-May/Oct = calm-water Sea of Cortez beach town + snorkel/SUP + ATV + Cabo Pulmo day trips; La Paz whale-shark add-ons Oct-Apr; summer = glass-calm offshore fishing + tournament energy","holiday_event_peaks":"Christmas-New Year (peak wind + snowbird villas), Semana Santa, Mexican summer holidays; tournament weekends spike lodging hardest","campaign_start_trigger":"open kite/wind campaigns late summer (for Nov-Mar); open sportfishing/tournament campaigns late winter (for May-Nov); market kite and fishing audiences separately - opposite seasons","event_peaks":["El Norte kite/wind Nov-Mar","Dorado Shoot Out ~mid-July + East Cape Offshore / Bisbee''s opener","whale season Dec-Apr","La Paz whale sharks ~Oct-Apr"],"sources":["https://www.wahoowind.com/about","https://vanwormerresorts.com/sport-fishing","https://discoverbaja.com/2026/06/03/summer-2026-baja-fishing-tournaments/","https://sallysees.com/whale-watching-in-baja-california-sur/"]},"jewels":[{"name":"El Norte kiteboarding season (Nov-Mar)","si_tag":"Ocean Adventures","status":"future","tier":"premier","bookable":"Wahoo Wind Co. / Vela Baja lessons + rentals","commission_path":"kite-school operator on application + GYG affiliate","source":"https://www.wahoowind.com/about","timing":"Nov-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"reliable 15–30 kt N/NE cross-wind on a protected sandy bay","si":"ocean","blurb":"reliable 15–30 kt N/NE cross-wind on a protected sandy bay","when":"Nov-Mar","commission":"kite-school operator on application + GYG affiliate"},{"name":"Wingfoil / windsurf clinics","si_tag":"Ocean Adventures","status":"future","tier":"premier","bookable":"local wind schools","commission_path":"operator on application","source":"https://middlecasa.com/why-los-barriles-is-mexicos-winter-mecca-for-kitesurfers/","hook":"multi-day progression on the same El Norte wind","si":"ocean","blurb":"multi-day progression on the same El Norte wind","commission":"operator on application"},{"name":"Offshore billfish/dorado charter","si_tag":"Ocean Adventures","status":"future","tier":"premier","bookable":"Van Wormer fleet / Charter Maria Teresa","commission_path":"charter on application","source":"https://vanwormerresorts.com/sport-fishing","timing":"Nov-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","when":"Nov-Mar","commission":"charter on application"},{"name":"Dorado Shoot Out tournament week","si_tag":"Ocean Adventures","status":"future","tier":"premier","bookable":"tournament entry + Palmas de Cortez lodging","commission_path":"lodge/charter on application","source":"https://discoverbaja.com/2026/06/03/summer-2026-baja-fishing-tournaments/","timing":"Nov-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"~mid-July, ~140 boats, largest dorado tournament in Baja","si":"ocean","blurb":"~mid-July, ~140 boats, largest dorado tournament in Baja","when":"Nov-Mar","commission":"lodge/charter on application"},{"name":"ATV / off-road desert + beach run","si_tag":"GEA","status":"live","tier":"comfort","bookable":"Los Barriles Adventures / local ATV operators","commission_path":"operator + Viator affiliate","source":"https://www.tripadvisor.com/Attraction_Review-g1544261-d23230066-Reviews-Los_Barriles_Adventures-Los_Barriles_Baja_California.html","hook":"quad rides into the sierra to remote beaches, snorkel coves, historic lighthouse","si":"GEA","blurb":"quad rides into the sierra to remote beaches, snorkel coves, historic lighthouse","commission":"operator + Viator affiliate"},{"name":"Winter whale watching (offshore)","si_tag":"GEA","status":"live","tier":"comfort","bookable":"local boat operators / Amstar","commission_path":"operator + affiliate","source":"https://sallysees.com/whale-watching-in-baja-california-sur/","si":"GEA","commission":"operator + affiliate"},{"name":"La Paz whale-shark day trip","si_tag":"GEA","status":"live","tier":"premier","bookable":"La Paz operator day trip + transfer","commission_path":"operator + Viator affiliate","source":"https://www.cabopulmopark.com/","si":"GEA","commission":"operator + Viator affiliate"},{"name":"Calm-water Sea of Cortez beach day (off-wind season)","si_tag":"Tropical Islands","status":"future","tier":"comfort","bookable":"villa + local SUP/snorkel rental","commission_path":"rental + villa","source":"https://www.globeguide.ca/travel-guide-los-barriles-mexico/","hook":"swim/snorkel/SUP the warm gulf when El Norte is down","si":"tropical","blurb":"swim/snorkel/SUP the warm gulf when El Norte is down","commission":"rental + villa"}],"faq":[{"q":"When is kiteboarding season in Los Barriles?","a":"November 1 to the end of March, when the \"El Norte\" wind blows a reliable 15–30 kt N/NE crosswind, building mid-morning and peaking in the afternoon. The wide, protected sandy bay suits all levels — book instructors and beachfront villas 4–9 months out.","source":"wahoowind.com, 2026-07-04","si_tag":"ocean"},{"q":"When is the fishing best, and what''s the big tournament?","a":"Offshore peaks May to early November in glass-calm water for marlin, dorado, wahoo and tuna, and the marquee event is the mid-July Dorado Shoot Out — ~140 boats, Baja''s largest dorado tournament. Kite and fishing are opposite seasons, so plan for one or the other.","source":"vanwormerresorts.com / discoverbaja.com, 2026-07-04","si_tag":"ocean"},{"q":"What else is there beyond wind and fish?","a":"Winter whale-watching (Dec–Apr) offshore, ATV desert-and-beach runs year-round, and the La Paz whale-shark snorkel ~40 minutes north (Oct–Apr). Off the wind season (Apr–Oct) the Sea of Cortez turns calm for swimming, snorkel and SUP.","source":"sallysees.com / globeguide.ca, 2026-07-04","si_tag":"expedition"},{"q":"Is Los Barriles safe, and how remote is it?","a":"Freely bookable — Baja California Sur is US State Dept Level 2 (May 29, 2026) and one of Mexico''s safer states — but remote. There''s no major trauma center in town; serious cases go to La Paz (~40 min) or Los Cabos (~1 hr), so flag medevac distance for offshore and kite incidents.","source":"travel.state.gov, 2026-05-29 / globeguide.ca, 2026-07-04","si_tag":"safety"},{"q":"Is kiteboarding here dangerous?","a":"It''s for the prepared — the core hazard is offshore drift. El Norte''s 15–30 kt N/NE wind is side-offshore, so a downed kiter drifts toward open sea; take lessons with a school running rescue-boat cover, use the right kite size and self-rescue skills, and check the daily wind before launch.","source":"wahoowind.com, 2026-07-04","si_tag":"safety"}],"seo":{"meta_title":"Los Barriles Mexico: Kiteboarding, Fishing & El Norte Winds 2026","meta_description":"Los Barriles on Baja''s East Cape — El Norte kiteboarding season (Nov–Mar), world-class marlin/dorado sportfishing, villas, ATV desert runs and the gateway to Cabo Pulmo.","slug":"los-barriles-mexico","primary_keyword":"Los Barriles kiteboarding","long_tail":["Los Barriles El Norte wind season","Los Barriles sportfishing dorado marlin","Dorado Shoot Out tournament Los Barriles","Los Barriles East Cape villa rentals","kitesurfing Los Barriles vs La Ventana"],"search_language":["en","es-MX"],"local_keywords":["Los Barriles kitesurf temporada El Norte","pesca deportiva Los Barriles dorado marlin","torneo Dorado Shoot Out Los Barriles","villas renta Los Barriles Baja","clases de kite Los Barriles","qué hacer en Los Barriles","Los Barriles cómo llegar desde Los Cabos"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-04"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"ocean","status":"future"},{"si":"GEA (Great Escapes & Adventures)","status":"live"},{"si":"tropical","status":"future"}],"ultra":[{"name":"Hotel Palmas de Cortez (Van Wormer)","posture":"premier fishing resort + tournament host in-town; not five-star brand","price_tier":"premier","earning":"on application via host / DMC","virtuoso_value_add":"n/a-branded - treat as premier fishing lodge","mor":"no net-rate resale","source":"https://vanwormerresorts.com/"},{"name":"Premier beachfront villas (Punta Pescadero / Los Barriles)","posture":"top private-stay rung locally for wind-week/fishing groups","price_tier":"luxury","earning":"on application via host / villa manager","virtuoso_value_add":"private villa + kite/fishing days brought in","mor":"agency terms, no net-rate resale","source":"https://abajavacation.com/"}],"source_verified":"2026-07-04","hero":{"query":"Los Barriles, Mexico"},"geo":{"lat":23.682,"lng":-109.696}}'::jsonb, 60)
insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('magdalena-bay-mexico', '10S', 'Magdalena Bay', 'Mexico', 'Gray-whale lagoon, marlin bait-balls', 'live', 'verified', 'oceanAerial', 'Baja California Sur (Los Cabos & La Paz)', '{"expedition","ocean"}', '{}', '{"essential","premier","luxury"}', null, null, '{"key_facts":["Gray-whale breeding lagoon; whales arrive late Dec-early Jan, stay to early/late Apr, peak Jan-Mar (Source: seakayakadventures.com, 2026-07-04)","Famously ''friendly'' gray whales approach boats for close encounters (Source: randomtrip.net, 2026-07-04)","Striped-marlin + sea-lion bait balls form ~mid-Oct-Dec (sardine run) (Source: magdalenabaywhales.com, 2026-07-04)","~5-6 h from Cabo San Lucas, ~3.5-4 h from La Paz; whale towns Puerto San Carlos & Lopez Mateos (Source: randomtrip.net, 2026-07-04)","Lodging is barrier-island glamping camp (~US$650+ 1-night all-in) or basic town hotels — no resorts (Source: thoroughlytravel.com, 2026-07-04)"],"safety":{"emergency":"911","nearest_trauma":"basic local care in Puerto San Carlos / Lopez Mateos; serious trauma to La Paz (~3.5-4 h) or Los Cabos (~5-6 h)","advisory_level":"L2","advisory_note":"Baja California Sur US Level 2 (Exercise Increased Caution), May 29, 2026 — freely bookable, disclose L2, no hold","malaria":"none","dengue":"present in Baja California Sur; use repellent","water":"bottled/purified","hurricane":"May 15-Nov 30, peak Aug-Oct (whale/marlin windows largely outside peak)","remote_medevac":"remote Pacific coast; barrier-island camp is boat-access only — long ground evac"},"timing":{"peak":"gray-whale HARD window ~mid-Jan-mid-Mar (calving lagoon)","second_peak":"sardine run / striped-marlin bait ball, mid-Oct-Dec","shoulder":"late Dec-early Jan (arrival), late Mar-Apr (tail-end)","green":"May-Sep (off-season, hot, hurricane-exposed)","booking_window_lead_time":"6-12 months (tiny whale-camp capacity, both windows sell out early)","out_of_season_fill":"minimal; sport fishing + birding fill edges","holiday_event_peaks":["US/Canada winter escape overlaps gray-whale peak"],"campaign_start_trigger":"gray-whale 9-12 months out; marlin/sardine-run by mid-summer for Oct-Dec"},"jewels":[{"si_tag":"expedition","status":"live","tier":"premier","commission":"operator agreement","name":"Gray-whale calving-lagoon encounter","si":"expedition"},{"si_tag":"expedition","status":"live","tier":"premier","commission":"operator; net-rate red","name":"Barrier-island whale-camp overnight","si":"expedition"},{"si_tag":"expedition","status":"live","tier":"essential","commission":"operator","name":"Mangrove / birding skiff","si":"expedition"},{"si_tag":"ocean","status":"future","tier":"premier","commission":"operator agreement","name":"Snorkel-with-striped-marlin bait ball (sardine run)","si":"ocean"},{"si_tag":"ocean","status":"future","tier":"luxury","commission":"operator/wholesale","name":"Striped-marlin liveaboard (Nautilus)","si":"ocean"}],"faq":[{"q":"When is gray-whale season in Magdalena Bay?","a":"The hard window is roughly mid-January to mid-March, when mothers and calves fill the calving lagoon; whales arrive late Dec–early Jan and linger to April. Mag Bay''s grays are famously \"friendly,\" often approaching the pangas — book the tiny whale-camp capacity 6–12 months ahead.","source":"seakayakadventures.com / randomtrip.net, 2026-07-04","si_tag":"expedition"},{"q":"Can I snorkel the striped-marlin bait balls?","a":"Yes, from about mid-October to December — but it''s an advanced open-water activity. You''re offshore in current among fast-moving marlin and sea lions driving sardines to the surface, so it''s for confident, fit snorkelers and freedivers with specialist operators only.","source":"magdalenabaywhales.com / divernet.com, 2026-07-04","si_tag":"ocean"},{"q":"Where do I stay — are there resorts?","a":"No resorts — the accurate options are a barrier-island whale camp (glamping, 1–7 nights, ~$650+ for a 1-night all-in) or basic hotels in Puerto San Carlos and López Mateos. The camp is part of the experience: whales from shore, and nothing between you and the lagoon.","source":"thoroughlytravel.com, 2026-07-04","si_tag":"expedition"},{"q":"Is Magdalena Bay safe, and how remote is it?","a":"Freely bookable — Baja California Sur is US State Dept Level 2 (May 29, 2026) — but genuinely remote. The whale towns have only basic care; serious trauma routes ~3.5–4 h to La Paz or ~5–6 h to Los Cabos, and the barrier-island camp is boat-access only, so carry evacuation insurance.","source":"travel.state.gov, 2026-05-29 / randomtrip.net, 2026-07-04","si_tag":"safety"},{"q":"Is the bait-ball snorkel dangerous?","a":"It is not a beginner activity. The sardine run happens offshore in current among fast predators, so go only with specialist operators, follow the guide''s positioning rules and never touch the wildlife; if you dive elsewhere in Baja, the nearest chambers are La Paz and Cabo San Lucas with 18–24 h no-fly.","source":"divernet.com / sssnetwork.com, 2026-07-04","si_tag":"safety"}],"seo":{"meta_title":"Magdalena Bay — Gray-Whale Lagoon & Striped-Marlin Sardine Run | TravelWell.World","meta_description":"Magdalena Bay, Baja California Sur: gray-whale calving lagoon (Jan-Mar) and the striped-marlin bait-ball sardine run (Oct-Dec). Whale-camp stays, seasons, safe-panga guidance.","primary_keywords":["Magdalena Bay whale watching","gray whale Magdalena Bay","striped marlin bait ball","Baja sardine run"],"long_tail":["gray whale season Magdalena Bay 2026","snorkel with striped marlin Baja","Magdalena Bay whale camp","Puerto San Carlos whale watching","how to get to Magdalena Bay from Los Cabos"],"search_language":"es-MX","local_keywords":["ballena gris Bahia Magdalena","avistamiento de ballenas Puerto San Carlos","marlin rayado Bahia Magdalena","corrida de la sardina Baja","campamento de ballenas Bahia Magdalena"],"hreflang":["en","es-MX"],"jsonld_type":"TouristAttraction","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-04"},"booking":null,"si_checklist_25":null,"sis_present":["expedition","ocean"],"ultra":[{"what":"National Geographic / Lindblad expedition cruise to Magdalena Bay (sea-based); or Los Cabos/East Cape ultra property as pre/post base","why_ultra":"small-ship expedition w/ naturalists is the only refined product on the bay; no land ultra exists here (nearest = Los Cabos/East Cape 3.5-6 h away)","earning":"on application / via host-Virtuoso; expedition-cruise lines carry advisor commission","virtuoso_value_add":"shipboard credit/expedition perks via preferred programs, or resort credit at Los Cabos base","mor":"resale via host-Virtuoso / cruise-wholesale only; Magdalena Bay lodging itself is NOT ultra"}],"source_verified":"2026-07-04","hero":{"query":"Magdalena Bay, Mexico"},"geo":{"lat":24.6167,"lng":-112.1}}'::jsonb, 61),
  ('mahahual-mexico', '10S', 'Mahahual (Costa Maya & Banco Chinchorro)', 'Mexico', '*If it''s the largest coral atoll in the Northern', 'live', 'verified', 'oceanAerial', 'Quintana Roo (Cancún & Riviera Maya)', '{"liveaboard","diveglobal"}', '{}', '{"comfort","premier"}', null, 'anchor', '{"key_facts":["Banco Chinchorro - largest coral atoll in the Northern Hemisphere; biosphere 144,000 ha; ~25x10 mi","~80-90 min (some ops ~2.5h) boat from Mahahual; ~200 shipwrecks; permit-restricted (op handles permit)","Best viz May-Sep (~15-30m); crocodile-encounter season Jun 1-Sep 30 (XTC = sole federal permit)","Overnight = palafito stilt-hut on Cayo Centro (legalized 2010; no services) - the liveaboard-style product","Costa Maya cruise port (2nd-largest in Caribbean Mexico, up to ~20k cruisers) = OUT of TWW cruise scope"],"safety":{"emergency":"911","dan_emergency":"+1-919-684-9111","advisory_level":"L2","nearest_chamber":"Costamed, COZUMEL (DAN-certified) - Mahahual clinic has NO chamber; long medevac from Chinchorro","nearest_trauma":"Chetumal (Hospital General, south) or evac to Cancun","malaria":"NONE in tourist zone; dengue present","water":"bottled/purified","hurricane":"Jun-Nov, peak Aug-Oct","dive_no_fly":"18-24h (DAN)","special_rule":"REMOTE-MEDEVAC - dive conservative; permitted+certified op only; croc encounter handler-led, max 6/trip"},"timing":{"peak":"Dive peak May-Sep (viz ~15-30m; croc encounter hard window Jun 1-Sep 30)","shoulder":"Apr and Oct edges","green":"Nov-Mar (wind/swell; Chinchorro often blown out - fall back to Costa Maya/Xcalak reef)","booking_lead":"4-6 months for permit-limited summer Chinchorro/croc product (permit scarcity = longer lead than a general reef trip)","off_season_specials":"winter Nov-Mar: Costa Maya/Xcalak mainland-reef dive days + no-fly beach fill-the-beds (lean Xcalak, south of the cruise port)","event_peaks":"croc window Jun 1-Sep 30; (Costa Maya cruise day-crowds peak Sep-Dec, busiest Nov, Wed/Thu - OUT of TWW scope, plan dive departures around it)","campaign_start":"live by Dec-Jan, ~4-6 months ahead of the May-Sep dive window; run a winter Xcalak-reef value campaign for Nov-Mar fill-the-beds"},"jewels":[{"name":"Chinchorro overnight palafito expedition (Cayo Centro)","si_tag":"Dive Liveaboards","status":"live","bookable_category":"multi-day dive expedition","tier":"premier","commission_path":"on application (liveaboard-reseller/dive-op host)","source":"https://pepedivemahahual.com/en/diving/chinchorro/","timing":"Dive peak May-Sep","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"multi-day dive with stilt-hut overnight on the atoll ·","si":"liveaboard","blurb":"multi-day dive with stilt-hut overnight on the atoll ·","when":"Dive peak May-Sep","commission":"on application (liveaboard-reseller/dive-op host)"},{"name":"~200-wreck atoll dives","si_tag":"Dive Liveaboards","status":"live","bookable_category":"wreck/wall diving","tier":"premier","commission_path":"dive-op host ~10-20% / on application","source":"https://xtcdivecenter.com/chinchorro/","timing":"Dive peak May-Sep","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","when":"Dive peak May-Sep","commission":"dive-op host ~10-20% / on application"},{"name":"Chinchorro day-boat 2-3 tank + Cayo Centro","si_tag":"Dive Globally","status":"live","bookable_category":"day dive charter","tier":"comfort","commission_path":"dive-op host / affiliate","source":"https://xtcdivecenter.com/chinchorro/","timing":"Dive peak May-Sep","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"state day-trip, 2-tank $275 / 3-tank $325, Cayo Centro surface stop ·","si":"diveglobal","blurb":"state day-trip, 2-tank $275 / 3-tank $325, Cayo Centro surface stop ·","when":"Dive peak May-Sep","commission":"dive-op host / affiliate"},{"name":"Costa Maya / Xcalak reef diving","si_tag":"Dive Globally","status":"live","bookable_category":"day dive charter","tier":"comfort","commission_path":"dive-op host ~10-20%","source":"https://amigosdelmar.net/","timing":"Dive peak May-Sep","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","when":"Dive peak May-Sep","commission":"dive-op host ~10-20%"},{"name":"Wild American-crocodile in-water encounter (XTC)","si_tag":"Global Expedition Adventures","status":"future","bookable_category":"expert-guided wildlife","tier":"premier","commission_path":"dive-op host / on application; XTC sole permit","source":"https://xtcdivecenter.com/crocs/croc-encounters/","timing":"Dive peak May-Sep","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"handler-led encounter, world''s only permitted such experience ·","si":"expedition","blurb":"handler-led encounter, world''s only permitted such experience ·","when":"Dive peak May-Sep","commission":"dive-op host / on application; XTC sole permit"}],"faq":[{"q":"Is Mahahual safe to visit right now?","a":"Yes - freely bookable, no hold. Mahahual sits in Quintana Roo (US State Dept Level 2, Exercise Increased Caution, dated 2026-05-29). It''s a remote fishing village on the Costa Maya; the real planning here is medical and dive-logistical, not crime.","source":"travel.state.gov","si_tag":"safety"},{"q":"What''s the real risk to plan for diving Mahahual?","a":"Remote medevac - the load-bearing risk. Mahahual has NO hyperbaric chamber; the nearest DAN-certified chamber is in Cozumel, a multi-hour transit from a Chinchorro site ~25 miles offshore. Dive conservatively, hold no-fly 18-24h, and treat DCS as a logistics problem.","source":"costamed.com.mx","si_tag":"safety"},{"q":"When is the best time to dive Mahahual and Chinchorro?","a":"May-September - the counterintuitive answer: calmest seas, best visibility (~15-30m) and the crocodile season (Jun 1-Sep 30), even though it overlaps the rainy/hurricane months. Winter (Nov-Mar) sees more wind and Chinchorro is often blown out.","source":"coralrealm.com","si_tag":"diveglobal"},{"q":"Can I day-dive Banco Chinchorro, and how?","a":"Yes - most Mahahual/Xcalak operators run day-trips for certified divers: a 2-tank ($275) or 3-tank ($325) day with a Cayo Centro stop, an 80-90-minute crossing each way. The operator handles the limited federal permit when you book; May-September has the calmest seas.","source":"xtcdivecenter.com","si_tag":"diveglobal"},{"q":"Can you really swim with wild crocodiles at Chinchorro?","a":"Yes - it''s the only legally permitted in-water wild-crocodile encounter on Earth, and only XTC Dive Center holds the federal permit. The season is a hard window of June 1 to September 30, capped at 6 people (2 in the water with the handler at a time), flotation device required. Book far ahead.","source":"xtcdivecenter.com","si_tag":"globaladv"},{"q":"What is the Banco Chinchorro liveaboard experience actually like?","a":"It''s a stilt-hut expedition, not a cruise ship. Multi-day trips overnight in a palafito on Cayo Centro - a basic 2x2m stilt-deck fishing hut with hammocks and no services - legalized in 2010. It''s the closest access to the remote walls and ~200 wrecks; permit-scarce, so book the specialist operator well ahead.","source":"pepedivemahahual.com","si_tag":"liveaboard"}],"seo":{"meta_title":"Mahahual & Banco Chinchorro: Atoll Diving Guide","meta_description":"Mahahual is the gateway to Banco Chinchorro - the Northern Hemisphere''s largest coral atoll: ~200 wrecks, croc encounters, and the remote-chamber realities.","slug":"mahahual-mexico","primary_keyword":"Banco Chinchorro diving","long_tail":["Mahahual Banco Chinchorro dive","Chinchorro liveaboard palafito","Chinchorro crocodile snorkel XTC","Costa Maya diving","Xcalak scuba diving"],"search_language":"es","local_keywords":["buceo Banco Chinchorro","Mahahual buceo Costa Maya","encuentro con cocodrilos Xcalak","buceo Xcalak","atolon Chinchorro liveaboard palafito"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister - commercial pilot, 56 countries","content_freshness":"2026-07-04"},"booking":{"bin":"freely_bookable","level":"L2","codes":[],"consent_flow":false,"note":"Quintana Roo US L2 (Exercise Increased Caution, dated 2026-05-29) - freely bookable; the real planning is dive-medevac (nearest chamber Cozumel), not crime; MXN currency, dive prices often USD-quoted"},"si_checklist_25":{"run_date":"2026-07-30","hits":4,"misses":18,"disregarded":3,"note":"Canonical 25-SI list; Banco Chinchorro moat = largest N-Hemisphere atoll (~200 wrecks) + sole permitted wild-crocodile encounter (XTC); sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"liveaboard","name":"liveaboard","status":"live","note":"overnight-palafito multi-day on Cayo Centro (stilt-hut, not a cruise ship)"},{"si":"diveglobal","name":"diveglobal","status":"live"}],"ultra":[{"name":"Private crewed Chinchorro dive charter / private palafito buy-out","why_ultra":"exclusive-use permitted multi-day atoll expedition - the rarest dive product in Mexican waters (permit-scarce, ~200 wrecks, sole-group access)","earning":"on application (dive-op/charter host / liveaboard-reseller)","virtuoso_value_add":"none formal (specialist dive charter, not a consortia hotel)","mor":"commission-on-net, agent-of-record; no net-rate resale"},{"name":"Nearest branded ultra = Riviera Maya (Mayakoba: Rosewood/Banyan Tree; Maroma A Belmond)","why_ultra":"n/a locally - branded-residence ultra sits far north; route ultra client Mahahual-for-dive + Riviera-Maya-for-stay","earning":"via host-Virtuoso (see Playa del Carmen / Puerto Morelos dossiers)","virtuoso_value_add":"upgrade / breakfast / resort credit (per those dossiers)","mor":"commission-on-net"}],"source_verified":"2026-07-04","hero":{"query":"Mahahual (Costa Maya & Banco Chinchorro), Mexico"},"geo":{"lat":18.7167,"lng":-87.7167}}'::jsonb, 62),
  ('manaus-amazon-brazil', '10S', 'Manaus & the Brazilian Amazon', 'Brazil', 'Where two great rivers meet', 'live', 'verified', 'desertDunes', 'Amazon, Pantanal & Iguaçu', '{"adventure","river","romance","wildlife"}', '{}', '{"essential","comfort","premier","ultra"}', null, null, '{"key_facts":null,"safety":{"emergency":"190","emergency_medical":"192","advisory_level":"L2","advisory_source":"https://travel.state.gov/content/travel/en/traveladvisories/traveladvisories/brazil-travel-advisory.html","book_enabled":true,"bin":"freely bookable (L2)","consent_flow":false,"air_access_verified":{"international":"MAO (Eduardo Gomes International, Manaus) — direct Miami + Panama City","domestic":"MAO — São Paulo / Brasília / Belém via LATAM, Gol, Azul"},"remote_flag":true,"malaria":"low in urban Manaus, real in deep-forest lodges — prophylaxis a lodge+season decision with a travel clinic","vaccinations":["yellow fever (required-in-practice, all Manaus travelers, ≥10 days pre-travel, single lifetime dose)","routine (DTP, MMR, polio, hep A/B) up to date"],"water":"bottled / lodge-treated only (no untreated river or tap water)","caveats":["High-vs-low water: the trip changes with the season — set expectations","Yellow fever vaccine required-in-practice ≥10 days pre-travel","Malaria prophylaxis for deep-forest lodges; dengue/Zika/chikungunya year-round, active 2026","Jungle-lodge remoteness — hours by river from Manaus hospitals; confirm evac insurance","Manaus urban crime — vetted transport, discreet valuables, night-area discipline","River safety — lifejackets on all transfers/excursions"]},"timing":{"peak_high_water":"March–August, peaking Jun–Jul — flooded-forest / canoe-the-canopy Amazon","peak_low_water":"September–February — river beaches, hiking, peacock-bass fishing","inflection":"mid–late April (high-water established; Jun–Jul lodge/riverboat inventory locks)","fire_date":"late March (high-water curve-start − 1–2 wks); mirror fire date late August for the low-water product","off_season_fill":"none true — opposite peaks mean year-round sell; pivot copy to whichever product the calendar delivers","note":"the product itself changes with water level — high-water = flooded-forest canoeing; low-water = beaches/hiking/fishing; itineraries must state which"},"jewels":[{"name":"Meeting of the Waters (Encontro das Águas)","si_tag":"adventure","tier":"essential","commission_path":"DMC / tour affiliate half-day; park fee non-commissionable","source":"https://www.viator.com/Manaus-attractions/Meeting-of-Waters/d4441-a6911","hook":"the 6-km line where the warm dark Rio Negro and the pale cooler Solimões run side by side without mixing, the signature Amazon spectacle","si":"adventure","blurb":"the 6-km line where the warm dark Rio Negro and the pale cooler Solimões run side by side without mixing, the signature Amazon spectacle","commission":"DMC / tour affiliate half-day; park fee non-commissionable"},{"name":"Jungle-lodge canopy + night walk","si_tag":"adventure","tier":"comfort","commission_path":"DMC lodge package (AOR)","source":"https://www.rainforestcruises.com/lodges/mirante-do-gaviao","hook":"the core lodge product: elevated canopy walkways by day, spotlight forest walk by night, naturalist naming birds, insects, tree frogs","si":"adventure","blurb":"the core lodge product: elevated canopy walkways by day, spotlight forest walk by night, naturalist naming birds, insects, tree frogs","commission":"DMC lodge package (AOR)"},{"name":"Presidente Figueiredo waterfalls + river-caves","si_tag":"adventure","tier":"essential","commission_path":"DMC / tour affiliate full-day; municipal fee non-commissionable","source":"https://www.viator.com/tours/Manaus/Presidente-Figueiredo-Waterfalls-Day-Trip-from-Manaus/d4441-2484MAOFALLS","hook":"the \"Land of Waterfalls\" 107 km / ~1.5 h north of Manaus: Iracema and Araras falls, Lagoa Cristalina, and river-caves home to bats, turtles","si":"adventure","blurb":"the \"Land of Waterfalls\" 107 km / ~1.5 h north of Manaus: Iracema and Araras falls, Lagoa Cristalina, and river-caves home to bats, turtles","commission":"DMC / tour affiliate full-day; municipal fee non-commissionable"},{"name":"Night caiman-spotting + piranha fishing","si_tag":"adventure","tier":"comfort","commission_path":"DMC lodge package (AOR)","source":"https://offroadstravel.com/home/amazon-brazil-tour/","hook":"the two classic after-dark / on-water lodge excursions; spotlight the shallows for orange caiman eyeshine, drop a hand-line for piranha","si":"adventure","blurb":"the two classic after-dark / on-water lodge excursions; spotlight the shallows for orange caiman eyeshine, drop a hand-line for piranha","commission":"DMC lodge package (AOR)"},{"name":"Amazon riverboat expedition (Iberostar Grand Amazon)","si_tag":"river","tier":"premier","commission_path":"DMC / consortia / cruise affiliate; all-inclusive package","source":"https://www.rainforestcruises.com/cruises/iberostar-grand-amazon","hook":"72-cabin 5★ all-inclusive expedition boat, 4/5/8-day Solimões + Negro itineraries from Manaus, English-guided excursions, ending at the Meeting of the Waters","si":"river","blurb":"72-cabin 5★ all-inclusive expedition boat, 4/5/8-day Solimões + Negro itineraries from Manaus, English-guided excursions, ending at the Meeting of the Waters","commission":"DMC / consortia / cruise affiliate; all-inclusive package"},{"name":"Small-group expedition riverboat (Katerre / Jacaré-Açu)","si_tag":"river","tier":"premier","commission_path":"DMC / operator (Amazonas by Viverde) net/commission package","source":"https://amazonastravel.com.br/expedicao-katerre-i.html","hook":"low-impact small-group boats, Novo Airão / Anavilhanas / Jaú, full board with drinks, bilingual guide, park entries, Novo Airão embarkation","si":"river","blurb":"low-impact small-group boats, Novo Airão / Anavilhanas / Jaú, full board with drinks, bilingual guide, park entries, Novo Airão embarkation","commission":"DMC / operator (Amazonas by Viverde) net/commission package"},{"name":"Anavilhanas archipelago","si_tag":"wildlife","tier":"comfort","commission_path":"DMC / lodge / riverboat; park fee non-commissionable","source":"https://national-parks.org/brazil/anavilhanas-national-park/","hook":"the second-largest river archipelago on Earth: 400 forested islands over 90 km of the Rio Negro, a UNESCO-caliber protected area of igarapés, black-water channels","si":"wildlife","blurb":"the second-largest river archipelago on Earth: 400 forested islands over 90 km of the Rio Negro, a UNESCO-caliber protected area of igarapés, black-water channels","commission":"DMC / lodge / riverboat; park fee non-commissionable"},{"name":"Pink river dolphins (boto), Novo Airão","si_tag":"wildlife","tier":"comfort","commission_path":"DMC day-trip / lodge excursion; platform-regulated","source":"https://www.aventuradobrasil.com/blog/swimming-with-pink-dolphins-in-brazil/","hook":"the famous Rio Negro boto, encountered at regulated floating platforms ~180 km from Manaus; a genuine wildlife highlight","si":"wildlife","blurb":"the famous Rio Negro boto, encountered at regulated floating platforms ~180 km from Manaus; a genuine wildlife highlight","commission":"DMC day-trip / lodge excursion; platform-regulated"},{"name":"Indigenous / ribeirinho community visit","si_tag":"wildlife","tier":"comfort","commission_path":"vetted DMC / operator AOR only (ethical, community-consenting)","source":"https://amazontourmanaus.com/manaus-amazon/the-amazon-rainforest/anavilhanas-national-park/item162","hook":"a visit to a river-people or indigenous community, done through a genuinely vetted, community-consenting operator","si":"wildlife","blurb":"a visit to a river-people or indigenous community, done through a genuinely vetted, community-consenting operator","commission":"vetted DMC / operator AOR only (ethical, community-consenting)"},{"name":"Teatro Amazonas opera house","si_tag":"Romance & Honeymoons / Culture","tier":"essential","commission_path":"DMC / city-tour affiliate; performance/visit ticket non-commissionable","source":"https://en.wikipedia.org/wiki/Amazon_Theatre","hook":"the 1896 belle-époque jewel of the rubber boom: Alsatian roof tiles, Glaswegian steel, Carrara-marble stairs, a dome of 36,000 tiles in the national colours","si":"Romance & Honeymoons / Culture","blurb":"the 1896 belle-époque jewel of the rubber boom: Alsatian roof tiles, Glaswegian steel, Carrara-marble stairs, a dome of 36,000 tiles in the national colours","commission":"DMC / city-tour affiliate; performance/visit ticket non-commissionable"},{"name":"Design jungle-lodge honeymoon (Mirante do Gavião / Anavilhanas)","si_tag":"romance","tier":"ultra","commission_path":"DMC lodge package / consortia (AOR)","source":"https://www.here-away.com/mirantedogaviaoamazonlodge","hook":"a boutique design lodge over black water: canopy hammock, private dawn canoe, floating bar, spa/wellness space, dolphin-swim afternoon. The adventurous honeymoon","si":"romance","blurb":"a boutique design lodge over black water: canopy hammock, private dawn canoe, floating bar, spa/wellness space, dolphin-swim afternoon. The adventurous honeymoon","commission":"DMC lodge package / consortia (AOR)"}],"faq":null,"seo":{"meta_title":"Manaus & the Brazilian Amazon Travel Guide 2026 — Meeting of the Waters, Jungle Lodges & Amazon Cruises | TravelWell","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","freshness":"2026-07-07","search_language":"pt-BR","local_keywords":["Manaus Amazônia o que fazer","Encontro das Águas passeio","cruzeiro Rio Negro Amazonas","melhores lodges de selva na Amazônia","botos cor-de-rosa Novo Airão","cachoeiras Presidente Figueiredo","Teatro Amazonas visita","vacina febre amarela Manaus","Manaus é seguro para turistas","lua de mel na Amazônia","arquipélago de Anavilhanas","Amazônia cheia e vazante melhor época"],"hreflang":["en","pt-BR"]},"booking":null,"si_checklist_25":null,"sis_present":null,"ultra":[{"name":"Mirante do Gavião Amazon Lodge","lane":"Fora/consortia","mor":"consortia","tier":"ultra","note":"12-suite design lodge, Novo Airão / Anavilhanas edge"},{"name":"Anavilhanas Jungle Lodge","lane":"consortia/Fora","mor":"consortia","tier":"premier","note":"glass-wall bungalows, floating bar, pool, spa"},{"name":"Juma Amazon Lodge","lane":"consortia/DMC","mor":"consortia/DMC","tier":"comfort","note":"stilted treetop bungalows ~15m, solar-powered"},{"name":"Iberostar Grand Amazon (riverboat)","lane":"consortia/cruise affiliate","mor":"consortia/operator","tier":"premier","note":"72-cabin all-inclusive expedition; verify consortia lane"}],"source_verified":null,"hero":{"query":"Manaus & the Brazilian Amazon, Brazil"},"geo":{"lat":-3.119,"lng":-60.0217}}'::jsonb, 63),
  ('manuel-antonio-costa-rica', '10S', 'Manuel Antonio', 'Costa Rica', 'Sloths, monkeys and Pacific cliffs', 'live', 'verified', 'tropicalBeach', 'Costa Rica', '{"tropical","expedition","wildlife"}', '{"tropical"}', '{"essential","comfort","premier","luxury","ultra"}', null, null, '{"key_facts":["Manuel Antonio NP is open Wed–Mon 07:00–16:00, CLOSED every Tuesday; adult entry US$18, child (2–12) US$5, under-2 free; advance online ticket + passport number required.","One of few places to see all of Costa Rica''s iconic wildlife at a beach: 2- & 3-toed sloths, white-faced capuchins (90%+ of visits), endangered Central American squirrel monkeys, howlers, coatis, toucans.","Two park beaches: crescent Playa Manuel Antonio (calm, turquoise — best/safest swim) and longer, choppier Playa Espadilla Sur.","Access: ~2.5–3 hr / ~168 km drive from San José (SJO), OR ~25-min domestic flight to Quepos–Manuel Antonio (XQP) on Sansa / Costa Rica Green Airways + 15 km / 25-min transfer.","Cliffside-resort belt (Arenas del Mar, Makanda, Gaia, Tulemar) makes it a top romance/honeymoon hub; hillside villas make it a strong family/multi-gen hub."],"safety":{"emergency":"911","hospital":"Hospital Metropolitano Quepos (private, 24-hr, marina) + public Max Terán Valls Hospital; serious cases to San José major hospitals (~2.5–3 hr) with air evac available","advisory_level":"L2","book_enabled":true,"l2_disclosure":true,"advisory_note":"US Level 2 Exercise Increased Caution (reissued 2026-04-02); clean L2, no L4 zone near Manuel Antonio/Quepos; standard caution — petty crime, don''t display wealth, avoid poorly lit beaches at night, enroll in STEP","air_access_verified":"SJO gateway; XQP (Quepos–Manuel Antonio) ~25-min domestic flight on Sansa / Costa Rica Green Airways, or ~2.5–3 hr drive from SJO","riptide":"HARD FLAG — rip currents are the leading cause of tourist drowning in Costa Rica (>80% of drownings); most beaches unguarded. Swim only at guarded/flagged beaches (park cove safest), heed red flags, never swim alone; if caught, swim parallel to shore.","wildlife":"Bold habituated monkeys/raccoons/coatis raid food — no feeding, seal food, don''t leave bags unattended","dengue":"Year-round mosquito-borne risk (higher green season May–Nov); no widely available traveler vaccine — DEET/picaridin, cover at dawn/dusk, screened/AC rooms","water":"Tap water in San José & major tourist areas (incl. Manuel Antonio/Quepos) treated and generally safe; sensitive stomachs / remote lodges use bottled/filtered"},"timing":{"inflection_curve_start":"late October–early November","peak":"mid-December–April (Christmas/New Year & Semana Santa ~1 yr lead)","fire_date":"2026-10-17","shoulder":"May–November (green-season value)","green":"May–November (afternoon rain; lush, lower rates)","booking_lead":"3–8 weeks normal peak; ~1 year for Christmas/New Year & Semana Santa (lead pressure on cliffside-resort + villa beds)","off_season_specials":"green-season resort/villa discounts + whale-watching backfill (Jul–Oct/Nov Southern-Hemisphere humpbacks)","event_peaks":["Whale season Jul–Oct/Nov (peak Aug–Sep)","Whale season Dec–Mar/Apr (peak Jan–Feb)","Christmas/New Year","Semana Santa (Easter)"],"operational_note":"Manuel Antonio NP closed every Tuesday — route park visit Wed–Mon; slot waterfalls/catamaran/mangrove on Tuesday"},"jewels":[{"name":"Playa Manuel Antonio (in-park)","si_tag":"Tropical Islands / Beaches","status":"live","hook":"Crescent white sand + calm turquoise — the park''s best and safest swim/snorkel, backed by monkey-filled rainforest.","bookable_category":"guided park tour / DIY ticket","tier":"essential","commission_path":"GYG/Viator or host-IATA guide; park entry non-commissionable","source":"https://www.mustseespots.com/costa-rica/articles/manuel-antonio-national-park-beaches-wildlife-trails-explained/ + Accessed 2026-07-06","timing":"mid-December–April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Tropical Islands / Beaches","blurb":"Crescent white sand + calm turquoise — the park''s best and safest swim/snorkel, backed by monkey-filled rainforest.","when":"mid-December–April","commission":"GYG/Viator or host-IATA guide; park entry non-commissionable","accessed":"2026-07-06"},{"name":"Playa Biesanz","si_tag":"Tropical Islands / Beaches","status":"live","hook":"Small jungle-backed calm cove on Quepos Point — the local''s-choice calm-swim/kayak/snorkel beach away from crowds.","bookable_category":"DIY + gear / guided kayak-snorkel","tier":"essential","commission_path":"thin/DIY concierge add-on; small guided kayak-snorkel via affiliate","source":"https://www.earthtrekkers.com/things-to-do-in-manuel-antonio/ + Accessed 2026-07-06","timing":"mid-December–April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"Tropical Islands / Beaches","blurb":"Small jungle-backed calm cove on Quepos Point — the local''s-choice calm-swim/kayak/snorkel beach away from crowds.","when":"mid-December–April","commission":"thin/DIY concierge add-on; small guided kayak-snorkel via affiliate","accessed":"2026-07-06"},{"name":"Catamaran sunset + snorkel","si_tag":"GEA","status":"live","hook":"~4-hr coastal catamaran with snorkeling, meals, seasonal dolphins/whales — the signature on-the-water romance experience.","bookable_category":"catamaran tour / private charter","tier":"comfort","commission_path":"GYG/Viator affiliate; DMC/host-IATA for private charter","source":"https://www.thecostaricatoursite.com/manuel-antonio/Snorkeling_Tours.php + Accessed 2026-07-06","si":"GEA","blurb":"~4-hr coastal catamaran with snorkeling, meals, seasonal dolphins/whales — the signature on-the-water romance experience.","commission":"GYG/Viator affiliate; DMC/host-IATA for private charter","accessed":"2026-07-06"},{"name":"Nauyaca Waterfalls day trip","si_tag":"GEA","status":"live","hook":"~1.5 hr away; steep hike (or 4x4/horseback) to two massive cascades + natural swimming pools.","bookable_category":"guided day tour","tier":"comfort","commission_path":"GYG/Viator affiliate; host-IATA land services","source":"https://www.earthtrekkers.com/things-to-do-in-manuel-antonio/ + Accessed 2026-07-06","si":"GEA","blurb":"~1.5 hr away; steep hike (or 4x4/horseback) to two massive cascades + natural swimming pools.","commission":"GYG/Viator affiliate; host-IATA land services","accessed":"2026-07-06"},{"name":"Damas Island mangrove kayak","si_tag":"GEA","status":"live","hook":"Calm-water estuary/mangrove kayak north of Quepos — monkeys, crocodiles and birds; superb family + wildlife half-day.","bookable_category":"half-day kayak tour","tier":"essential","commission_path":"GYG/Viator affiliate + local operator; host-IATA private","source":"https://www.thecostaricatoursite.com/manuel-antonio/tours/Half-Day-Kayak-Damas-Mangroves.php + Accessed 2026-07-06","si":"GEA","blurb":"Calm-water estuary/mangrove kayak north of Quepos — monkeys, crocodiles and birds; superb family + wildlife half-day.","commission":"GYG/Viator affiliate + local operator; host-IATA private","accessed":"2026-07-06"},{"name":"Rainmaker canopy + hanging bridges","si_tag":"GEA","status":"live","hook":"~1,400-acre private rainforest reserve with waterfalls, trails and Mistico-style suspension bridges — lower-crowd canopy near Manuel Antonio.","bookable_category":"guided canopy/bridges tour","tier":"comfort","commission_path":"GYG/Viator affiliate; host-IATA land services","source":"https://www.earthtrekkers.com/things-to-do-in-manuel-antonio/ + Accessed 2026-07-06","timing":"year-round","timing_type":"ALWAYS-ON","si":"GEA","blurb":"~1,400-acre private rainforest reserve with waterfalls, trails and Mistico-style suspension bridges — lower-crowd canopy near Manuel Antonio.","when":"year-round","commission":"GYG/Viator affiliate; host-IATA land services","accessed":"2026-07-06"},{"name":"Quepos marina sportfishing","si_tag":"GEA","status":"live","hook":"Marina Pez Vela — top Pacific billfish/sailfish + dorado sportfishing base; premier half/full-day charters.","bookable_category":"charter","tier":"premier","commission_path":"host-IATA / private-charter agent-of-record; premium day rates","source":"https://costaricaexperts.com/destinations/manuel-antonio/ + Accessed 2026-07-06","timing":"mid-December–April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"GEA","blurb":"Marina Pez Vela — top Pacific billfish/sailfish + dorado sportfishing base; premier half/full-day charters.","when":"mid-December–April","commission":"host-IATA / private-charter agent-of-record; premium day rates","accessed":"2026-07-06"},{"name":"Whale-watching (Marino Ballena / Uvita)","si_tag":"GEA","status":"live","hook":"~45–60 min south; two humpback seasons (Jul–Oct/Nov + Dec–Mar/Apr) at the whale''s-tail sandbar — spans both green & dry season.","bookable_category":"guided whale-watching boat tour","tier":"comfort","commission_path":"GYG/Viator affiliate + host-IATA; Marino Ballena entry non-commissionable","source":"https://puravidamoms.com/whale-watching-uvita-tour-guide/ + Accessed 2026-07-06","si":"GEA","blurb":"~45–60 min south; two humpback seasons (Jul–Oct/Nov + Dec–Mar/Apr) at the whale''s-tail sandbar — spans both green & dry season.","commission":"GYG/Viator affiliate + host-IATA; Marino Ballena entry non-commissionable","accessed":"2026-07-06"},{"name":"National Park wildlife walk (sloths + 4 monkey species)","si_tag":"Wildlife","status":"future","hook":"2- & 3-toed sloths, capuchins, endangered squirrel monkeys, howlers, coatis, toucans — reliably seen with a certified scope-guide.","bookable_category":"guided park wildlife tour","tier":"essential","commission_path":"GYG/Viator affiliate or host-IATA guide; park entry non-commissionable","source":"https://www.adventuretourscostarica.com/blog/spotting-sloths-monkeys-your-manuel-antonio-wildlife-guide + Accessed 2026-07-06","timing":"mid-December–April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"wildlife","blurb":"2- & 3-toed sloths, capuchins, endangered squirrel monkeys, howlers, coatis, toucans — reliably seen with a certified scope-guide.","when":"mid-December–April","commission":"GYG/Viator affiliate or host-IATA guide; park entry non-commissionable","accessed":"2026-07-06"}],"faq":[{"q":"Is Manuel Antonio National Park open on Tuesday?","a":"No — the park is closed every Tuesday, year-round including holidays. It is open Wednesday–Monday 07:00–16:00; adult entry is $18, children 2–12 $5, under-2 free, and advance online ticket purchase with your passport number is required — route the park visit Wed–Mon.","source":"machupicchu.org, 2026-07-06","si_tag":"tropical"},{"q":"Can you see whales near Manuel Antonio?","a":"Yes — nearby Marino Ballena / Uvita has two humpback seasons. Southern-Hemisphere humpbacks run Jul–Oct/Nov (peak Aug–Sep) and Northern-Hemisphere humpbacks Dec–Mar/Apr (peak Jan–Feb), a rare draw spanning both the green and dry seasons, ~45–60 min south by guided boat tour.","source":"puravidamoms.com, 2026-07-06","si_tag":"expedition"},{"q":"Is Manuel Antonio good for a honeymoon?","a":"Yes — it''s one of Costa Rica''s premier romance hubs. The cliffside-resort belt above the beach, led by adults-only Makanda by the Sea ~100 m above the ocean, defines the honeymoon identity, while Arenas del Mar is the only true beachfront luxury resort with two private beaches.","source":"oyster.com, 2026-07-06","si_tag":"romance"},{"q":"Can you really see sloths and monkeys at the beach?","a":"Yes — it''s one of very few places anywhere you reliably can. Two- and three-toed sloths, white-faced capuchins (on 90%+ of visits), the endangered Central American squirrel monkey, howlers, coatis and toucans all live inside a compact, walkable national park where the rainforest meets the sand.","source":"adventuretourscostarica.com, 2026-07-06","si_tag":"wildlife-—-future"},{"q":"Is Manuel Antonio safe to visit right now?","a":"Yes, with standard caution. Costa Rica is U.S. Level 2 — Exercise Increased Caution (reissued April 2, 2026) — the same tier as France, Italy and the UK — and this is a clean L2 with no \"Do Not Travel\" zone near Manuel Antonio or Quepos; disclose standard petty-crime caution and enroll in STEP.","source":"travel.state.gov, 2026-07-06","si_tag":"safety"},{"q":"What''s the biggest safety risk in Manuel Antonio?","a":"Pacific rip currents — the leading cause of tourist drowning in Costa Rica (over 80% of drownings), on mostly unguarded beaches. Swim only at guarded/flagged beaches (the calm park cove of Playa Manuel Antonio is safest), heed red flags, never swim alone, and if caught, swim parallel to shore.","source":"crie.cr, 2026-07-06","si_tag":"safety"},{"q":"Are the monkeys a problem in the park?","a":"They can be — capuchins, raccoons and coatis are bold and habituated and will raid open bags and grab food. Don''t feed wildlife, keep food sealed and bags zipped, and don''t leave belongings unattended on the beach.","source":"adventuretourscostarica.com, 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Manuel Antonio, Costa Rica Travel Guide — Sloths, Rainforest Beaches, Cliffside Resorts & Quepos | TravelWell.World","meta_description":"See sloths and monkeys at a Pacific beach, base on the Quepos cliffs for romance or in a villa for family, and do Manuel Antonio well, safely, and at the right time — park hours, riptide safety, whales, catamarans and waterfalls.","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-06","search_language":"es-CR","long_tail_en":["Manuel Antonio National Park hours 2026","is Manuel Antonio open on Tuesday","best time to visit Manuel Antonio Costa Rica","Manuel Antonio sloths and monkeys guide","Manuel Antonio riptide beach safety","SJO to Quepos flight Manuel Antonio","Manuel Antonio cliffside honeymoon resorts","Manuel Antonio villas with pool family","Nauyaca Waterfalls day trip from Manuel Antonio","Uvita whale watching season from Manuel Antonio"],"local_keywords":["Parque Nacional Manuel Antonio","playas Manuel Antonio","qué hacer en Quepos","avistamiento de ballenas Uvita Marino Ballena","cataratas Nauyaca desde Manuel Antonio","kayak manglares isla Damas","perezosos y monos Manuel Antonio","hoteles de lujo Manuel Antonio","vuelo San José a Quepos","horario Parque Nacional Manuel Antonio precio entrada"],"hreflang":["en","es-CR"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"tropical","status":"live"},{"si":"expedition","status":"live"},{"si":"wildlife","status":"future"}],"ultra":[{"name":"Arenas del Mar (Böÿ Collection / Cayuga)","why_ultra":"The only true beachfront luxury resort in Manuel Antonio — private ridge, two secluded beaches (golf-cart access), rainforest all around, strong sustainability, ocean-view suites with plunge pools. The apex property.","earning":"consortia/agent rate + amenity block; agent-of-record commission","consortia_value_add":"upgrade, breakfast/resort credit, early/late, VIP welcome (confirm current program)","mor":"Fora / host-IATA agent-of-record","tier":"luxury / ultra"},{"name":"Makanda by the Sea","why_ultra":"Adults-only (16+), ~100 m above the ocean on 12 acres of rainforest gardens — the definitive Manuel Antonio honeymoon/romance property; small, private, view-forward.","earning":"consortia/agent rate + amenity","consortia_value_add":"upgrade/credit where program allows (verify)","mor":"Fora / host-IATA","tier":"luxury"},{"name":"Gaia Hotel & Reserve","why_ultra":"Eco-chic adults-oriented 22-room private-reserve hillside hotel; 500-thread-count linens, wellness + service focus.","earning":"consortia/agent rate","consortia_value_add":"upgrade/credit (verify)","mor":"Fora / host-IATA","tier":"premier / luxury"},{"name":"Tulemar Resort (+ private villas)","why_ultra":"Gated hillside estate with its own private sandy beach, 4 pools, concierge, spa, and a portfolio of private villas — the best resort-serviced villa play for families/multi-gen.","earning":"consortia/agent rate + villa MoR","consortia_value_add":"upgrade/credit + villa perks (verify)","mor":"Fora / host-IATA agent-of-record + villa direct-contract","tier":"premier / luxury (villas: luxury/ultra)"},{"name":"Preferred / luxury hillside villas","why_ultra":"Private ocean-view villas (chef/staff, pools, 2–8 br) — the whole-property-buyout ultra lane for honeymooners + multi-gen groups.","earning":"villa MoR + agent-of-record","consortia_value_add":"n/a (villa direct-contract perks vary)","mor":"direct-contract / villa specialist (host-IATA)","tier":"luxury / ultra"}],"source_verified":"2026-07-06","hero":{"query":"Manuel Antonio, Costa Rica"},"geo":{"lat":9.392,"lng":-84.137}}'::jsonb, 64),
  ('mazamitla-mexico', '10S', 'Mazamitla', 'Mexico', '*If it''s chalet cabañas in a pine-oak Sierra, a', 'live', 'verified', 'mountainValley', 'Jalisco (Puerto Vallarta & Guadalajara)', '{"expedition","family","adventure"}', '{}', '{"essential","comfort"}', null, null, '{"key_facts":["Pueblo Mágico (2005) at ~2,200 m in southern Jalisco, ~124–135 km / ~2 hr from Guadalajara; ''Switzerland of Mexico'' (Source: travelagewest.com, Accessed 2026-07-04)","Cool year-round (~15°C avg; ~7–26°C) — a magnet for Guadalajara residents, esp. summer (Source: en.wikipedia.org/wiki/Mazamitla, Accessed 2026-07-04)","El Salto waterfall ~35 m in Los Cazos (private, ~US$1, ~45-min forest hike or horse ~M$250) (Source: zonaturistica.com, Accessed 2026-07-04)","Signature chalet cabañas (e.g., Cabañas Monteverde: kitchens, fireplaces, daily firewood) (Source: travelagewest.com, Accessed 2026-07-04)","Canopy/zipline + six-hanging-bridge tours (Green Forest Tours); La Zanja 1977 town forest (Source: theguadalajarapost.com, Accessed 2026-07-04)"],"safety":{"emergency":"911","hospital":"No major trauma hospital in town; nearest full ER/trauma is Guadalajara ~2 hr / ~124–135 km back down mountain road; local clinic for minor cases; air-evac to US for critical cases","advisory_level":"L3","book_enabled":false,"tourist_zone_carveout":"none","air_access_verified":"via GDL ~2 hr ground (not into a carve-out); approach via Hwy 405 (advisory-designated route)","advisory_note":"Advisory names Mazamitla as a specific EXCEPTION to the Hwy-110 restriction and directs ''travel via Highway 405 only'' — stronger than a blanket exclusion, but still NOT a named safe-zone carve-out; ruling holds at no-Book","malaria":"none","dengue":"very low at ~2,200 m (above Aedes aegypti elevation ceiling)","yellow_fever":"not required"},"timing":{"peak":"Domestic-holiday & weekend peaks — summer (GDL heat escape) + Semana Santa + Christmas/New-Year + long weekends; cool ~15°C year-round draw","waterfall_flow_peak":"October–December (fullest El Salto flow, post-rains)","shoulder":"Non-holiday weekdays / shoulder months","green":"Deep off-holiday midweeks (softest domestic demand)","booking_lead":"Weeks–months for Semana Santa/summer/Christmas/long-weekend cabañas; midweek walk-up-easy; largely direct/domestic","event_peaks":"Semana Santa, summer school holidays, Christmas–New-Year, Mexican puentes","campaign_start":"''Cool-mountain weekend from Guadalajara'' ahead of summer + Semana Santa; waterfall-flow (Oct–Dec) into fall"},"jewels":[{"name":"El Salto waterfall (Los Cazos)","si_tag":"Global Expedition Adventures","status":"future","hook":"~35 m waterfall, ~45-min forest hike (or horseback) to a wooden overlook","bookable_category":"site entry (~US$1) + guide/horse","tier":"essential","commission_path":"day-tour or curated-recommend","source":"https://www.zonaturistica.com/en/things-to-do/jalisco/mazamitla/the-salto-waterfall (Accessed 2026-07-04)","si":"expedition","blurb":"~35 m waterfall, ~45-min forest hike (or horseback) to a wooden overlook","commission":"day-tour or curated-recommend","accessed":"2026-07-04"},{"name":"La Zanja town forest","si_tag":"Global Expedition Adventures","status":"future","hook":"1977 municipal pine forest — trails, cabins, rentable grills","bookable_category":"free/low-cost","tier":"essential","commission_path":"curated-recommend","source":"https://theguadalajarapost.com/2022/06/03/mazamitla-jalisco-what-to-do-and-how-to-get-to-this-magical-town/ (Accessed 2026-07-04)","si":"expedition","blurb":"1977 municipal pine forest — trails, cabins, rentable grills","commission":"curated-recommend","accessed":"2026-07-04"},{"name":"Canopy + six hanging bridges (Green Forest Tours)","si_tag":"Global Expedition Adventures","status":"future","hook":"3-hr zipline + 2-hr six-hanging-bridge forest walk","bookable_category":"operator","tier":"comfort","commission_path":"activity affiliate / day-tour","source":"https://theguadalajarapost.com/2022/06/03/mazamitla-jalisco-what-to-do-and-how-to-get-to-this-magical-town/ (Accessed 2026-07-04)","timing":"year-round","timing_type":"ALWAYS-ON","si":"expedition","blurb":"3-hr zipline + 2-hr six-hanging-bridge forest walk","when":"year-round","commission":"activity affiliate / day-tour","accessed":"2026-07-04"},{"name":"Chalet cabañas (Cabañas Monteverde)","si_tag":"Family","status":"future","hook":"Wooden chalet cabins with kitchens + fireplaces (daily firewood) — the definitive stay","bookable_category":"direct (domestic)","tier":"essential","commission_path":"curated-recommend (direct-only)","source":"https://www.travelagewest.com/Travel/Mexico/mazamitla-mexico-travel-guide (Accessed 2026-07-04)","si":"family","blurb":"Wooden chalet cabins with kitchens + fireplaces (daily firewood) — the definitive stay","commission":"curated-recommend (direct-only)","accessed":"2026-07-04"},{"name":"Enchanted Garden (Los Cazos)","si_tag":"Family","status":"future","hook":"Greenery + crystalline stream, toured on foot/bike/horseback/ATV","bookable_category":"site entry + rentals","tier":"essential","commission_path":"day-tour / curated","source":"https://www.travelagewest.com/Travel/Mexico/mazamitla-mexico-travel-guide (Accessed 2026-07-04)","si":"family","blurb":"Greenery + crystalline stream, toured on foot/bike/horseback/ATV","commission":"day-tour / curated","accessed":"2026-07-04"},{"name":"Los Cazos ATV + horseback","si_tag":"Adventure / Ecotourism","status":"future","hook":"ATV tours + horse rides through pine-oak forest","bookable_category":"licensed operator","tier":"comfort","commission_path":"activity affiliate / day-tour","source":"https://theguadalajarapost.com/2022/06/03/mazamitla-jalisco-what-to-do-and-how-to-get-to-this-magical-town/ (Accessed 2026-07-04)","si":"Adventure / Ecotourism","blurb":"ATV tours + horse rides through pine-oak forest","commission":"activity affiliate / day-tour","accessed":"2026-07-04"}],"faq":[{"q":"Can I book a stay in Mazamitla through TravelWell?","a":"No — it is content-only, recommended only as a licensed day/weekend trip from the Guadalajara carve-out. Jalisco is US State Dept Level 3 (May 29, 2026) and Mazamitla is not one of the four named carve-outs; notably, though, the advisory names Mazamitla as an exception to the Highway 110 restriction and permits access \"via Highway 405 only.\" book_enabled=FALSE.","source":"travel.state.gov, 2026-05-29","si_tag":"safety"},{"q":"What''s the real risk to plan for?","a":"The ~2-hour mountain road transfer, not the town''s street crime (which is low — a domestic family town). The drive from Guadalajara leaves the GDL safe zone, even on the advisory-approved Highway 405, which is the hold reason; use licensed daytime transport only, and note the nearest full trauma hospital is ~2 hr back in Guadalajara.","source":"travel.state.gov / en.wikipedia.org, 2026-07-04","si_tag":"safety"},{"q":"What is there to do at El Salto waterfall?","a":"Hike to it. The ~35 m El Salto falls in Los Cazos are reached by a ~45-minute forest trail (or a horse, ~M$250) to a wooden overlook, entry ~US$1, with the fullest flow October–December after the rains. Sturdy footwear, and turn back in weather.","source":"zonaturistica.com, 2026-07-04","si_tag":"expedition"},{"q":"Is Mazamitla good for a family weekend?","a":"Yes — it is the classic Guadalajara family escape. The product is a wooden chalet cabaña with a full kitchen and fireplace (Cabañas Monteverde delivers firewood daily) in a cool ~15°C pine-oak Pueblo Mágico at 2,200 m; cabañas sell out for Semana Santa, summer and Christmas, so book weeks to months ahead.","source":"travelagewest.com / en.wikipedia.org, 2026-07-04","si_tag":"family"},{"q":"What adventure activities are on offer?","a":"Zip, ride and cross bridges. Green Forest Tours runs a 3-hour zipline and a 2-hour six-hanging-bridge walk, plus ATV, horseback and mountain-biking through the forest and Los Cazos. Use licensed operators with helmet/harness checks — evac to Guadalajara is ~2 hr, so injuries carry a distance penalty.","source":"theguadalajarapost.com, 2026-07-04","si_tag":"adventure"}],"seo":{"meta_title":"Mazamitla Travel Guide — Jalisco''s ''Mexican Switzerland'' Cabaña Mountain Pueblo Mágico | TravelWell.World","meta_description":"Jalisco''s cool pine-forest Pueblo Mágico at 2,200 m — chalet cabañas, the El Salto waterfall, canopy tours, and straight guidance: a Level-3-interior day/weekend trip from Guadalajara (Hwy 405), not a bookable base.","slug":"mazamitla-mexico","primary_keyword":"Mazamitla Mexico travel guide","long_tail":["Mazamitla from Guadalajara day trip","El Salto waterfall Mazamitla","Mazamitla cabañas Monteverde","is Mazamitla safe","Mazamitla Suiza Mexicana things to do"],"search_language":"es-MX","local_keywords":["qué hacer en Mazamitla Pueblo Mágico","Mazamitla desde Guadalajara","cascada El Salto Mazamitla","cabañas en Mazamitla","Mazamitla la Suiza Mexicana","tirolesa puentes colgantes Mazamitla"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-04"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"future"},{"si":"family","status":"future"},{"si":"Adventure / Ecotourism","status":"future"}],"ultra":[],"source_verified":"2026-07-04","hero":{"query":"Mazamitla, Mexico"},"geo":{"lat":19.9153,"lng":-103.0208}}'::jsonb, 65),
  ('medellin-colombia', '10S', 'Medellín & Antioquia, Colombia', 'Colombia', 'Medellín & Antioquia', 'live', 'verified', 'mountainValley', 'Bogotá & The Andes', '{"culture"}', '{}', '{"essential","comfort"}', null, null, '{"key_facts":["City of Eternal Spring — consistently mild climate year-round; elevation ~1,495 m","Comuna 13 is Medellín''s most-visited site; its 2011 outdoor escalators cut a 35-min climb to 6 min","El Peñol rock at Guatapé is climbed via 740 steps over an island-dotted reservoir, ~2 hrs east","Laureles named by Time Out one of the coolest neighborhoods in the world; El Poblado/Provenza is the polished tourist core","Feria de las Flores 2026 runs Jul 31–Aug 9, climaxing in the Aug 9 Desfile de Silleteros (530 silleteros)"],"safety":{"emergency":"123","book_enabled":true,"bin":"BOOK WITH WARNING","risk_codes":["C","T","U","K","N"],"named_danger":["Arauca","Cauca excl Popayán","Valle del Cauca excl Cali","Norte de Santander","Venezuela border ~10km"],"dating_app_drugging_flag":true,"consent_flow":{"bin":"BOOK WITH WARNING","disclosure_required":true,"renders":"full verbatim live US State Dept advisory for Colombia (level + reason + named-danger areas + complete ''If you decide to travel'' guidance), pulled live, plus traveler acknowledgment","wording_status":"hook set only — final consent language PENDING compliance-attorney sign-off"},"air_access_verified":"MDE / José María Córdova (Rionegro) — major direct-air gateway","altitude_m":1495,"notes":"Scopolamine/dating-app drugging — 8 suspicious US-citizen deaths in Medellín Nov–Dec 2023 (US Embassy). Trauma: medical-tourism hub w/ top private clinics; carry US-evac coverage. Dengue present. Tap water generally potable. Zone discipline: El Poblado/Laureles/Envigado; vetted transport; do not resist robbery."},"timing":{"peak":["December–March (drier)","July–August (drier)","Feria de las Flores late-Jul→Aug 9 (headline peak)","December Alumbrados (secondary peak)"],"inflection":"Steep ramp from late Ju