  ('mexico-city-mexico', '10S', 'Mexico City (CDMX)', 'Mexico', '*If it''s the beating heart of the Americas', 'live', 'verified', 'kyoto', 'Mexico City', '{"romance","culture","culinary","nightlife","entertainment"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, null, '{"key_facts":["Anchor of the Central Mexico block — culture, food, and history mega-destination; folds in Centro Histórico, Coyoacán, Roma-Condesa, Polanco, Chapultepec, Xochimilco, Basílica de Guadalupe + Teotihuacán day-trip","Museo Nacional de Antropología holds the Aztec Sun Stone — Mexico''s largest and most-visited museum","Pujol / Quintonil / Contramar form the ''holy trinity'' of CDMX dining; Pujol is top-5 on Latin America''s list","Día de Muertos (Oct 31–Nov 2) is the cultural apex — ~6 km Grand Parade Chapultepec → Reforma → Zócalo (~Nov 1)","Sits at ~2,240 m (7,349 ft) — ~25% less oxygen than sea level; 24–72 hr acclimatization typical"],"safety":{"emergency":"911","hospital":"Centro Médico ABC (International Patient dept, English-speaking); Hospital Ángeles (Lomas/Pedregal); Médica Sur. Air-ambulance evac via insurer.","advisory_level":"L2","book_enabled":true,"tourist_zone_carveout":"CDMX is nationwide-L2 (NOT one of the six Level-4 states); tourist zones (Centro/Reforma/Polanco/Chapultepec/Coyoacán) freely bookable with L2 disclosure","air_access_verified":"MEX/AICM (primary international) + AIFA/NLU Felipe Ángeles (secondary; Tren FA to Buenavista opened Apr 2026)","altitude":"~2,240 m (7,349 ft) — AMS note for sensitive travelers; 24–72 hr acclimatization; guided-only for Izta-Popo/Nevado de Toluca volcano day-hikes","malaria":"none (altitude >2,000 m is above vector zone)","water":"bottled/purified only; tap not for drinking"},"timing":{"inflection_curve_start":"early-to-mid September (Día de Muertos peak); mid-February (spring jacaranda/Semana Santa peak)","peak":"Oct 31 – Nov 2 (Día de Muertos; Grand Parade ~Nov 1). Secondary: Mar–Apr (jacaranda + Semana Santa)","fire_date":"2026-08-25 (Día de Muertos primary); ~2026-02-20 (spring secondary)","shoulder":"May, September","green":"June–September (afternoon rains, mornings clear, lowest rates)","booking_lead":"Centro/Reforma weeks-out for Día de Muertos; Casa Barragán tickets release Tue noon CDMX (sell out in minutes); Teotihuacán balloon + Casa Azul 2–4 weeks ahead; top restaurants weeks ahead","off_season_specials":"June–Sep green-season value stays — weather-resilient (rain is afternoon-only); ''same museums, same Pujol, half the room rate''","event_peaks":["Día de Muertos Oct 31–Nov 2 (marquee)","Jacaranda bloom Mar–Apr","Grito de Independencia Sep 15–16","Semana Santa (moveable Mar/Apr)"]},"jewels":[{"name":"Teotihuacán dawn hot-air balloon","si_tag":"Culture & Heritage","status":"future","hook":"float over the Pyramid of the Sun as the Avenue of the Dead emerges from mist","bookable_category":"private tour/experience","tier":"luxury","commission_path":"Journey Mexico (Fora) or affiliate ~8%","source":"https://www.colima71.com/signature-experiences-mexico-city/hot-air-balloon-in-teotihuacan-experience — Accessed 2026-07-05","timing":"Oct 31","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"float over the Pyramid of the Sun as the Avenue of the Dead emerges from mist","when":"Oct 31","commission":"Journey Mexico (Fora) or affiliate ~8%","accessed":"2026-07-05"},{"name":"Museo Nacional de Antropología","si_tag":"Culture & Heritage","status":"future","hook":"the Aztec Sun Stone + the greatest pre-Columbian collection on earth","bookable_category":"private guided visit","tier":"premier","commission_path":"fixed INAH entry (pass-through) + guide via DMC/affiliate","source":"https://en.wikipedia.org/wiki/National_Museum_of_Anthropology_(Mexico) — Accessed 2026-07-05","timing":"Oct 31","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"the Aztec Sun Stone + the greatest pre-Columbian collection on earth","when":"Oct 31","commission":"fixed INAH entry (pass-through) + guide via DMC/affiliate","accessed":"2026-07-05"},{"name":"Templo Mayor + Centro Histórico (UNESCO)","si_tag":"Culture & Heritage","status":"future","hook":"excavated Aztec ceremonial center beneath the colonial Zócalo","bookable_category":"private walking tour","tier":"comfort","commission_path":"DMC or affiliate ~8%","source":"https://www.tripadvisor.com/Attraction_Review-g150800-d153711-Reviews-Museo_Nacional_de_Antropologia-Mexico_City — Accessed 2026-07-05","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"excavated Aztec ceremonial center beneath the colonial Zócalo","when":"year-round","commission":"DMC or affiliate ~8%","accessed":"2026-07-05"},{"name":"Basílica de Guadalupe","si_tag":"Culture & Heritage","status":"future","hook":"most-visited Catholic pilgrimage site in the Americas; the tilma of Juan Diego","bookable_category":"private half-day tour","tier":"comfort","commission_path":"DMC/affiliate","source":"https://www.casagoliana.com/blog/best-time-to-visit-mexico-city/ — Accessed 2026-07-05","timing":"Oct 31","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"most-visited Catholic pilgrimage site in the Americas; the tilma of Juan Diego","when":"Oct 31","commission":"DMC/affiliate","accessed":"2026-07-05"},{"name":"Coyoacán + Museo Frida Kahlo (Casa Azul)","si_tag":"Culture & Heritage","status":"future","hook":"the cultural heart; Frida''s cobalt-blue house + cobblestone plazas","bookable_category":"combo tour (often w/ Xochimilco)","tier":"comfort","commission_path":"affiliate ~8% (Viator) or DMC private","source":"https://amigotours.com/mexico-city-tours/xochimilco-coyoacan-frida-kahlo-museum-tour/ — Accessed 2026-07-05","timing":"Oct 31","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"the cultural heart; Frida''s cobalt-blue house + cobblestone plazas","when":"Oct 31","commission":"affiliate ~8% (Viator) or DMC private","accessed":"2026-07-05"},{"name":"Casa Luis Barragán (UNESCO)","si_tag":"Culture & Heritage","status":"future","hook":"the modernist master''s house-studio; tickets release Tue noon, sell out in minutes","bookable_category":"timed entry (pass-through) + architecture tour","tier":"premier","commission_path":"concierge add-on + DMC guide","source":"https://www.tripadvisor.com/Attraction_Review-g150800-d184110-Reviews-Casa_Luis_Barragan-Mexico_City — Accessed 2026-07-05","timing":"Oct 31","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"the modernist master''s house-studio; tickets release Tue noon, sell out in minutes","when":"Oct 31","commission":"concierge add-on + DMC guide","accessed":"2026-07-05"},{"name":"Pujol / Quintonil tasting menus","si_tag":"Culinary","status":"future","hook":"top-of-the-world Mexican fine dining + taco omakase; reservations weeks out","bookable_category":"reservation/experience","tier":"luxury","commission_path":"concierge value-add (non-commissionable) — bundle into DMC ultra","source":"https://www.theinfatuation.com/mexico-city/guides/best-mexico-city-restaurants — Accessed 2026-07-05","timing":"Oct 31","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","blurb":"top-of-the-world Mexican fine dining + taco omakase; reservations weeks out","when":"Oct 31","commission":"concierge value-add (non-commissionable) — bundle into DMC ultra","accessed":"2026-07-05"},{"name":"Contramar","si_tag":"Culinary","status":"future","hook":"the sun-drenched seafood institution; tuna tostadas + pescado a la talla","bookable_category":"reservation","tier":"premier","commission_path":"concierge add-on","source":"https://joinpearl.co/restaurants/mexico-city/contramar — Accessed 2026-07-05","timing":"Oct 31","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","blurb":"the sun-drenched seafood institution; tuna tostadas + pescado a la talla","when":"Oct 31","commission":"concierge add-on","accessed":"2026-07-05"},{"name":"Mercado de San Juan","si_tag":"Culinary","status":"future","hook":"the gourmet market of exotic proteins + cheeses — a chef''s playground","bookable_category":"guided food tour","tier":"comfort","commission_path":"affiliate ~8% or DMC","source":"https://www.mezcalistas.com/a-locals-guide-to-mexico-city/ — Accessed 2026-07-05","timing":"Oct 31","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","blurb":"the gourmet market of exotic proteins + cheeses — a chef''s playground","when":"Oct 31","commission":"affiliate ~8% or DMC","accessed":"2026-07-05"},{"name":"Licorería Limantour (Roma)","si_tag":"Nightlife","status":"future","hook":"Best Bar in North America (2022 & 2023) + 2024 backroom speakeasy","bookable_category":"reservation/bar tour","tier":"premier","commission_path":"concierge add-on / guided crawl affiliate","source":"https://www.mezcalistas.com/a-locals-guide-to-mexico-city/ — Accessed 2026-07-05","timing":"Oct 31","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"nightlife","blurb":"Best Bar in North America (2022 & 2023) + 2024 backroom speakeasy","when":"Oct 31","commission":"concierge add-on / guided crawl affiliate","accessed":"2026-07-05"},{"name":"Mezcalerías (Templo Centro + Claraluz Coyoacán)","si_tag":"Nightlife","status":"future","hook":"2024-new prehispanic speakeasy + candlelit mezcal salon, still under the radar","bookable_category":"guided mezcal crawl","tier":"comfort","commission_path":"affiliate ~8% or DMC","source":"https://www.mezcalistas.com/a-locals-guide-to-mexico-city/ — Accessed 2026-07-05","timing":"Oct 31","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"nightlife","blurb":"2024-new prehispanic speakeasy + candlelit mezcal salon, still under the radar","when":"Oct 31","commission":"affiliate ~8% or DMC","accessed":"2026-07-05"},{"name":"Pulquerías (Centro)","si_tag":"Nightlife","status":"future","hook":"traditional fermented-agave cantinas — a genuinely local drinking tradition","bookable_category":"guided cultural bar tour","tier":"essential","commission_path":"affiliate","source":"https://keith.is/guides/cdmx — Accessed 2026-07-05","timing":"Oct 31","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"nightlife","blurb":"traditional fermented-agave cantinas — a genuinely local drinking tradition","when":"Oct 31","commission":"affiliate","accessed":"2026-07-05"},{"name":"Lucha libre at Arena México","si_tag":"Live Entertainment","status":"future","hook":"''the Cathedral'' — masked-wrestling theater in a ~17,000-seat arena","bookable_category":"guided experience + arena admission","tier":"comfort","commission_path":"affiliate up to ~12% (Viator) or DMC","source":"https://www.viator.com/tours/Mexico-City/Tacos-Beer-Lucha-BEST-NIGHT-EVER/d628-86240P2 — Accessed 2026-07-05","timing":"Oct 31","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"entertainment","blurb":"''the Cathedral'' — masked-wrestling theater in a ~17,000-seat arena","when":"Oct 31","commission":"affiliate up to ~12% (Viator) or DMC","accessed":"2026-07-05"},{"name":"Día de Muertos Grand Parade","si_tag":"Live Entertainment","status":"future","hook":"~6 km Nov-1 parade Chapultepec → Reforma → Zócalo; biggest live-culture moment","bookable_category":"parade-window package (hotel + guided viewing)","tier":"premier","commission_path":"DMC (Fora lane) — book weeks out","source":"https://www.casagoliana.com/blog/day-of-the-dead-parade-mexico-city-2026/ — Accessed 2026-07-05","timing":"Oct 31","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"entertainment","blurb":"~6 km Nov-1 parade Chapultepec → Reforma → Zócalo; biggest live-culture moment","when":"Oct 31","commission":"DMC (Fora lane) — book weeks out","accessed":"2026-07-05"},{"name":"Xochimilco trajineras","si_tag":"Romance & Honeymoons","status":"live","hook":"colorful boats poled through UNESCO canals + floating gardens; mariachi afternoon","bookable_category":"private trajinera tour","tier":"comfort","commission_path":"affiliate ~8% (Viator private) or DMC","source":"https://www.viator.com/tours/Mexico-City/Private-Tour-in-Trajinera-through-the-Canals-of-Xochimilco/d628-289853P13 — Accessed 2026-07-05","timing":"Oct 31","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","blurb":"colorful boats poled through UNESCO canals + floating gardens; mariachi afternoon","when":"Oct 31","commission":"affiliate ~8% (Viator private) or DMC","accessed":"2026-07-05"},{"name":"Sunday Paseo de la Reforma (Muévete en Bici)","si_tag":"Romance & Honeymoons","status":"live","hook":"the grand boulevard closes to cars Sunday mornings for cyclists + walkers","bookable_category":"bike tour / self-guided","tier":"essential","commission_path":"affiliate","source":"https://www.casagoliana.com/blog/best-time-to-visit-mexico-city/ — Accessed 2026-07-05","timing":"Oct 31","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","blurb":"the grand boulevard closes to cars Sunday mornings for cyclists + walkers","when":"Oct 31","commission":"affiliate","accessed":"2026-07-05"},{"name":"Jacaranda-season Roma-Condesa stroll + rooftop dinner","si_tag":"Romance & Honeymoons","status":"live","hook":"Mar–Apr purple canopies over the prettiest neighborhoods + Polanco rooftop","bookable_category":"hotel + private guide + reservation","tier":"premier","commission_path":"DMC (Fora lane)","source":"https://www.casagoliana.com/blog/best-time-to-visit-mexico-city/ — Accessed 2026-07-05","timing":"Oct 31","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","blurb":"Mar–Apr purple canopies over the prettiest neighborhoods + Polanco rooftop","when":"Oct 31","commission":"DMC (Fora lane)","accessed":"2026-07-05"}],"faq":[{"q":"Is Mexico City safe to visit right now?","a":"Yes — freely bookable. CDMX carries a US State Dept **Level 2** advisory and is grouped with nationwide-L2 Mexico, NOT one of the six Level-4 \"Do Not Travel\" states. The realistic tourist risk is petty crime — pickpocketing on the Metro and in crowded plazas — so the single most-repeated local directive is to use ride-hail apps (Uber/DiDi), not street-hailed taxis.","source":"travel.state.gov, 2026-07-05","si_tag":"safety"},{"q":"Will the altitude affect me?","a":"It can for the first day or two. The city sits at **~2,240 m (7,349 ft)** — roughly 25% less oxygen than sea level — and most travelers need **24–72 hours** to acclimate; mild headache, fatigue and breathlessness are common on arrival from sea level and pass with rest, hydration and easing off alcohol on day one. Fitness and age do not predict susceptibility.","source":"nomadoc.com.mx, 2026-07-05","si_tag":"safety"},{"q":"Is Mexico City good for a romantic city break?","a":"Strongly — it''s the one live-launch SI that genuinely fits an inland capital. The romance lane is Polanco/Reforma luxe: the St. Regis atop the **31-story Torre Libertad**, the Sofitel''s **38th-floor pool**, rooftop dining, and the March–April jacaranda bloom that turns Roma-Condesa purple.","source":"blacklane.com / casagoliana.com, 2026-07-05","si_tag":"romance"},{"q":"What are the must-see culture sites, and is Teotihuacán worth it?","a":"Yes — the heritage circuit runs from the Museo Nacional de Antropología (the Aztec Sun Stone) and Templo Mayor beneath the Zócalo out to Teotihuacán, ~50 km northeast, best at dawn by private balloon (**$150–$300 USD**). It''s the single greatest day-trip from the city.","source":"mexicocity-tours.com, 2026-07-05","si_tag":"culture"},{"q":"Do I need reservations for Pujol and the top restaurants?","a":"Yes — book weeks ahead. Pujol (top-5 on Latin America''s 50 Best) and Quintonil sell their tasting menus out well in advance, and Casa Luis Barragán tickets release Tuesdays at noon CDMX time and sell out within minutes. Lock the marquee tables the moment the trip is confirmed.","source":"theinfatuation.com, 2026-07-05","si_tag":"culinary"},{"q":"Where''s the best nightlife and cocktail scene?","a":"Roma-Condesa. Licorería Limantour was named **Best Bar in North America in 2022 and 2023**, and the surrounding streets hold the city''s densest cluster of cocktail bars, mezcalerías and traditional pulquerías — best done as a guided crawl.","source":"mezcalistas.com, 2026-07-05","si_tag":"nightlife"},{"q":"When is Día de Muertos, and can I see the parade?","a":"Oct 31–Nov 2, with the Grand Parade on ~Nov 1 running **~6 km** from Chapultepec down Reforma to the Zócalo — the biggest live-culture moment of the CDMX year. Parade-corridor hotels (Centro/Reforma) tighten sharply through October, so book weeks out.","source":"casagoliana.com, 2026-07-05","si_tag":"entertainment"}],"seo":{"meta_title":"Mexico City (CDMX) Travel Guide 2026 — Culture, Food & Día de Muertos | TravelWell.World","meta_description":"Plan a Mexico City trip with TravelWell.World: when to go (Día de Muertos, jacaranda season), where to stay (Four Seasons to Roma villas), food and culture jewels, altitude and safety — all bookable.","slug":"mexico-city-mexico","primary_keyword":"Mexico City travel guide","long_tail":["best time to visit Mexico City","Día de Muertos Mexico City 2026","Mexico City altitude sickness","luxury hotels Polanco","Teotihuacán balloon day trip","Roma Condesa restaurants"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-05","search_language":"en + es-MX","local_keywords":["qué hacer en CDMX","Día de Muertos Ciudad de México","mejores restaurantes Roma Condesa","hoteles de lujo Polanco","globo aerostático Teotihuacán","mejor época para visitar la Ciudad de México"],"hreflang":["en","es-MX"]},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"romance","status":"live"},{"si":"culture","status":"future"},{"si":"culinary","status":"future"},{"si":"nightlife","status":"future"},{"si":"entertainment","status":"future"}],"ultra":[{"name":"Four Seasons Hotel Mexico City","why_ultra":"hacienda-style courtyard-oasis on Reforma; 240 rooms/40 suites; FS service benchmark","earning":"Four Seasons Preferred Partner / Virtuoso via host","virtuoso_value_add":"upgrade + daily breakfast + $100 credit + early/late (verify)","mor":"hotel/chain","tier":"ultra"},{"name":"St. Regis Mexico City","why_ultra":"31-story Torre Libertad; 189 rooms; butler service; best high-floor Reforma views","earning":"Marriott STARS/Luxury via host (Fora)","virtuoso_value_add":"STARS amenity: credit + upgrade + breakfast","mor":"hotel/chain","tier":"ultra"},{"name":"Las Alcobas (Luxury Collection, Polanco)","why_ultra":"Yabu Pushelberg 35-room jewel-box; butler; Anatol + Dulce","earning":"Marriott Luxury STARS/Luminous via host (Fora)","virtuoso_value_add":"STARS amenity","mor":"hotel/chain","tier":"premier-ultra"},{"name":"Sofitel Mexico City Reforma","why_ultra":"French-luxe, 38th-floor pool over the city; 275+56 suites","earning":"Accor Sofitel preferred / Virtuoso via host (Fora)","virtuoso_value_add":"preferred-partner amenity","mor":"hotel/chain","tier":"premier-luxury"},{"name":"Casa Polanco","why_ultra":"restored 1930s aristocratic residence; villa-like intimacy w/ hotel service","earning":"verify Virtuoso/preferred membership at booking","virtuoso_value_add":"TBD per program","mor":"hotel","tier":"premier-ultra"},{"name":"Pug Seal boutiques (Polanco)","why_ultra":"tiny art-filled design micro-hotels for boutique-over-grand ultra travelers","earning":"verify host/preferred program","virtuoso_value_add":"TBD","mor":"hotel","tier":"premier"}],"source_verified":"2026-07-05","hero":{"query":"Mexico City (CDMX), Mexico"},"geo":{"lat":19.4326,"lng":-99.1332}}'::jsonb, 69),
  ('monteverde-costa-rica', '10S', 'Monteverde', 'Costa Rica', 'The original cloud forest', 'live', 'verified', 'mountainValley', 'Costa Rica', '{"expedition","wildlife","romance"}', '{}', '{"essential","premier","ultra"}', null, null, '{"key_facts":["Birthplace of the commercial canopy zipline; Selvatura runs 13 ziplines incl. a 1 km line, 15 platforms, Tarzan swing, and 8 hanging bridges (51-170 m long, 12-60 m high).","Cloud forest protects 400+ bird species (resplendent quetzal, three-wattled bellbird), 2,500+ plants incl. 500+ orchids, 100+ mammals.","Three reserves: Monteverde Cloud Forest ($25, 7AM-4PM), Santa Elena (quieter, great quetzals), Curi-Cancha (least crowded, top birding).","Resplendent quetzal breeds Feb-Jun (peak Mar-Apr), best viewed 6-9 AM on wild-avocado trees.","Highland ~1,400 m; ~3-4 hr from SJO with a rough, partly-unpaved final mountain road; dengue risk low at elevation."],"safety":{"emergency":"911","nearest_clinic":"Santa Elena local clinics (minor/first response)","major_trauma":"San Jose hospitals (CIMA, Clinica Biblica), ~3-4 hr by road; air/ground evac pathway","advisory_level":"L2","advisory_reason":"Crime (petty nationwide; some violent crime, concentrated in specific San Jose neighborhoods)","advisory_issued":"2026-04-02","standard_caution":"No valuables in parked rental cars; registered operators; daylight driving on mountain road","activity_hazards":["zipline/canopy operator certification + harness/brakes + weight limits","mountain-road fog + unpaved sections (4WD, daylight)","night-walk footing + vipers (guided only)","wet suspension-bridge decking + heights"],"book_enabled":true,"air_access_verified":"SJO (Juan Santamaria) ~3-4 hr road; note rough/partly-unpaved access road","water":"Tap water generally potable including Monteverde area; bottled optional for sensitive travelers","dengue":"Low at ~1,400 m highland elevation; use repellent"},"timing":{"national_dry_peak":"mid-December to April","holiday_hard_peak":"late December","quetzal_breeding":"February to June/July, peak March-April","green_secret_season":"May-June (low crowds, birding-rich, misty year-round)","wettest_month":"October","curve_start_dry":"early-mid December","curve_start_quetzal":"early February","fire_date":"late November (~Nov 20-27) for dry/holiday; mid-late January (~Jan 20-27) for quetzal-birding","booking_lead":"60-90 days peak; 2-4 weeks green season","note":"misty year-round; peak demand != peak experience; sharpen on live tracking"},"jewels":[{"name":"Selvatura Park canopy + bridges","si_tag":"expedition","tier":"essential","commission_path":"Activities-Well direct or DMC bundle","source":"https://www.selvatura.com/","timing":"year-round","timing_type":"ALWAYS-ON","si":"expedition","when":"year-round","commission":"Activities-Well direct or DMC bundle"},{"name":"Sky Adventures (SkyTram/SkyTrek/SkyWalk)","si_tag":"expedition","tier":"essential","commission_path":"Activities-Well / DMC","source":"https://eternalarrival.com/ziplining-in-monteverde-canopy-tours/","si":"expedition","commission":"Activities-Well / DMC"},{"name":"100% Aventura (Superman ziplines)","si_tag":"expedition","tier":"essential","commission_path":"Activities-Well / DMC","source":"https://mytanfeet.com/activities/100-aventura-monteverde/","si":"expedition","commission":"Activities-Well / DMC"},{"name":"Guided night wildlife walk","si_tag":"expedition","tier":"essential","commission_path":"Activities-Well / DMC","source":"https://www.twoweeksincostarica.com/night-walk-monteverde/","hook":"uneven, wet, dark footing — guided only; wear grippy footwear, follow the guide''s beam, watch for vipers","si":"expedition","blurb":"uneven, wet, dark footing — guided only; wear grippy footwear, follow the guide''s beam, watch for vipers","commission":"Activities-Well / DMC"},{"name":"San Luis Waterfall","si_tag":"expedition","tier":"essential","commission_path":"DMC / guide","source":"https://www.airbnb.com/monteverde-costa-rica/stays/villas","si":"expedition","commission":"DMC / guide"},{"name":"Monteverde Cloud Forest Reserve (quetzal)","si_tag":"wildlife","tier":"essential","commission_path":"guide/DMC; entry non-commissionable","source":"https://monteverdetravel.com/quetzal-season-in-monteverde/","si":"wildlife","commission":"guide/DMC; entry non-commissionable"},{"name":"Santa Elena Reserve","si_tag":"wildlife","tier":"essential","commission_path":"guide/DMC; entry non-commissionable","source":"https://www.enjoycostarica.com/blog/monteverde-cloud-forest-a-complete-guide-for-nature-lovers/","si":"wildlife","commission":"guide/DMC; entry non-commissionable"},{"name":"Curi-Cancha Reserve","si_tag":"wildlife","tier":"essential","commission_path":"guide/DMC; entry non-commissionable","source":"https://mytanfeet.com/activities/birdwatching-at-curi-cancha-reserve/","si":"wildlife","commission":"guide/DMC; entry non-commissionable"},{"name":"Bat Jungle","si_tag":"wildlife","tier":"essential","commission_path":"affiliate/pass-through","source":"https://monteverdecostarica-info.weebly.com/monteverde-bat-jungle.html","si":"wildlife","commission":"affiliate/pass-through"},{"name":"Butterfly Garden + glass-frog vivarium","si_tag":"wildlife","tier":"essential","commission_path":"affiliate/pass-through","source":"https://tours.co.cr/activities-in-monteverde/","si":"wildlife","commission":"affiliate/pass-through"},{"name":"Monteverde Cheese Factory (La Lecheria) + coffee","si_tag":"wildlife","tier":"essential","commission_path":"DMC/guide add-on","source":"https://www.costarica-spirit.com/destinations/monteverde/","si":"wildlife","commission":"DMC/guide add-on"},{"name":"Hidden Canopy Treehouses (adults-only)","si_tag":"romance","tier":"premier","commission_path":"consortia/DMC","source":"https://www.enchantingtravels.com/hotels/monteverde/hidden-canopy-treehouse/","si":"romance","commission":"consortia/DMC"}],"faq":[{"q":"Which is the best zipline in Monteverde?","a":"It depends on your appetite. Selvatura''s flagship runs 13 ziplines including a 1 km line, 15 platforms, a Tarzan swing and 8 hanging bridges; 100% Aventura is the adrenaline pick with 11 ziplines including two Superman lines; Sky Adventures is the family-friendly tram-up, zip-down option.","source":"selvatura.com, 2026-07-06","si_tag":"expedition"},{"q":"When is quetzal season in Monteverde?","a":"Peak sightings run February–June (breeding), with March–April the sweet spot. Best hours are 6–9 AM, when males feed on wild avocado; a guided dawn quetzal walk (~$40–80, 2–3 hrs) is among Costa Rica''s best-value wildlife experiences.","source":"monteverdetravel.com, 2026-07-06","si_tag":"wildlife-&-nature-—-future"},{"q":"Is Monteverde good for a honeymoon?","a":"Yes — it''s a genuine eco-romance hub, not a beach substitute. Adults-only Hidden Canopy Treehouses are the honeymoon centerpiece, and Hotel Belmar offers Forest Superior rooms with a jacuzzi and private terrace for a mist-and-forest soak; both run boutique-luxe, not palace-scale.","source":"enchantingtravels.com, 2026-07-06","si_tag":"romance"},{"q":"Is Monteverde safe to visit right now?","a":"Yes — it''s one of Costa Rica''s safest highland zones. The country is at U.S. Level 2 — Exercise Increased Caution (reissued April 2, 2026, crime), with petty theft concentrated in specific San José neighborhoods rather than the cloud-forest reserves; use registered operators, keep valuables out of parked cars and drive the mountain road in daylight.","source":"travel.state.gov, 2026-07-06","si_tag":"safety"},{"q":"Is ziplining in Monteverde dangerous?","a":"It''s high-consequence if gear or technique fails, so ride only with certified operators. Confirm harness and dual-brake systems, helmet and stated weight limits before booking with Selvatura, Sky Adventures or 100% Aventura — high-speed lines and Superman/Tarzan configurations raise the stakes.","source":"selvatura.com, 2026-07-06","si_tag":"safety"},{"q":"How hard is the drive to Monteverde?","a":"It''s a real mountain climb. Monteverde sits at ~1,400 m, roughly 3–4 hours from Juan Santamaría (SJO), with the final stretch a rough, partly-unpaved and fog-prone road — drive in daylight, 4WD recommended, allow extra time.","source":"travel.state.gov, 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Monteverde Cloud Forest, Costa Rica: Quetzals, Ziplines & Cloud-Forest Lodges | TravelWell.World","meta_description":"Plan Monteverde - the original cloud-forest zipline, resplendent-quetzal birding, hanging bridges, night walks, and boutique eco-lodges. Best times, safety, and how to book.","long_tail_en":["Monteverde cloud forest guide 2026","best zipline in Monteverde","resplendent quetzal season Monteverde","Monteverde vs Santa Elena reserve","Monteverde hanging bridges","Monteverde night walk","luxury eco lodge Monteverde","how to get to Monteverde from San Jose","Monteverde honeymoon treehouse"],"search_language":"es-CR","local_keywords":["bosque nuboso Monteverde","canopy Monteverde","reserva Santa Elena","quetzal Monteverde temporada","puentes colgantes Monteverde","tour nocturno Monteverde","hoteles ecologicos Monteverde","como llegar a Monteverde"],"hreflang":["en","es-CR"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister - commercial pilot, 56 countries","content_freshness":"2026-07-06"},"booking":null,"si_checklist_25":null,"sis_present":["expedition","wildlife","romance"],"ultra":[{"name":"Hotel Belmar","type":"premier boutique eco-lodge","note":"CST level 5, first carbon-neutral in Monteverde, brewery, Nicoya Suites ~1000sqft, ~$270-1200/nt; Design Hotels + Mr&Mrs Smith listed; no confirmed Virtuoso","consortia":"Design Hotels / Mr & Mrs Smith / Fora","mor":"consortia commission or DMC block","tier":"premium-boutique (NOT ultra-palace)"},{"name":"Hidden Canopy Treehouses","type":"adults-only luxury treehouses","note":"R&H apex, secluded canopy","consortia":"consortia/DMC","mor":"consortia/DMC","tier":"premium-boutique"},{"name":"Senda Monteverde","type":"modern sustainable boutique","note":"private trails, farm-to-table","consortia":"consortia/DMC","mor":"consortia/DMC","tier":"premium-boutique"},{"name":"Koora Monteverde","type":"newest boutique eco-lodge","note":"26 rooms (10 suites/6 bungalows/10 forest)","consortia":"consortia/DMC","mor":"consortia/DMC","tier":"premium-boutique"}],"source_verified":"2026-07-06","hero":{"query":"Monteverde, Costa Rica"},"geo":{"lat":10.301,"lng":-84.8259}}'::jsonb, 70),
  ('nosara-costa-rica', '10S', 'Nosara & the Nicoya Peninsula', 'Costa Rica', '*If it''s sunrise vinyasa over a Blue Zone shore', 'live', 'verified', 'tropicalBeach', 'Costa Rica', '{"tropical","expedition","wellness"}', '{"tropical"}', '{"essential","comfort","premier","luxury","ultra"}', null, null, '{"key_facts":["Nicoya Peninsula is Costa Rica''s Blue Zone — historically ~3-4x the global centenarian rate (2013 study).","Playa Guiones (Nosara) offers consistent year-round surf — Nosara sees 300+ surfable days a year.","Ostional Wildlife Refuge (est. 1984) hosts olive-ridley arribadas of up to ~500,000 turtles, peaking Sep-Oct.","Santa Teresa / Mal Pais is the peninsula''s boho-luxury surf-and-sunset coast, remote southern tip.","LIR (Liberia) is ~2.5-3 hr drive to Nosara; Tambor (TMU) is a 25-min flight + 25-min drive to Santa Teresa."],"safety":{"emergency":"911","advisory_level":"L2","book_enabled":true,"air_access_verified":true,"nearest_trauma":"Nicoya town hospital (stabilize) -> CIMA Guanacaste (Liberia) / CIMA San Jose (major) -> air evac ($20k-$100k+) for extreme trauma","advisory_reasons":["crime (petty + violent)","deadly rip currents"],"riptide":"STRONG at Playa Guiones & Santa Teresa; swim only in guarded/designated zones","activity_fires":["surf/riptides (beginner Guiones vs advanced Santa Teresa)","ATV/quad on unpaved roads (leading local injury)","turtle arribada (guided-only, no lights)","waterfall jumping (Montezuma)"],"road_remoteness_flag":"Santa Teresa/Mal Pais — unpaved sections, green-season river crossings, slow trauma response","dengue":"present, wet-season peak","water":"potable in developed towns; bottled/filtered common in remote beach communities — verify locally"},"timing":{"curve_start":"late-Oct to early-Nov","peak":"mid-December to April (dry season)","shoulder":"May-June & November","green":"July-October (wet; bigger surf swell; arribada peak)","surf":"year-round; green-season swells bigger (counter-seasonal draw)","arribada":"year-round, peaks Jul-Nov (biggest Sep-Oct), lunar-timed near last-quarter & new moon","retreat_booking_lead":"3-6 months","fire_date":"mid-September"},"jewels":[{"name":"Playa Guiones surf","si_tag":"expedition","tier":"comfort","commission_path":"surf-school/retreat direct + affiliate","source":"https://www.vacationscostarica.com/nosara/","hook":"300+ day beach break; the beginner-to-intermediate teaching wave","si":"expedition","blurb":"300+ day beach break; the beginner-to-intermediate teaching wave","commission":"surf-school/retreat direct + affiliate"},{"name":"Nosara yoga core (Nosara Yoga Institute / Bodhi Tree / Harmony)","si_tag":"wellness","tier":"premier","commission_path":"retreat operator + BookYogaRetreats affiliate + hotel MoR","source":"https://bodhitreeyogaresort.com/","timing":"mid-December to April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the genuine, lived-in yoga capital: daily classes, teacher trainings, sound baths, healing/energy work","si":"wellness","blurb":"the genuine, lived-in yoga capital: daily classes, teacher trainings, sound baths, healing/energy work","when":"mid-December to April","commission":"retreat operator + BookYogaRetreats affiliate + hotel MoR"},{"name":"Ostional arribada","si_tag":"GEA (wildlife)","tier":"comfort","commission_path":"guided community tour + lodging MoR (refuge fee non-commissionable)","source":"https://www.wcanosara.org/arribadas","timing":"mid-December to April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Year-round but peaks Jul–Nov; events cluster on the ~28-day lunar cycle","si":"GEA (wildlife)","blurb":"Year-round but peaks Jul–Nov; events cluster on the ~28-day lunar cycle","when":"mid-December to April","commission":"guided community tour + lodging MoR (refuge fee non-commissionable)"},{"name":"Santa Teresa / Mal Pais surf + boho-luxe sunset","si_tag":"GEA/Romance","tier":"premier","commission_path":"villa/hotel MoR + DMC","source":"https://www.vacationscostarica.com/santa-teresa/rentals/","hook":"advanced swell coast + sunset-bar culture; the peninsula''s cool jewel","si":"GEA/Romance","blurb":"advanced swell coast + sunset-bar culture; the peninsula''s cool jewel","commission":"villa/hotel MoR + DMC"},{"name":"Montezuma waterfalls + Cabo Blanco reserve","si_tag":"expedition","tier":"essential","commission_path":"guided-tour affiliate + DMC","source":"https://www.twoweeksincostarica.com/cabo-blanco-nature-reserve/","hook":"challenging jungle trek to a white-sand reward beach; seabird + wildlife","si":"expedition","blurb":"challenging jungle trek to a white-sand reward beach; seabird + wildlife","commission":"guided-tour affiliate + DMC"},{"name":"Sámara calm-bay family beach","si_tag":"tropical","tier":"comfort","commission_path":"villa/hotel MoR + DMC transfer","source":"https://www.costaricarios.com/the-top-16-must-do-highlights-of-the-nicoya-peninsula/","si":"tropical","commission":"villa/hotel MoR + DMC transfer"},{"name":"Playa Barrigona (hidden)","si_tag":"tropical","tier":"premier","commission_path":"villa MoR + guided transfer","source":"https://www.costaricarios.com/the-top-16-must-do-highlights-of-the-nicoya-peninsula/","timing":"mid-December to April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"tropical","when":"mid-December to April","commission":"villa MoR + guided transfer"},{"name":"Sloth / howler jungle wildlife","si_tag":"expedition","tier":"comfort","commission_path":"guided-tour affiliate","source":"https://thetravnav.com/the-best-nosara-costa-rica-guide-things-to-do/","timing":"mid-December to April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Nosara/Cabo Blanco forests hold sloths, howler monkeys, scarlet macaws — guided wildlife walks","si":"expedition","blurb":"Nosara/Cabo Blanco forests hold sloths, howler monkeys, scarlet macaws — guided wildlife walks","when":"mid-December to April","commission":"guided-tour affiliate"},{"name":"Blue Zone longevity + food","si_tag":"wellness","tier":"comfort","commission_path":"culinary/wellness experience + retreat packages","source":"https://www.specialplacesofcostarica.com/blog/blue-zone-costa-rica-living-longer-living-better/","timing":"mid-December to April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"plant-forward Nicoyan diet, garden-to-table, longevity-lifestyle immersion; the destination''s signature intangible","si":"wellness","blurb":"plant-forward Nicoyan diet, garden-to-table, longevity-lifestyle immersion; the destination''s signature intangible","when":"mid-December to April","commission":"culinary/wellness experience + retreat packages"},{"name":"SUP the Nosara river estuary","si_tag":"expedition","tier":"comfort","commission_path":"outfitter affiliate","source":"https://thetravnav.com/the-best-nosara-costa-rica-guide-things-to-do/","timing":"mid-December to April","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"mangrove + birdlife paddle where the river meets Guiones; low-risk family adventure","si":"expedition","blurb":"mangrove + birdlife paddle where the river meets Guiones; low-risk family adventure","when":"mid-December to April","commission":"outfitter affiliate"}],"faq":[{"q":"Which Nicoya beach is best for families and calm swimming?","a":"Sámara is the pick. Its long horseshoe bay is calm and reef-protected, making it the peninsula''s safest swim and best family beach for kayaking, snorkeling and SUP — a gentler alternative to the surf breaks at Guiones and Santa Teresa.","source":"costaricarios.com, 2026-07-06","si_tag":"tropical"},{"q":"Is Nosara good for beginner surfers?","a":"Yes — Playa Guiones is a forgiving beach break with surf schools and whitewater, and Nosara sees 300+ surfable days a year, so beginners can learn nearly any day. Advanced surfers should head to the heavier point/reef swell at Santa Teresa / Mal País instead.","source":"vacationscostarica.com, 2026-07-06","si_tag":"expedition"},{"q":"When is the Ostional turtle arribada?","a":"Year-round, but it peaks Jul–Nov and is biggest Sep–Oct, when up to ~500,000 olive-ridleys come ashore. Events cluster on the ~28-day lunar cycle — around the last-quarter moon and the dark nights just before the new moon — and access is guided-only.","source":"volunteerlatinamerica.com, 2026-07-06","si_tag":"expedition"},{"q":"Is Nosara or Santa Teresa better for a honeymoon?","a":"Both work — pick your mood. Nosara pairs wellness-retreat honeymoons with its lived-in yoga scene; Santa Teresa / Mal País is the remote boho-luxury surf-and-sunset coast, with elite jungle-beach villas and barefoot-ultra properties like Latitude 10 for total privacy.","source":"vacationscostarica.com, 2026-07-06","si_tag":"romance"},{"q":"What is the Nicoya Blue Zone?","a":"It''s Costa Rica''s official Blue Zone — one of only five global longevity zones. A 2013 study found the region had roughly 3–4× the global proportion of centenarians, and Nosara''s yoga culture is local and lived-in, not imported for tourists.","source":"specialplacesofcostarica.com, 2026-07-06","si_tag":"wellness-&-spa-—-future"},{"q":"Is Nosara safe to visit right now?","a":"Yes, with standard caution. Costa Rica is U.S. Level 2 — Exercise Increased Caution (reissued April 2, 2026) for crime, and the advisory also flags deadly rip currents; don''t display wealth, avoid unlit beaches alone at night, don''t resist a robbery and secure valuables.","source":"travel.state.gov, 2026-07-06","si_tag":"safety"},{"q":"What''s the #1 safety risk on this coast?","a":"Rip currents. The State Department explicitly warns that dozens of U.S. citizens die yearly in Costa Rica surf, and both Guiones and Santa Teresa have strong riptides — swim only in designated/guarded areas and heed local surf-instructor guidance.","source":"travel.state.gov, 2026-07-06","si_tag":"safety"},{"q":"Can anyone watch the Ostional arribada?","a":"No — access is guided-only. Ostional is a community-managed refuge where guided access is mandatory, with no lights or flash and no touching, respecting nesting-window rules; unguided night beach access is both a wildlife-harm and personal-safety issue.","source":"wcanosara.org, 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Nosara & the Nicoya Peninsula, Costa Rica — Blue Zone Yoga, Surf & Turtle Coast | TravelWell.World","jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-06","search_language":"es-CR","local_keywords":["Nosara yoga surf","Santa Teresa Costa Rica","Península de Nicoya playas","arribada Ostional","Zona Azul Nicoya longevidad","retiro de yoga Nosara"],"hreflang":["en","es-CR"]},"booking":null,"si_checklist_25":null,"sis_present":["Tropical Islands & Beaches (LIVE)","GEA (LIVE)","Wellness & Spa (FUTURE)"],"ultra":[{"name":"Latitude 10 Exclusive Beach Resort","location":"Santa Teresa","tier":"ultra","path":"MoR + Fora/consortia amenity"},{"name":"Hotel Nantipa","location":"Santa Teresa","tier":"luxury-ultra","path":"SLH/consortia + MoR"},{"name":"The Harmony Hotel","location":"Nosara","tier":"luxury","path":"consortia + MoR"},{"name":"Bodhi Tree Yoga Resort","location":"Nosara","tier":"premier","path":"retreat operator + MoR"},{"name":"Nosara/Santa Teresa branded luxury villas","location":"Nicoya","tier":"ultra","path":"MoR"},{"name":"Nalu (Santa Teresa)","location":"Santa Teresa","tier":"luxury","path":"verify — thin sourcing"},{"name":"Origins Lodge / Kinkára","location":"VERIFY — likely NOT Nicoya","tier":"ultra","path":"excluded pending region confirmation"}],"source_verified":"2026-07-06","hero":{"query":"Nosara & the Nicoya Peninsula, Costa Rica"},"geo":{"lat":9.976,"lng":-85.653}}'::jsonb, 71),
  ('oaxaca-city-mexico', '10S', 'Oaxaca City & the Central Valleys', 'Mexico', 'High valley of mezcal and markets', 'live', 'verified', 'kyoto', 'Oaxaca (Oaxaca City & Coast)', '{"romance","expedition"}', '{}', '{"essential","comfort","premier","ultra"}', null, null, '{"key_facts":["Dual UNESCO World Heritage: Historic Centre of Oaxaca + Monte Alban, jointly inscribed 1987","Santiago Matatlan is the recognized World Capital of Mezcal, ~45 min SE on the Ruta Caminos del Mezcal","Teotitlan del Valle: ~2,500-year living Zapotec weaving tradition, natural cochineal/indigo/marigold dyes, rugs $75–$500","Tlacolula Sunday market: longest continuously running market in Mesoamerica, 1,000+ vendors","El Tule (Santa Maria del Tule): the world''s widest tree, a ~2,000-year-old Montezuma cypress"],"safety":{"emergency":"911","hospitals":["Clinica Hospital Carmen (Calle M. Abasolo 215)","Hospital Reforma (Calle Reforma 613)"],"medevac":"Air ambulance staged at OAX; serious cases transferred to Mexico City (MEX)","advisory_level":"L2","advisory_note":"State-wide Level 2; Oaxaca City / Monte Alban / Puerto Escondido / Huatulco explicitly carry no US-gov-employee restrictions","book_enabled":true,"tourist_zone_carveout":true,"air_access_verified":true,"airport":"OAX (Xoxocotlan International)","altitude_m":1555,"altitude_note":"~1,550–1,555 m (mild)","water":"bottled/purified","other_risks":["Hierve el Agua cliff-edge footing + periodic Jun–Oct closures","high-proof mezcal + rural driving (use driver)","high-valley UV/heat on all-day circuits"]},"timing":{"inflection_curve_start":"Late spring (Mar–May) for Oct 31–Nov 2 Dia de Muertos; intent stirs summer prior","peak":"Dia de Muertos Oct 31–Nov 2 (rates 2–3x, ~$150–250 USD/night centro); secondary peak Guelaguetza (2026: Jul 20 & Jul 27)","fire_date":"2026-03-10","shoulder":"Nov–Apr dry/high season (best weather)","green":"Jun–Sep wet/value (lush, lower rates) except the Jul Guelaguetza spike","booking_lead":"Dia de Muertos 4–8 months (5–6 mo / May–Jun = sweet spot); Guelaguetza 3–5 months","off_season_specials":"May (post-booking lull) and late Aug–Sep (deep green, lowest occupancy) for value + villa-rung pushes","event_peaks":["Dia de Muertos (Oct 31–Nov 2)","Guelaguetza (last two Mondays of July; 2026 Jul 20 & 27)","Noche de Rabanos (Dec 23)","Semana Santa (Mar/Apr, moving)"]},"jewels":[{"name":"Monte Alban","si_tag":"culture","tier":"essential","commission_path":"DMC/Viator half-day tour + 210 MXN INAH pass-through","source":"https://www.machupicchu.org/monte-alban-2026-complete-unesco-archaeological-guide.htm","timing":"Dia de Muertos Oct 31–Nov 2","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"Dia de Muertos Oct 31–Nov 2","commission":"DMC/Viator half-day tour + 210 MXN INAH pass-through"},{"name":"Mitla","si_tag":"culture","tier":"premier","commission_path":"valley-circuit private day tour + 210 MXN INAH pass-through","source":"https://montealbanoaxaca.com/inah-2026-entrance-fee-increases-for-monte-alban-mitla-and-other-oaxaca-archaeological-sites-updates-and-visitor-guide/","timing":"Dia de Muertos Oct 31–Nov 2","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"Dia de Muertos Oct 31–Nov 2","commission":"valley-circuit private day tour + 210 MXN INAH pass-through"},{"name":"Tlacolula Sunday market","si_tag":"culture","tier":"essential","commission_path":"Sunday-market + villages day tour (Viator/DMC)","source":"https://oaxacatraveltips.com/tlacolula-market-oaxaca/","timing":"Dia de Muertos Oct 31–Nov 2","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"Dia de Muertos Oct 31–Nov 2","commission":"Sunday-market + villages day tour (Viator/DMC)"},{"name":"Dia de Muertos panteones","si_tag":"culture","tier":"premier","commission_path":"lodging + guided-experience wave (peak booking window)","source":"https://www.mexicotravelandleisure.com/blog/day-of-the-dead-oaxaca/","timing":"Dia de Muertos Oct 31–Nov 2","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"Dia de Muertos Oct 31–Nov 2","commission":"lodging + guided-experience wave (peak booking window)"},{"name":"Guelaguetza","si_tag":"culture","tier":"premier","commission_path":"ticketed-auditorium + lodging packages via DMC","source":"https://oaxacatraveltips.com/oaxaca-guelaguetza-festival/","timing":"Dia de Muertos Oct 31–Nov 2","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"Dia de Muertos Oct 31–Nov 2","commission":"ticketed-auditorium + lodging packages via DMC"},{"name":"Noche de Rabanos (Dec 23)","si_tag":"culture","tier":"comfort","commission_path":"pre-Christmas lodging micro-spike (affiliate)","source":"https://en.wikipedia.org/wiki/Night_of_the_Radishes","timing":"Dia de Muertos Oct 31–Nov 2","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","when":"Dia de Muertos Oct 31–Nov 2","commission":"pre-Christmas lodging micro-spike (affiliate)"},{"name":"Casa Crespo cooking school","si_tag":"culinary","tier":"comfort","commission_path":"Cookly/Viator marketplace","source":"https://casacrespo.com/cooking-classes/","timing":"Dia de Muertos Oct 31–Nov 2","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","when":"Dia de Muertos Oct 31–Nov 2","commission":"Cookly/Viator marketplace"},{"name":"Mole negro tasting circuit","si_tag":"culinary","tier":"comfort","commission_path":"culinary day-tour / cooking-class attach","source":"https://www.fiestamericanatravelty.com/en/grand-fiesta-americana/hotels/grand-fiesta-americana-oaxaca","timing":"Dia de Muertos Oct 31–Nov 2","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culinary","when":"Dia de Muertos Oct 31–Nov 2","commission":"culinary day-tour / cooking-class attach"},{"name":"Hierve el Agua","si_tag":"expedition","tier":"essential","commission_path":"guided valley day-trip + ~50 MXN entry pass-through (VERIFY OPEN)","source":"https://www.mexicotravelandleisure.com/blog/hierve-el-agua-oaxaca/","timing":"Dia de Muertos Oct 31–Nov 2","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"~50 MXN site entry + separate communal road toll + ~30 MXN parking, cash only, no on-site ATM. Non-commissionable","si":"expedition","blurb":"~50 MXN site entry + separate communal road toll + ~30 MXN parking, cash only, no on-site ATM. Non-commissionable","when":"Dia de Muertos Oct 31–Nov 2","commission":"guided valley day-trip + ~50 MXN entry pass-through (VERIFY OPEN)"},{"name":"Santiago Matatlan mezcal route","si_tag":"expedition","tier":"premier","commission_path":"guided mezcal-route tour (DMC/Viator); bottles non-commissionable","source":"https://www.oaxaca-mio.com/mezcalesdeoaxaca/matatlan.htm","timing":"Dia de Muertos Oct 31–Nov 2","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","when":"Dia de Muertos Oct 31–Nov 2","commission":"guided mezcal-route tour (DMC/Viator); bottles non-commissionable"},{"name":"El Tule (world''s widest tree)","si_tag":"expedition","tier":"essential","commission_path":"bundled into valley-circuit tour","source":"https://culturestraveled.com/hierve-el-agua-oaxaca/","timing":"Dia de Muertos Oct 31–Nov 2","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"At Santa María del Tule, ~20 minutes from the city","si":"expedition","blurb":"At Santa María del Tule, ~20 minutes from the city","when":"Dia de Muertos Oct 31–Nov 2","commission":"bundled into valley-circuit tour"},{"name":"Teotitlan del Valle weavers","si_tag":"romance","tier":"premier","commission_path":"private artisan-village tour (DMC); rug purchases direct-to-artisan","source":"https://brokenbootstravel.com/the-travelers-guide-to-teotitlan-del-valle/","timing":"Dia de Muertos Oct 31–Nov 2","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"Dia de Muertos Oct 31–Nov 2","commission":"private artisan-village tour (DMC); rug purchases direct-to-artisan"},{"name":"San Bartolo Coyotepec black pottery","si_tag":"romance","tier":"essential","commission_path":"south-valley artisan tour (DMC)","source":"https://theculturetrip.com/north-america/mexico/articles/a-tour-of-oaxacas-best-markets","timing":"Dia de Muertos Oct 31–Nov 2","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"Dia de Muertos Oct 31–Nov 2","commission":"south-valley artisan tour (DMC)"},{"name":"Alebrijes at San Martin Tilcajete","si_tag":"romance","tier":"comfort","commission_path":"artisan-workshop tour + hotel alebrije programming","source":"https://www.fiestamericanatravelty.com/en/grand-fiesta-americana/hotels/grand-fiesta-americana-oaxaca","timing":"Dia de Muertos Oct 31–Nov 2","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"romance","when":"Dia de Muertos Oct 31–Nov 2","commission":"artisan-workshop tour + hotel alebrije programming"}],"faq":[{"q":"Is Oaxaca City safe to visit right now?","a":"Yes — the book path is open. Oaxaca is a **Level 2** state, and the advisory explicitly names Oaxaca City / Monte Albán / Puerto Escondido / Huatulco as carrying no US-gov-employee restrictions. The realistic Centro risk is petty/opportunistic theft; the serious-crime concerns are rural-corridor, not the city center.","source":"travel.state.gov, 2026-07-05","si_tag":"safety"},{"q":"What''s the real risk to plan for?","a":"Terrain and high-proof spirits, not crime. The city is a mild **~1,555 m** (light first-day breathlessness at most); the genuine hazards are Hierve el Agua''s cliff-edge footing above a canyon and the mezcal route — high-proof tastings plus rural highway driving mean you take a driver or DMC, never self-drive after tasting.","source":"oaxacalife.com, 2026-07-05","si_tag":"safety"},{"q":"When is Día de Muertos, and how far ahead do I book?","a":"Oct 31–Nov 2, and it''s the longest lead time in the inland catalog: book **4–8 months ahead** (5–6 months / May–June is the sweet spot). Walkable-Centro rooms are ~95% booked by early September and rates run **2–3× normal** ($150–250 USD/night).","source":"mexicotravelandleisure.com / wheregoesrose.com, 2026-07-05","si_tag":"culture"},{"q":"Is Oaxaca really a top food destination?","a":"Yes — it''s widely regarded as one of the world''s great food capitals. The \"seven moles,\" market-to-table cooking schools (Casa Crespo), and the mezcal terroir of Santiago Matatlán (~45 minutes southeast, the World Capital of Mezcal) are destination-defining reasons to go.","source":"oaxaca-mio.com, 2026-07-05","si_tag":"culinary"},{"q":"Is Hierve el Agua worth it — and will it be open?","a":"Worth it, but verify first. The petrified mineral \"waterfalls\" and clifftop spring-fed pools sit 70 km east near Mitla, but the site sees **periodic community-dispute closures clustering June–October** — always confirm it''s open the week before, and keep a Mitla + Tlacolula fallback ready.","source":"mexicotravelandleisure.com, 2026-07-05","si_tag":"expedition"},{"q":"Is Oaxaca good for couples?","a":"Yes — a slow, sensory, non-beach romance. Boutique casonas and the ex-convent (1576) Quinta Real, mezcal-tasting date nights, and the artisan-village shopping ritual (Teotitlán weaving, rugs $75–$500; San Bartolo black pottery; alebrijes) make the case.","source":"caminoreal.com / brokenbootstravel.com, 2026-07-05","si_tag":"romance"}],"seo":{"meta_title":"Oaxaca City & the Central Valleys, Mexico — UNESCO, Mezcal, Dia de Muertos & Monte Alban | TravelWell.World","search_language":["en","es-MX"],"local_keywords":["Dia de Muertos Oaxaca","que hacer en Oaxaca","ruta del mezcal","Guelaguetza fechas","Monte Alban precio entrada","Hierve el Agua abierto","hoteles boutique Oaxaca centro","Noche de Rabanos"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-05"},"booking":null,"si_checklist_25":null,"sis_present":["romance","expedition"],"ultra":[{"name":"Quinta Real Oaxaca","positioning":"ex-Convent of Santa Catalina (1576), 91 rooms, UNESCO Centre","earning_path":"consortia/Virtuoso + Fora lane","mor":"hotel","tier":"ultra"},{"name":"Escondido Oaxaca","positioning":"Grupo Habita design-boutique, rooftop pool","earning_path":"Grupo Habita direct + consortia/Fora","mor":"hotel","tier":"ultra"},{"name":"Pug Seal Oaxaca","positioning":"top-cited Centro design-boutique","earning_path":"consortia/Fora","mor":"hotel","tier":"ultra"},{"name":"Hotel Sin Nombre","positioning":"intimate quiet-luxury design hotel","earning_path":"Fora/direct","mor":"hotel","tier":"ultra"},{"name":"Casa Antonieta","positioning":"9-room boutique casona, affordable-ultra entry","earning_path":"OTA + boutique-collection/Fora","mor":"hotel","tier":"premier"}],"source_verified":"2026-07-05","hero":{"query":"Oaxaca City & the Central Valleys, Mexico"},"geo":{"lat":17.0732,"lng":-96.7266}}'::jsonb, 72),
  ('ometepe-island-nicaragua', '10S', 'Ometepe Island, Nicaragua', 'Nicaragua', 'Ometepe Island', 'live', 'verified', 'mountainValley', 'Nicaragua', '{"wellness"}', '{}', '{"essential"}', 'essential', null, '{"key_facts":null,"safety":{"emergency":"118","emergency_fire":"128","book_enabled":false,"bin":"NO SAFE ZONE (content-only)","content_only":true,"redirect_eligible":true,"consent_flow":false,"founder_review_flag":"Political wrongful-detention risk may not register with typical leisure travelers; requires deliberate founder + compliance-attorney review before any Book path — do not soft-open on demand alone","remote_flag":true,"trauma_note":"No trauma care on-island; comprehensive care only in Managua; serious cases → Managua → US medical evacuation; long transfer times from lake island"},"timing":{"peak":"Dry season Dec–Apr (clear skies, passable hiking trails; March standout)","inflection":"Peak volume December; late-Nov/early-Dec good weather pre-rush; Nov–Feb choppy lake winds","off_season":"May–Nov green/wet — muddy trails, clouded summits","fire_date":"held — pending advisory clearance + founder/attorney"},"jewels":[{"name":"Volcán Concepción summit (1,610 m)","si_tag":"expedition","tier":"essential","commission_path":"dormant","source":"https://ometepenicaragua.com/volcanoes/","timing":"Dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"Nicaragua''s second-highest volcano and one of the most perfectly formed cones in the Americas; a serious dawn climb. price","si":"expedition","blurb":"Nicaragua''s second-highest volcano and one of the most perfectly formed cones in the Americas; a serious dawn climb. price","when":"Dry season Dec–Apr","commission":"dormant"},{"name":"Volcán Maderas summit + crater lagoon (1,394 m)","si_tag":"expedition","tier":"essential","commission_path":"dormant","source":"https://ometepenicaragua.com/volcanoes/","timing":"Dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"dormant cone crowned by cloud forest and a still crater lake you can swim in. price","si":"expedition","blurb":"dormant cone crowned by cloud forest and a still crater lake you can swim in. price","when":"Dry season Dec–Apr","commission":"dormant"},{"name":"Río Istián kayak","si_tag":"expedition","tier":"essential","commission_path":"dormant","source":"https://ometepenicaragua.com/istian/index.php","hook":"moderate · guided/rental. ~4-hr paddle from Mérida through wetland channels; wildlife-rich; watch lake wind on the open-water leg","si":"expedition","blurb":"moderate · guided/rental. ~4-hr paddle from Mérida through wetland channels; wildlife-rich; watch lake wind on the open-water leg","commission":"dormant"},{"name":"San Ramón waterfall (64 m)","si_tag":"expedition","tier":"essential","commission_path":"dormant","source":"https://www.theselvistaexperience.com/hiking-san-ramon-waterfall","hook":"moderate hike. ~64 m fall on Maderas above Mérida, with a swimming pool beneath","si":"expedition","blurb":"moderate hike. ~64 m fall on Maderas above Mérida, with a swimming pool beneath","commission":"dormant"},{"name":"Punta Jesús María sandbar","si_tag":"expedition","tier":"essential","commission_path":"dormant","source":"https://ometepenicaragua.com/charcoverde/index.php","timing":"Dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"long sandbar spit reaching into the lake, framed views of both volcanoes; classic sunset point. price","si":"expedition","blurb":"long sandbar spit reaching into the lake, framed views of both volcanoes; classic sunset point. price","when":"Dry season Dec–Apr","commission":"dormant"},{"name":"Ojo de Agua natural spring","si_tag":"wellness","tier":"essential","commission_path":"dormant","source":"https://ometepenicaragua.com/volcanoes/","timing":"Dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"underground-fed mineral swimming holes between the volcanoes; the island''s slow-morning ritual. price","si":"wellness","blurb":"underground-fed mineral swimming holes between the volcanoes; the island''s slow-morning ritual. price","when":"Dry season Dec–Apr","commission":"dormant"},{"name":"Charco Verde Nature Reserve","si_tag":"wellness","tier":"essential","commission_path":"dormant","source":"https://travelmademedoit.com/charco-verde-ometepe/","timing":"Dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"algae-green lagoon and lake beaches on Concepción''s south side, with the Mirador del Diablo lookout above. price","si":"wellness","blurb":"algae-green lagoon and lake beaches on Concepción''s south side, with the Mirador del Diablo lookout above. price","when":"Dry season Dec–Apr","commission":"dormant"},{"name":"Pre-Columbian petroglyphs (1,700+)","si_tag":"Culture/Romance","tier":"essential","commission_path":"dormant","source":"https://www.dreambigtravelfarblog.com/blog/ometepe-nicaragua","timing":"Dry season Dec–Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"1,700+ carvings across 100+ sites; densest at Finca Magdalena; half-submerged carved stones near Tichana past San Ramón. price","si":"Culture/Romance","blurb":"1,700+ carvings across 100+ sites; densest at Finca Magdalena; half-submerged carved stones near Tichana past San Ramón. price","when":"Dry season Dec–Apr","commission":"dormant"}],"faq":[{"q":"What makes Ometepe Island special?","a":"Ometepe is the largest island in a freshwater lake in the world and a UNESCO Biosphere Reserve since 2010, formed by two volcanoes — active Concepción (1,610 m) and dormant Maderas (1,394 m) — joined by the Isthmus of Istián across roughly 276 km². It also holds over 1,700 pre-Columbian petroglyphs across more than 100 documented sites.","source":"en.unesco.org; lacgeo.com, Accessed 2026-07-07","si_tag":"expedition"},{"q":"How hard are the Ometepe volcano hikes?","a":"Both are serious. Concepción is a strenuous ~10-hour dawn-start climb; Maderas is ~8 hours via a ~4.5 km trail from Balgüe / Finca Magdalena, with a crater lagoon you can swim in at the summit. A licensed local guide is mandatory for both because the upper slopes are exposed, muddy, and cloud-forest-slick.","source":"ometepenicaragua.com; alongdustyroads.com, Accessed 2026-07-07","si_tag":"expedition"},{"q":"Where can you swim on Ometepe?","a":"Ojo de Agua (\"eye of the water\") is the island''s signature spot — a natural mineral swimming hole fed by an underground river originating on Volcán Maderas, about 2 km from Santo Domingo. Go early or late to avoid crowds. Maderas'' summit crater lagoon and designated lake beaches are the other locally advised swims.","source":"ometepenicaragua.com, Accessed 2026-07-07","si_tag":"wellness"},{"q":"Where do couples stay on Ometepe?","a":"Ometepe skews to off-grid eco-lodges rather than resorts. Totoco Eco-Lodge (8 design cabins on Maderas'' slopes, lake-and-Concepción views, farm-to-table dining), Finca del Sol (a 100% sustainable eco-lodge with permaculture farm), and Hacienda Mérida give the quiet, unscripted, two-people-and-a-volcano energy.","source":"steppestravel.com; hotelfincadelsol.com, Accessed 2026-07-07","si_tag":"romance"},{"q":"Is Ometepe Island, Nicaragua safe to visit right now?","a":"Not on a bookable basis. Nicaragua carries a US State Department Level 3 — Reconsider Travel advisory, reissued May 14, 2026. The risk is country-wide, government-driven wrongful detention and arbitrary enforcement of law, with no geographic carve-out for travelers — the only carve-outs cover US-government-employee driving in the Managua/Masaya corridor, not tourists. TravelWell keeps the Book path OFF.","source":"travel.state.gov, Accessed 2026-07-07","si_tag":"safety"},{"q":"What''s the real risk to plan for?","a":"Two things: political detention and remoteness. Per the State Department, US nationals face serious risk of wrongful detention, exit bans, and detentions of weeks-plus, with some crimes carrying 50+ year sentences. And there is no trauma-grade care on-island — comprehensive care exists only in Managua, so a serious case realistically means Managua then a US medical evacuation.","source":"travel.state.gov, Accessed 2026-07-07","si_tag":"safety"},{"q":"Is climbing an active volcano here dangerous?","a":"Concepción is an active stratovolcano (its last significant ash event was March 2010), and its summit hike is strenuous, exposed, and dawn-started; Maderas is dormant but steep, muddy, and cloud-forest-slick. A licensed guide is mandatory on both, and you should check volcanic status before going — though all of this fires as content only under the Level 3 advisory.","source":"ometepenicaragua.com, Accessed 2026-07-07","si_tag":"safety"}],"seo":{"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","freshness":"2026-07-07","search_language":"es-NI","local_keywords":["Isla de Ometepe qué hacer","Volcán Concepción","Volcán Maderas laguna cráter","Ojo de Agua Ometepe","cascada San Ramón Ometepe","kayak Río Istián","petroglifos Ometepe","ferry San Jorge Ometepe"],"hreflang":["en","es-NI"],"primary_keyword":"Ometepe Island"},"booking":null,"si_checklist_25":null,"sis_present":[{"si":"wellness","status":"live"}],"ultra":[{"name":"Totoco Eco-Lodge","location":"Balgüe","price_tier":"mid/boutique-eco","commission_path":"dormant","source":"https://www.steppestravel.com/accommodation/totoco-eco-lodge/"},{"name":"Finca del Sol Eco Lodge","location":"Maderas base","price_tier":"mid/eco","commission_path":"dormant","source":"https://hotelfincadelsol.com/"},{"name":"Hacienda Mérida","location":"Mérida","price_tier":"value/mid","commission_path":"dormant","source":"https://www.hmerida.com/espanol/activity/1"}],"source_verified":null,"hero":{"query":"Ometepe Island, Nicaragua, Nicaragua"},"geo":{"lat":11.5,"lng":-85.5833}}'::jsonb, 73),
  ('osa-peninsula-corcovado-costa-rica', '10S', 'Osa Peninsula / Corcovado', 'Costa Rica', 'Corcovado rainforest at the continent''s edge', 'live', 'verified', 'mountainValley', 'Costa Rica', '{"expedition","diveglobal"}', '{}', '{"comfort","premier","ultra"}', null, null, '{"key_facts":["Corcovado holds 2.5% of the world''s biodiversity in 41,800 hectares — ''the most biologically intense place on Earth'' (National Geographic)","Certified guide LEGALLY MANDATORY for all Corcovado entry (SINAC rule since Feb 1 2014)","Caño Island is Costa Rica''s #2 dive site (after Cocos), 30–100+ ft viz, capped at 120 visitors/day","Cocos Island = liveaboard-only pilgrimage, ~36-hr sail from Puntarenas, world''s most consistent schooling hammerheads","Golfo Dulce is one of only four tropical fjords on Earth and hosts BOTH hemispheres'' humpback populations"],"safety":{"emergency":"911","advisory_level":"L2","book_enabled":true,"air_access_verified":true,"air_access":"SJO → Drake Bay (DRK) / Puerto Jiménez (PJM) daily small-strip flights (~40–45 min); or 6–8 hr overland 4×4 drive","remote_flag":true,"medevac_note":"Deep-rural; nearest clinic Puerto Jiménez → San José for major care; Sirena has no road; Cocos ~36 hr by sea","hazards":["tide-timed river crossings (crocodile + bull shark at Rio Sirena/Rio Claro mouths)","jungle heat/humidity","Pacific rip currents","venomous snakes (fer-de-lance)","no-fly-after-diving (Caño + Cocos)"],"malaria":"low but present in region; Corcovado itself generally not a malaria concern — consult travel clinic","dengue":"primary mosquito risk; spikes May–Nov rainy season (CR 31,000+ cases 2024)","water":"potable in serviced areas; follow lodge guidance in deep-Osa"},"timing":{"terrestrial_peak":"mid-Dec–Apr (dry, Corcovado access best)","green_season":"May–Nov (lush, some lodge closures, access degrades)","whale_season":"Jul–Nov Southern humpback (prime late Aug–Sep) + Nov–Feb Northern humpback","cocos_hammerhead_peak":"Jun–Dec","curve_start":"early-mid December","fire_date":"late November (curve-start − 1–2 wks); secondary early-July for whale+hammerhead","booking_lead":"eco-lodges 3–6 mo; Sirena permits 3–4 mo; Cocos liveaboard 6–18 mo","sharpen_note":"sharpen on live tracking — windows drift year to year"},"jewels":[{"name":"Sirena Ranger Station, Corcovado","si_tag":"expedition","highlight":"tapir ~70% overnight, all 4 monkey species, scarlet macaw near-guaranteed, peccary herds 30+","tier":"premier","commission_path":"guided trek + Sirena overnight via DMC; margin on guide service","source":"https://vamosrentacar.com/blog/corcovado-national-park-sirena-station/","si":"expedition","commission":"guided trek + Sirena overnight via DMC; margin on guide service"},{"name":"Caño Island Biological Reserve","si_tag":"diveglobal","highlight":"CR #2 dive site, 30–100+ ft viz, sharks/rays/turtles, 120-pax/day cap","tier":"premier","commission_path":"day-dive/snorkel net-rate/referral","source":"https://www.entercostarica.com/attractions/national-parks-and-refuges/cano-island","si":"diveglobal","commission":"day-dive/snorkel net-rate/referral"},{"name":"Cocos Island National Park (UNESCO)","si_tag":"diveglobal","highlight":"world''s most consistent schooling hammerheads; liveaboard-only, 36-hr sail from Puntarenas","tier":"ultra","commission_path":"own CLIA/DLA lane (Aggressor/Undersea Hunter)","source":"https://www.aggressor.com/destination/Cocos","si":"diveglobal","commission":"own CLIA/DLA lane (Aggressor/Undersea Hunter)"},{"name":"Golfo Dulce (tropical fjord)","si_tag":"WILDLIFE_NATURE/RHN","highlight":"one of 4 tropical fjords on Earth; both hemispheres'' humpbacks; dolphins, mangroves","tier":"premier","commission_path":"lodge-bundled boat tour","source":"https://www.nicuesalodge.com/blog/witness-the-wonder-humpback-migration-in-costa-ricas-golfo-dulce","si":"WILDLIFE_NATURE/RHN","commission":"lodge-bundled boat tour"},{"name":"Drake Bay","si_tag":"DIVE/GEA","highlight":"northern-Osa gateway to Caño Island + Corcovado San Pedrillo; sportfishing, night tours","tier":"comfort","commission_path":"lodge + activity referral","source":"https://www.copadearbol.com/osa-peninsula-eco-lodge/","si":"DIVE/GEA","commission":"lodge + activity referral"},{"name":"Puerto Jiménez","si_tag":"expedition","highlight":"frontier town + PJM airstrip; Golfo Dulce + southern Corcovado gateway","tier":"comfort","commission_path":"gateway nights + transfers","source":"https://mytanfeet.com/driving-in-costa-rica/puerto-jimenez-osa-peninsula/","si":"expedition","commission":"gateway nights + transfers"},{"name":"Matapalo surf & waterfalls","si_tag":"expedition","highlight":"secluded breaks + jungle cascades at peninsula tip","tier":"comfort","commission_path":"lodge-bundled excursion","source":"https://www.crsurfzone.com/corcovado-national-park.html","si":"expedition","commission":"lodge-bundled excursion"},{"name":"Whale-watching, Golfo Dulce","si_tag":"WILDLIFE_NATURE","highlight":"both hemispheres'' humpbacks (Jul–Nov Southern + Nov–Feb Northern)","tier":"premier","commission_path":"guided boat referral","source":"https://www.nicuesalodge.com/blog/witness-the-wonder-humpback-migration-in-costa-ricas-golfo-dulce","si":"wildlife","commission":"guided boat referral"},{"name":"Cacao finca / farm-to-bar chocolate","si_tag":"expedition","highlight":"Indigenous + smallholder cacao experience","tier":"comfort","commission_path":"referral","source":"https://www.osawild.travel/locations/","si":"expedition","commission":"referral"}],"faq":[{"q":"Do you need a guide to hike Corcovado National Park?","a":"Yes — a certified guide is legally mandatory for all Corcovado entry, a SINAC rule in force since February 1, 2014 and enforced at every ranger station, where unguided visitors are turned away. Build the guided-trek product; there is no compliant self-guided version to sell.","source":"Wikipedia — Corcovado National Park, 2026-07-06","si_tag":"expedition"},{"q":"Can you dive Cocos Island on a day trip?","a":"No. Cocos is liveaboard-only — it lies ~342 mi off the Pacific coast, an ~36-hr open-ocean crossing from Puntarenas, and is sold as 8/10/12-night charters (15/21/27 dives) via Aggressor or Undersea Hunter. Berths book 6–18 months out, so plan far ahead.","source":"aggressor.com, 2026-07-06","si_tag":"diveglobal"},{"q":"Are the Osa eco-lodges right for a honeymoon?","a":"Yes — the Osa is honeymoon-grade seclusion without the resort cliché: private-reserve bungalows over the Pacific, canopy suites and no Wi-Fi. Lapa Rios alone offers 16 ocean-view bungalows across 1,000 protected acres, and remote lodges bundle meals, guided excursions and transfers by necessity.","source":"laparios.com, 2026-07-06","si_tag":"romance"},{"q":"When can you see whales in Golfo Dulce?","a":"Golfo Dulce — one of only four tropical fjords on Earth — draws both hemispheres'' humpbacks, so the season is unusually long: Southern-hemisphere humpbacks calve July–November (prime late Aug–Sept), and Northern-hemisphere humpbacks arrive November–February.","source":"nicuesalodge.com, 2026-07-06","si_tag":"wildlife"},{"q":"Is the Osa safe to book right now?","a":"Yes, with eyes open. Costa Rica is U.S. State Department Level 2 — Exercise Increased Caution for crime (advisory maintained April 2026), and TWW keeps `book_enabled = true` under standard L2 posture: stay aware, don''t display wealth, don''t resist a robbery.","source":"travel.state.gov, 2026-07-06","si_tag":"safety"},{"q":"What''s the real risk to plan for on a Corcovado trek?","a":"The tide-timed river crossings. Rio Sirena and Rio Claro are the most dangerous, with American crocodiles and bull sharks patrolling the river mouths, so guides cross only at low tide and never in storms. This — plus jungle heat and deep-remote medevac — is the true gatekeeper, above petty crime.","source":"crsurfzone.com, 2026-07-06","si_tag":"safety"},{"q":"Is diving Cocos Island dangerous?","a":"It is advanced diving in a strong-current, deeply remote environment. DAN membership and dive insurance are essential, no-fly-after-diving surface intervals apply, and because the site is ~36 hr from land the vessel itself is the only evacuation. Not a first-timer''s trip.","source":"aggressor.com, 2026-07-06","si_tag":"safety"}],"seo":{"meta_title":"Osa Peninsula & Corcovado, Costa Rica — The Most Biologically Intense Place on Earth | TravelWell.World","search_language":"es-CR","local_keywords":["Parque Nacional Corcovado","Península de Osa","Isla del Coco buceo","Bahía Drake","Golfo Dulce ballenas","Puerto Jiménez"],"long_tail_en":["Corcovado guided tour","Sirena station Corcovado","Caño Island diving Drake Bay","Cocos Island liveaboard hammerhead","Osa Peninsula luxury eco lodge","Golfo Dulce whale watching"],"hreflang":["en","es-CR"],"jsonld_type":"TouristDestination","author_byline":"By David McCallister — commercial pilot, 56 countries","content_freshness":"2026-07-06"},"booking":null,"si_checklist_25":null,"sis_present":["expedition","diveglobal"],"ultra":[{"name":"Lapa Rios","operator":"Böëna / Cayuga Collection","location":"above Corcovado","earn":"Virtuoso/consortia; AoR via ST Costa Rica DMC","tier":"ultra"},{"name":"El Remanso","location":"Puerto Jiménez / private beach","earn":"Virtuoso/consortia + full-property buyout","tier":"ultra"},{"name":"Copa de Árbol","location":"Drake Bay","earn":"consortia","tier":"ultra"},{"name":"Playa Cativo","location":"Golfo Dulce","earn":"consortia + private-reserve buyout","tier":"ultra"},{"name":"Aguila de Osa","location":"Drake Bay","earn":"consortia + Caño Island dive referral","tier":"ULTRA/PREMIUM"},{"name":"Cocos private liveaboard charter","operator":"Aggressor / Undersea Hunter","earn":"own CLIA/DLA lane — AoR/MoR via DLA relationship","tier":"ultra"},{"name":"Kasiiya Papagayo","correction":"in GUANACASTE, not Osa — do not sell as Osa property","tier":"N/A"}],"source_verified":"2026-07-06","hero":{"query":"Osa Peninsula / Corcovado, Costa Rica"},"geo":{"lat":8.54,"lng":-83.5